# -*- coding: utf-8 -*-
"""Локальный ПРЕ-ФИЛЬТР перед вызовом API — экономит токены.

До обращения к модели решает: engage (вести диалог) / refuse (не наш профиль) /
deflect (слить дубль). На refuse и deflect отдаёт готовый ШАБЛОН без вызова шлюза —
слитый лид стоит 0 токенов. Только stdlib, никаких нейросетей.

Детект дубля — по телефону (надёжно) и по идентичному тексту обращения (рано, до
телефона). Активная заявка в CRM по телефону — хук active_zayavka() (подключим на #5).
"""
import re

# ---- ОТКАЗ: не наш профиль (жёсткий отказ без сверки — только эти случаи) ----
_REFUSE = [
    # ГАЗ = отказ только про газовое ОБОРУДОВАНИЕ/подключение. Голое «газов*» ловило «собрать кухню
    # с газовой столешницей» (сборка мебели — берём!) — кейс заказчика 29.07.
    # ⚠ 12.08: «кот[Ё]л» через ё мимо регекса — «газовый котёл» шёл модели вместо отказа
    ("газ", re.compile(r"газов\w*\s*(?:плит|панел|поверхн|колонк|котл|кот[её]л|духовк|шкаф\w*\s*дух|"
                       r"оборудован|водонагрев|бойлер|шланг|труб|горелк|конфорк|варочн)|"
                       r"(?:плит|панел|поверхн|колонк|кот[её]л|котл|духовк|варочн|бойлер)\w*\s*(?:на\s*)?газ\w*|"
                       r"подключ\w*.{0,20}\bгаз|\bгаз\w{0,3}\s*(?:подключ|провести|утечк)|"
                       r"(?:пахнет|воняет|запах)\s*газ|утечк\w*\s*газ"),
     "газовое оборудование не обслуживаем"),
    # ⚠ СКУПКА ПРОВЕРЯЕТСЯ РАНЬШЕ МАТРИЦЫ (снимок владельца 26.08, вечер). Клиент писал:
    # «есть два телевизора… кошка уронила, на обоих не работает экран. Интересует на
    # запчасти?» — он ПРЕДЛАГАЛ технику, а не просил ремонт. Матрица стояла в списке выше
    # и перебивала скупку: бот отвечал «Экраны не меняю, к сожалению», клиент поправлял
    # «не правильно поняли, вам нужны на запчасти?».
    # ⚠ ЗАМЕР ПОКАЗАЛ, ЧТО СЛУЧАЙ НЕ ЕДИНИЧНЫЙ. На 9742 первых сообщениях со скупкой
    # совпадают 114 (1,17 %), и в 33 из них ЕСТЬ признаки матрицы — то есть каждый третий
    # такой клиент получал ответ не в тему. Живые мастера в этих же диалогах отвечают
    # ровно скупкой: «на запчасти не беру тв», «телевизор на продажу я не беру, я по
    # ремонту», «здравствуйте, нет».
    # Порядок и есть решение: если человек продаёт, неважно, что у него сломано.
    # Газ остаётся выше — там отказ ещё и про безопасность.
    ("скупка", re.compile(r"\bна\s*запчаст|скупк|выкуп\w*\s*(?:техник|телевизор|ноутбук|компьютер|у\s*вас)|"
                          r"выкупаете|скупаете|прода[мю]\w*\s*(?:нерабоч|неисправ|сломанн|битый|разбит)|"
                          r"занимает\w*\s*продаж|\bпрода[ёе]те\b|продаж\w*\s*(?:б/?у|техник|машин)|"
                          r"прода\w*\s*на\s*запчаст|берёте\w*\s*на\s*запчаст|берете\w*\s*на\s*запчаст"),
     "скупкой техники не занимаемся"),
    ("матрица", re.compile(r"матриц|разбит\w*\s*экран|экран\w*\s*разбит|треснул\w*\s*экран|"
                           # ⚠ ЗАМЕНА ЭКРАНА = ЗАМЕНА МАТРИЦЫ (слова владельца 29.08 по
                           # боевому диалогу Волгодонска: «замена экрана это то же самое,
                           # что замена матрицы, а с матрицей мы не работаем»). Требуем
                           # рядом ТВ: замену экрана НОУТБУКА берём (гард ниже), телефона —
                           # отдельная тема согласования, не отказ по матрице.
                           r"(?:помен|замен|смен)\w*[^.!?\n]{0,20}экран\w*[^.!?\n]{0,40}"
                           r"(?:телевизор|телек\b|\bтв\b|плазм)|"
                           r"(?:телевизор|телек\b|\bтв\b|плазм)\w*[^.!?\n]{0,40}"
                           r"(?:помен|замен|смен)\w*[^.!?\n]{0,20}экран|"
                           r"экран\w*[^.!?\n]{0,16}(?:помен|замен|смен)\w*[^.!?\n]{0,40}"
                           r"(?:телевизор|телек\b|\bтв\b|плазм)|"
                           r"полос\w*.{0,22}экран|экран\w*.{0,22}полос|вертикальн\w*\s*полос|горизонтальн\w*\s*полос|"
                           # ⚠ ПОЛОСЫ БЕЗ СЛОВА «ЭКРАН» (сверка регламента 30.08, №5):
                           # «полосы на ЖК телевизоре» проходило к модели. Регламент,
                           # дополнение п.2: полосы на ТВ = матрица. Операторы корпуса
                           # на полосах отказывали в 71 % и не брали никогда.
                           # ⚠ ГРАНИЦА СЛОВА И ОТРИЦАНИЕ С ОБЕИХ СТОРОН (аудит 30.08):
                           # «двухПОЛОСные колонки» матчились внутри слова, «показывает
                           # БЕЗ полос» — в альтернативе телевизор→полосы.
                           r"(?<![а-яё])полос\w*(?!\w*\s+нет)(?<!без\sполос).{0,26}(?:телевизор|телек\b|\bтв\b|плазм)|"
                           r"(?:телевизор|телек\b|\bтв\b|плазм)\w*.{0,26}(?<!без\s)(?<![а-яё])полос\w*(?!\s*нет)|"
                           r"рябит\s*экран|битые\s*пиксел|"
                           # ⚠ ПРИЧИНА ТОЖЕ ОТКАЗ: ТВ УРОНИЛИ, УДАРИЛИ ИЛИ ЗАЛИЛИ (26.08).
                           # Регламент отказывает по разбитой матрице, но клиент почти
                           # никогда не говорит «матрица» — он говорит, ЧТО СЛУЧИЛОСЬ:
                           # «на него упал шкаф», «ребёнок бросил игрушку», «попала вода».
                           # Замер живого корпуса: 63 таких первички, оператор отказал в
                           # 71 %, ВЗЯЛ в 0 %; остальные 29 % — мягкие отказы («нет смысла
                           # ремонтировать») и встречный вопрос «не били, не роняли его?».
                           # Бот же брал такое в работу ВСЕГДА — то есть отправлял мастера
                           # в заведомо пустой выезд. Это тот самый вопрос про анамнез,
                           # который владелец просил добавить 26.08: без вывода из ответа
                           # сам вопрос ничего не стоил.
                           # ⚠ ОКНО В 120 ЗНАКОВ И ЧЕРЕЗ ТОЧКУ: живое «возможно ли спасти
                           # телевизор? На него упал шкаф» — две разные фразы.
                           # ⚠ МОНИТОР СЮДА НЕ ВХОДИТ НАМЕРЕННО: отказ по матрице объявлен только для ЖК ТВ,
                           # а матрица монитора и моноблока — обычная работа КП (гард ниже
                           # снимает отказ по `_MONITOR_RX`, и спорить с ним незачем).
                           r"(?:телевизор|телек\b|\bтв\b|плазм)[\s\S]{0,120}"
                           r"(?<![а-яё])(?:упал|упало|упала|урон|уронил|ударил|ударили|"
                           r"бросил|бросили|кинул|кинули|зали[лвт]|намок|пролил|затопил|разбил\w*)|"
                           r"(?:попал\w*\s+вода|вода\s+попал\w*)[\s\S]{0,120}"
                           r"(?:телевизор|телек\b|\bтв\b|плазм)|"
                           r"(?:телевизор|телек\b|\bтв\b|плазм)[\s\S]{0,120}"
                           r"(?:попал\w*\s+вода|вода\s+попал\w*)|"
                           r"(?<![а-яё])(?:упал|упало|упала|урон|уронил|ударил|ударили|"
                           r"бросил|бросили|кинул|кинули|зали[лвт]|намок|пролил|затопил|разбил)"
                           r"\w*[\s\S]{0,120}(?:телевизор|телек\b|\bтв\b|плазм)"),
     "разбитая матрица/полосы — не наш профиль"),
    # формы «вскрОЙте/вскрЫтие замкА» и «дверь захлопнулась» добраны 02.08 — раньше ловилась
    # только пара «вскрыт…замок»; исход теперь сверка-передача, ложное срабатывание не страшно
    # ⚠ «замОк» НЕ содержит подстроки «замк» — нужны обе основы (зам(?:ок|к))
    # ⚠ 12.08: «вскроете замок» и «ключи потерял» проходили мимо — формы глагола и обратный
    # порядок слов. Это отказ, прямо подтверждённый регламентом, пропуски тут недопустимы.
    # ⚠⚠ 12.08, ВТОРАЯ ПРАВКА ЗА ДЕНЬ. Первая («ключи потерял» = отказ) оказалась хуже
    # исходной дыры: «потеряли ключи, надо замок ЗАМЕНИТЬ» уходило в окончательный отказ,
    # хотя замена замка — обычная работа из прайса МНЧ (межкомнатные 2500, входные 5000).
    # Регламент отказывает только ВСКРЫТИЮ: «Вскрытием замков мы не занимаемся». Поэтому
    # потерянные ключи и захлопнутая дверь считаются отказом ТОЛЬКО без просьбы о замене
    # или установке — иначе это заказ, а не вскрытие.
    ("замок", re.compile(r"вскр(?:ыт|ой|ыв|ыл|о[еюя])\w*\s*зам(?:ок|к)|зам(?:ок|к)\w*\s*вскр|"
                         r"открыть\s*дверь\s*без\s*ключ|"
                         r"выбит\w*\s*дверь|потерял\w*\s*ключ|ключ\w*\s*потерял|"
                         r"захлопнул\w*\s*дверь|дверь\s*захлопнул"),
     "вскрытие замков не делаем — сверка и передача"),
    # ГАРД \b у «на запчаст»: без него подстрока ловилась внутри обычных слов — «цеНА запчасти»,
    # «нужНА запчасть», «заменА запчасти» → живой лид на ремонт получал «На запчасти не беру».
    # Та же болезнь, что лечили у «анальн» и «\bтв\b». Проверять границу слова ВСЕГДА.
    # ⚠ F-009 (слепая сверка этапа 4): ловилось только «скупаете», а «вы занимаетесь
    # ПРОДАЖЕЙ б/у машин?» и «продаёте бу стиральные?» уходили модели — и та тянула
    # «сверюсь по графику» вместо честного «продажами не занимаюсь». Ветку закрывают
    # быстро не из вредности: по корпусу у скупки конверсия 5.7% против базы 11.5%,
    # держать такого клиента ожиданием — терять и его время, и своё.
    # ГАРД \b у «анальн/вагинальн»: без него ветка ловила «бАНАЛЬНо» и «кАНАЛЬНый» (многоканальный
    # видеорегистратор, канальный кондиционер) → мгновенный отказ живому лиду. Точность была 0/2.
    ("интим", re.compile(r"вибратор|секс[\s\-]?игруш|интимн|дилдо|мастурбатор|фаллоимитатор|"
                         r"\bанальн|\bвагинальн|\bпорно|секс-товар|игрушк\w*\s*для\s*взросл"),
     "интимные товары — не наш профиль"),
    # заправка = отказ (правило заказчика). ГАРД: «не печатает ПОСЛЕ заправки» = РЕМОНТ, берём —
    # lookbehind «после » не даёт роутеру сожрать принимаемый кейс.
    # КАРТРИДЖИ (регламент КЦ 08.12.2025): заправка / ремонт / ЗАМЕНА / прошивка картриджа —
    # больше НЕ согласование, а прямой отказ. Ремонт САМОГО принтера по-прежнему берём,
    # поэтому «не печатает после заправки» гардом (?<!после ) остаётся принимаемым кейсом.
    # ⚠ МЕЖДУ «ЗАПРАВКОЙ» И «КАРТРИДЖЕМ» БЫВАЮТ СЛОВА (снимки владельца 26.08). Шаблон
    # требовал их вплотную, и живое «заправка ВЕРНО-БЕЛОГО картриджа» проходило мимо: тема
    # не опознавалась, ход уходил модели, и на двух наших аккаунтах ОДИН клиент получил два
    # разных ответа — «сверюсь по графику» и «лучше в сервис заправки обратиться».
    # Регламент (матрица, строки 436 и 935): картриджи — сверка-передача, бывший отказ.
    ("заправка", re.compile(r"(?<!после )заправ(?:ить|ьте|те|ка|ку|кой|ляете|ите)\s*"
                            r"(?:\S+\s+){0,3}?(?:ка(?:рт|т)ридж|тонер|принтер)|"
                            r"ка(?:рт|т)ридж\w*\s*(?:нужно\s*|не\s*)?заправ(?:ить|ляете|ите|к)(?!\w*\s*не\s*печата)|"
                            r"(?:замен|помен|ремонт|почин|отремонт|прошив|прошить)\w*\s*(?:ка(?:рт|т)ридж|тонер)|"
                            r"ка(?:рт|т)ридж\w*\s*(?:замен|помен|ремонт|почин|прошив)"),
     "картриджи (заправка/ремонт/замена/прошивка) — не наш профиль, только ремонт принтеров"),
    # ПРАВИЛО ЗАКАЗЧИКА 01.08.2026: замена батареек в пульте — не ремонт, не выезжаем.
    # ⚠ ТОЛЬКО связка батарейка+пульт: «подключение и настройка пульта к ТВ» — регламентная
    # РАБОТА (п.7 ТВ), её ловит гард _REMOTE_RX; телевизор рядом = смесь, разберёт модель.
    ("батарейка пульта", re.compile(
        r"батарейк\w*[^.!?]{0,30}пульт|пульт\w*[^.!?]{0,30}батарейк"),
     "замена батареек в пульте — не ремонт, по регламенту не выезжаем"),
    # ПРАВИЛО ЗАКАЗЧИКА 01.08.2026: аккумуляторы/батареи самокатов не меняем.
    ("аккумулятор самоката", re.compile(
        r"(?:аккумулятор|батаре)\w*[^.!?]{0,40}(?:электро)?самокат|"
        r"(?:электро)?самокат\w*[^.!?]{0,40}(?:аккумулятор|батаре)"),
     "аккумуляторы самокатов — не наш профиль"),
    # П.12 РЕГЛАМЕНТА (решение заказчика 15.08): на МНЧ вне компетенции можно вежливо
    # отказать. Список УЗКИЙ и заведомо не наш ни в одном направлении — уличные и
    # капитальные работы; сомнительное и «Прочая» по-прежнему уходят сверкой.
    # ⚠ «копать» голым не ловим — «копаться в настройках» съело бы живой КП-лид;
    # снос СТЕН не здесь — перепланировка это партнёр 740, комплексные работы.
    ("мнч-непрофиль", re.compile(
        r"кровл\w*|перекрыть\s+крышу|крыш\w*\s+перекр|"
        r"асфальт|тротуарн\w*\s+плитк|дорожн\w*\s+(?:работ|покрыт)|"
        # ⚠ КОЛОДЕЦ САМ ПО СЕБЕ — НЕ ОТКАЗ (аудит 18.08). Копка колодца вне
        # компетенции, а «насос в колодце не качает», «почистить колодец»,
        # «кольцо просело» — обычные МНЧ-заявки, которые регламент велит брать.
        # Отказываем только когда речь именно о КОПКЕ.
        r"выкопа\w*|копк\w*|транше\w*|(?:копать|выкопать|бурить|бурен\w*)\s+колодц?\w*|"
        r"колодц?\w*\s+(?:выкопа|копа|бури)\w*|"
        # ⚠ «ПОКОСИТЬ» — НЕ ТОЛЬКО ТРАВА (боевой диалог 30.08, Самара, партнёр 723).
        # Объявление про ремонт ПК, бот уже сказал «такое лечим», назвал цену и спросил
        # адрес — а на реплике «главное ПОКОСИТЬ вирус» голый корень выдал отказ п.12
        # «боюсь, это не ко мне» и закрыл живой КП-лид. Клиент ответил дословно:
        # «Вы ж только что готовы были». В речи «покосить» сплошь и рядом значит
        # «извести, снести», а «перекосило», «покосившийся шкаф» — вообще про другое.
        # Теперь требуем ТО, ЧТО КОСЯТ. Пропущенный отказ дойдёт до человека, ложный
        # выбрасывает лид — цена ошибок разная.
        # Левую границу (?<![а-яё]) не снимать: без неё ловится «перекосило».
        r"спил\w*\s+дерев|"
        r"(?<![а-яё])покос(?:[ае]|ом|у)?\b|"                       # именной покос: «нужен покос участка»
        r"(?<![а-яё])(?:по|с|вы|за)?кос(?:ить|ит|ите|им|ил[аио]?|ят|ю)\s+(?:\S+\s+){0,2}?"
        # «поля» в списке нет намеренно: «косит ПОЛЕ зрения», «поле ввода», «поле в форме»
        # частотнее в наших диалогах, чем покос поля.
        r"(?:трав|газон|бурьян|сорняк|поросл|лужайк|участок|огород|борщевик)|"
        r"снос\w*\s+(?:дом|здани|построй)|построить\s+(?:дом|гараж|бан[юи]|сарай)|\bсруб\b"),
     "вид работ вне компетенции МНЧ (регламент, п.12 от 15.08)"),
    # ТЕЛЕФОНЫ/ПЛАНШЕТЫ (регламент КЦ 06.04.2026): ремонт/прошивка/разблокировка — БЫЛО
    # согласование, СТАЛО отказ «таким не занимаюсь».
    # ⚠ Дыра из регрессии 01.08: «\bсколько стоит ДИСПЛЕЙ на айфон 10 ПОМЕНЯТЬ и акб» проходила
    # мимо (нет «дисплей»/«акб», обратный порядок слов) — модель ПРИНИМАЛА ремонт телефона.
    # Добавлены: запчасть ПЕРЕД телефоном («дисплей на айфон»), телефон ПЕРЕД глаголом замены
    # («айфон 10 поменять»). Гарды: «стекл» в запчасть-перед-телефоном НЕ кладём (наклейка
    # защитного стекла — своя соглас-ветка); после слова «телефон» не должно идти 6+ цифр
    # (это КОНТАКТ клиента: «поменять розетку, телефон 89…» — живой лид, не ремонт трубки).
    # ⚠ ПЛАНШЕТЫ ОТДЕЛЕНЫ ОТ ТЕЛЕФОНОВ (решение владельца В-004, 19.08). Объявление
    # 11.12.2025: ремонт планшета — ПО СОГЛАСОВАНИЮ; объявление 06.04.2026 про отказ
    # касалось ТОЛЬКО телефонов. Раньше оба лежали в одном классе и планшет отшивался
    # вместе с трубкой. Класс стоит ВЫШЕ телефонного: первый матч побеждает.
    ("планшеты", re.compile(
        r"(?:разбил|разбит|треснул|не\s*включ|не\s*заряж|не\s*работает\s*экран|"
        r"замен\w*\s*(?:экран|стекл|дисплей|батаре|аккум|\bакб\b|матриц|крышк)|"
        r"ремонт|почин|отремонт|прошив\w*|разблокир|разлочит).{0,25}"
        r"(?:планшет|ipad|айпад)|"
        r"(?:планшет|ipad|айпад)\w*[^.!?]{0,30}"
        # ⚠ ГЛАГОЛ ПОСЛЕ ПРЕДМЕТА (боевой диалог 30.08, Чита): «Планшеты айпады
        # РЕМОНТИРУЕТЕ?» шёл мимо — в хвостовом списке были «почин|отремонт», а голого
        # «ремонт»/«чините» не было, и модель принимала согласуемую тему первым же ходом.
        r"(?:не\s*включ|не\s*заряж|разбит|треснул|ремонт|почин|отремонт|чинит|прошит|разблокир|"
        r"замен\w*\s*(?:экран|стекл|дисплей|батаре|аккум)|помен)"),
     "ремонт планшетов — по согласованию с филиалом"),
    ("телефоны", re.compile(
        r"(?:прошить|перепрошить|перепрошивк\w*|прошивк\w*)\s+(?:\w+\s+){0,2}(?:телефон|айфон|iphone|смартфон)|" r"(?:разбил|разбит|треснул|не\s*включ|не\s*работает\s*экран|"
        r"замен\w*\s*(?:экран|стекл|дисплей|батаре|аккум|\bакб\b|матриц|крышк)|"
        r"ремонт|почин|отремонт|прошив\w*|разблокир|разлочит).{0,20}"
        r"(?:телефон|айфон|iphone|смартфон|планшет|ipad)|"
        # ⚠ в связке «запчасть → телефон»: (?<!номер )телефон — «на весь экран рамка с введите
        # НОМЕР ТЕЛЕФОНА» это настройка КИОН, живой лид; телефон(?!ом) — «В экран попали
        # ТЕЛЕФОНОМ» это разбитый ТВ, телефон лишь предмет удара (оба из корпуса, 01.08)
        r"(?:экран|дисплей|батаре[йюяе]|аккумулятор|\bакб\b|матриц|задн\w*\s*крышк)\w*[^.!?]{0,30}"
        r"(?:(?<!номер )(?<!номера )телефон(?!ом\b|ами\b)(?!\w*\s*(?:номер\w*\s*)?\+?[78(]?\d{6})|"
        r"айфон|iphone|смартфон|планшет|ipad)|"
        r"(?:телефон(?!\w*\s*(?:номер\w*\s*)?\+?[78(]?\d{6})|айфон|iphone|смартфон|планшет|ipad)"
        r"[^.!?]{0,25}(?:замен|помен|смен)\w*\s*(?:и\s+)?(?:экран|стекл|дисплей|батаре|аккум|"
        r"\bакб\b|матриц|крышк)|"
        r"(?:телефон|айфон|iphone|смартфон|планшет|ipad)\w*\s*"
        r"(?:не\s*включ|разбит|треснул|почин|отремонт|прошит|разблокир|"
        r"замен\w*\s*(?:экран|стекл|дисплей|батаре|аккум)|(?:\d{1,3}\s*)?помен)"),
     "ремонт телефонов и планшетов не делаем"),
    # СПУТНИКОВОЕ ТВ (регламент КЦ 06.03.2026): настройка/подключение спутниковой антенны —
    # БЫЛО согласование, СТАЛО отказ. Обычная эфирная/наружная антенна остаётся в согласовании.
    ("спутниковое ТВ", re.compile(
        r"спутников\w*\s*(?:тв|телевид|антенн|тарелк|канал)|(?:антенн|тарелк)\w*\s*спутников|"
        r"триколор|нтв[\s-]?плюс|телекарт\w*\s*спутник"),
     "спутниковое телевидение не подключаем"),
]

