# ── ЧЁРНЫЙ СПИСОК ПРОФИЛЕЙ (канал «Правила Авито», 24.03 и 11.06.2026) ───────────
# «НОВАЯ / БЫВАЛЫЙ / PIFAGOR / АЛЕКСАНДР-БЕРЕЗНИКИ»: пишут НАМЕРЕННО, чтобы оставить
# негативный отзыв на профиль. Правило от 11.06: «ОТВЕЧАТЬ ТАКЖЕ НЕ НУЖНО, ПОЛНЫЙ ИГНОР».
# Сверяем ИМЯ ПРОФИЛЯ целиком, а не подстроку: «Новая» — обычное слово, и внутри чужих
# имён («Александра») ловиться не должно.
_BLOCKLIST = {"новая", "бывалый", "pifagor", "пифагор", "александр-березники",
              "александр березники"}


# ПРЕДОХРАНИТЕЛЬ ReDoS (отчёт защиты wz7eelqy4 + ТЗ 3.2): простыня в 12 КБ загоняла
# квадратичные регексы в ~10 с CPU и стопорила ВСЕ диалоги. Классификации хватает начала
# текста: простыни длиннее и так уходят модели (гард len>180 в согласованиях). Историю
# для МОДЕЛИ никто не режет — только вход регекс-слоя.
_MAX_SCAN = 3000


def _cap(text):
    return (text or "")[:_MAX_SCAN]


def check_blocklist(visitor_name):
    """Профиль из чёрного списка → молчим и отдаём человеку (0 токенов)."""
    n = (visitor_name or "").strip().lower().replace("ё", "е")
    n = re.sub(r"\s{2,}", " ", n)
    if n and n in _BLOCKLIST:
        return {"kind": "blocklist", "sub": n, "reason": "профиль из чёрного списка Авито",
                "draft": ""}
    return None
