# ── ОБЯЗАТЕЛЬНАЯ ДЕТАЛЬ К СОГЛАСУЕМЫМ ТЕМАМ (регламент «Уточнять…») ──────────────
# Шаблон согласования отдаётся ДО модели (0 токенов), поэтому правило плейбука «собери одну деталь»
# на этих ходах физически не срабатывает — оператор получал заявку без того, что регламент требует.
# Здесь тот же шаблон + ОДИН короткий вопрос, если клиент это ещё не сказал сам.
_AREA_RX = re.compile(r"\d\s*(?:м2|м²|кв|квадрат|метр)")
_PEST_RX = re.compile(r"таракан|клоп|муравь|блох|моль|мошк|грызун|мыш|крыс")


def _disinfection_q(t):
    """Спрашиваем только то, чего клиент ещё не сказал."""
    has_area, has_pest = bool(_AREA_RX.search(t)), bool(_PEST_RX.search(t))
    if has_area and has_pest:
        return None
    if has_pest:
        return "Какая площадь помещения?"
    if has_area:
        return "А кто именно завёлся?"
    return "Какая площадь и кто именно завёлся?"


# (тема, регекс-признак темы внутри ветки, вопрос ИЛИ функция(текст)->вопрос, регекс «уже ответил»).
# Функция сама решает, чего не хватает, — так мы не переспрашиваем уже сказанное.
_SOGLAS_DETAIL = [
    ("кондиционер/вытяжка/наружная антенна", re.compile(r"вытяжк"),
     "Она у вас на кухне или в ванной?", re.compile(r"кухн|ванн|санузл|туалет")),
    ("кондиционер/вытяжка/наружная антенна", re.compile(r"кондицион|сплит"),
     "Какой этаж и к наружному блоку подобраться можно?", re.compile(r"этаж|балкон|\d\s*эт")),
    # деталь регламента «НАРУЖНАЯ АНТЕННА — на крыше или на стене» (сверка матрицы 04.08:
    # оператор получал заявку без неё)
    ("кондиционер/вытяжка/наружная антенна", re.compile(r"антенн"),
     "Антенна на крыше или на стене?", re.compile(r"крыш|стен|фасад|балкон|этаж")),
    # iCloud: квалификатор регламента «данные сохранились?» — с данными это прямой приём
    # (гард в _soglas_taken отпустит тему на следующем ходе), без данных — согласование
    # ⚠ «доступ/данные» в answered нельзя: «восстановить ДОСТУП» — это сама проблема, не ответ
    ("разблокировка iCloud без данных", re.compile(r"."),
     "Пароль и почта от аккаунта сохранились?", re.compile(r"парол|почт|логин")),
    ("восстановление из iCloud/WhatsApp/Telegram", re.compile(r"icloud|айклауд|аккаунт"),
     "Пароль и почта от аккаунта сохранились?", re.compile(r"парол|почт|логин")),
    # дезинфекция: регламент требует И квадратуру, И вид насекомых — спрашиваем ТОЛЬКО недостающее
    # (переспрашивать уже сказанное клиенту нельзя, это отдельное правило заказчика)
    ("дезинфекция", re.compile(r"."), _disinfection_q, None),
    ("светодиодный светильник", re.compile(r"."),
     "Какая высота потолка и потолок натяжной?", re.compile(r"высот|натяжн|\d\s*м\b|метр")),
]


#: ⚠ ЦЕНА ПО ЗАПРОСУ В СОГЛАС-ТЕМАХ (решение 30.08 по хвосту №10 аудита). Регламент
#: прямо велит озвучивать «от N», когда клиент спрашивает цену («Кондиционеры п.2:
#: заправка фреоном от 2000 — озвучиваем, если клиент спрашивает»); соглас-шаблон же
#: отвечал «подъеду, гляну» без цифры — клиент, спросивший цену, не получал её никогда.
#: Только позиции, где регламент даёт цифру ПРЯМО; остальным темам цифру не выдумываем.
_SOGLAS_PRICE = {
    "кондиционер/вытяжка/наружная антенна": {
        "строка": "заправка фреоном — от 2000",
        "предмет": r"фреон|заправ|хладагент",
    },
}
_ДЕНЕЖНЫЙ_ВОПРОС_RX = re.compile(
    r"(?<![а-яё])сколько|цена|цену|стоит|стоимост|почём|почем|прайс|расценк",
    re.IGNORECASE)


def soglas_price_line(kind, text):
    """Строка цены для соглас-темы, если клиент спросил о деньгах и регламент цифру даёт."""
    п = _SOGLAS_PRICE.get(kind)
    if not п or not _ДЕНЕЖНЫЙ_ВОПРОС_RX.search(text or ""):
        return None
    if not re.search(п["предмет"], (text or "").lower()):
        return None
    return "По деньгам " + п["строка"] + ", точнее скажу после сверки"


def soglas_detail_q(kind, text):
    """Один уточняющий вопрос к согласуемой теме, если клиент сам его не закрыл."""
    t = _cap(text).lower()
    for k, topic_rx, question, answered_rx in _SOGLAS_DETAIL:
        if k != kind or not topic_rx.search(t):
            continue
        if callable(question):
            q = question(t)
            if q:
                return q
            continue
        if not answered_rx.search(t):
            return question
    return None


def _soglas_taken(kind, t):
    """True, если гард отпускает тему НАВСЕГДА: это наша работа, согласования не требуется.
    Такие темы модели подсказывать НЕЛЬЗЯ — иначе вернутся ложные согласования, которые
    эти же гарды и лечили (кронштейн, прошивка принтера, засор, iCloud с данными)."""
    # ⚠ «ОПТИКА» СНИМАЕТСЯ, КОГДА КЛИЕНТ ЕЁ САМ ОТВЕРГАЕТ ИЛИ РЕЧЬ ПРО ТЕРМИНАЛ
    # (проверка корпуса 30.08). «Хз, кабель от роутера, врятли оптика» — клиент
    # говорит, что это НЕ оптика; «купил оптический терминал, можно подключить?» —
    # подключение терминала при проведённой оптике это настройка роутера, наша
    # работа без согласования. Работа с самим кабелем (варить, обжать, погрызла)
    # остаётся согласованием.
    # «виндовс, чтобы ПОДДЕРЖИВАЛА 1с» — цель совместимости при установке ОС, а не
    # работа с 1с (сверка регламента 30.08): lookbehind в регексе не дотягивается
    # через слово «программу», потому проверка живёт здесь.
    # ⚠ СУЖЕНО АУДИТОМ 30.08: голое «поддержива» ловило вопрос клиента «а вы такое
    # поддерживаете?». Снимаем только в контексте ОС («виндовс, чтобы поддерживала 1с»).
    # учреждение как ОРИЕНТИР или ЖИЛЬЁ клиента — не заказчик (аудит 30.08):
    # «возле школы», «рядом с садиком», «живу в общежитии, кран течёт»
    if kind == "бригада/учреждение/юрлицо" and re.search(
            r"(?:возле|около|рядом\s*с|напротив|у)\s+(?:школ|садик|детск|общежити|больниц|"
            r"поликлиник|гостиниц)|жив[уё]\w*\s+в\s+общежити|котельн\w*\s+пер", t):
        return True
    if kind == "узкопрофильное ПО" and re.search(
            r"(?:винд|windows|систем|\bос\b)\w*[^.!?\n]{0,40}(?:поддержива|совместим)"
            r"|(?:поддержива|совместим)\w*[^.!?\n]{0,40}(?:винд|windows|систем)", t):
        return True
    # ⚠ СУЖЕНО АУДИТОМ 30.08: голое «терминал» гасило согласование на «перебили оптику
    # возле терминала» — а работа с самим кабелем остаётся согласованием.
    if kind == "оптоволокно" and re.search(
            r"врятли|вряд\s*ли|наверн\w*\s+не|не\s+оптик"
            r"|(?:подключ|настро|установ)\w*[^.!?\n]{0,24}терминал"
            r"|терминал\w*[^.!?\n]{0,24}(?:подключ|настро|установ)", t):
        return True
    # чистый ЗАСОР без работ по трубам — наша работа, шаблоном не гасим
    if kind == "стояк/канализация/отопление" \
            and _ZASOR_TAKE_RX.search(t) and not _PIPE_WORK_RX.search(t):
        return True
    # L2-06: «батарея» техники (ноутбук/айфон/пульт/самокат) — не отопление. Ядра темы нет,
    # а техника есть → тему снимаем совсем: замену батареи ноутбука КП берёт напрямую,
    # телефоны отсеет роутер отказов; согласование тут хоронило бы живой лид.
    if kind == "стояк/канализация/отопление" \
            and not _HEATING_CORE_RX.search(t) and _BATTERY_TECH_RX.search(t):
        return True
    # «не радиатор надо, а унитаз» — тема отвергнута самим клиентом (скептик 01.08)
    if kind == "стояк/канализация/отопление" and _NOT_RADIATOR_RX.search(t):
        return True
    # ГОЛАЯ «батарея» без предмета: ни ядра отопления, ни отопительного контекста, ни техники —
    # предмет неизвестен («замена батареи» может быть ноутбуком). Шаблоном не гасим, модель
    # спросит «батарея от чего?» — так делали и живые операторы (скептик 01.08).
    if kind == "стояк/канализация/отопление" \
            and not _HEATING_CORE_RX.search(t) and not _HEATING_CTX_RX.search(t):
        return True
    # ⚠ ПОТОЛОЧНАЯ ПЛИТКА И ПЛИНТУС — ПРИЁМ, А НЕ ОТДЕЛКА (матрица, строка 716: «Плинтус /
    # порожек / потолочная плитка — любой вид работ, приём, от 800 ₽/м²»). Без этого
    # исключения новая тема отделки похоронила бы прямо перечисленную в прайсе работу.
    # «Варочная плитка» — это ПЛИТА, у неё свои правила выше по списку.
    if kind == "отделка/плитка/штукатурка" and (
            re.search(r"потолочн\w*\s*плитк|плитк\w*\s*(?:на\s*)?потол", t)
            or re.search(r"плинтус|порожек|порожк", t)
            or re.search(r"(?:варочн|индукцион|электрическ|настольн|переносн)\w*\s*плитк", t)):
        return True
    # ⚠ ЗАМЕНА МЕТАЛЛА НА ПЛАСТИК — ЭТО ПРИЁМ (матрица, строка 641: «Замена металлических/
    # металлопластиковых труб НА ПЛАСТИКОВЫЕ — приём»). Клиент уже согласился на пластик —
    # согласовывать нечего, это обычная работа МНЧ.
    if kind == "металлические трубы" and re.search(
            r"на\s*(?:пластик|полипропилен|\bпвх\b|\bпнд\b|\bпвд\b|металлопластик)", t):
        return True
    # ⚠ НАВЕС ТЕЛЕВИЗОРА — МЕЛКАЯ РАБОТА, БЕРЁМ БЕЗ СОГЛАСОВАНИЯ (слово владельца 26.08).
    # Дословно, разделом «Мелкие работы»: «Навес мелких аксессуаров, кронштейна и гардин.
    # Установка ЛЮБЫХ кронштейнов (для телевизора, бойлера и т.д.); установка настенных и
    # потолочных гардин. Можно принять без согласования».
    #
    # Раньше исключение было узким — «кронштейн упомянут, а сам телевизор не упомянут», —
    # и на живом диалоге 26.08 («повесить телевизор диагональю 49 на стену») сработало
    # ровно наоборот: бот ушёл в «сверюсь по графику и чуть позже дам ответ», то есть
    # отдал человеку простую мелкую работу и потерял темп на первичном обращении.
    # Гардины, карнизы, полки и кронштейн для бойлера согласования не требовали и до
    # этого — под старым правилом стоял один телевизор, и это была ошибка.
    #
    # ⚠ ПРАВИЛО ОСТАВЛЕНО В СПИСКЕ, А НЕ УДАЛЕНО. Его регекс — единственное место, где
    # описан навес ТВ; он ещё пригодится, если владелец однажды вернёт согласование для
    # какого-то подвида (например, очень крупных панелей). Сейчас вид берётся целиком.
    if kind == "крепление телевизора на кронштейн":
        return True
    # ПРОШИВКА принтера/МФУ и прошивка самого ТВ — берём; приставки/ресиверы — соглас
    if kind == "прошивка/спец-роутер/модем/СНПЧ" and not _STB_RX.search(t) \
            and (_FIRMWARE_OK_RX.search(t) or _FIRMWARE_TV_RX.search(t)) \
            and not re.search(r"снпч|симочн|\bмодем\b|роутер", t):
        return True
    # ⚠ РЕШЕНИЕ 30.08 (хвост №14, сверка регламента В-004): «пароль и почта есть»
    # отпускает только восстановление ДОСТУПА (разблокировку) — там данные и правда
    # решают всё. Восстановление ИНФОРМАЦИИ из iCloud/WhatsApp/Telegram регламент
    # согласует БЕЗУСЛОВНО: работа часто технически невыполнима, и мастер ехал бы
    # впустую даже с паролем на руках.
    if kind == "разблокировка iCloud без данных" \
            and _HAS_CREDS_RX.search(t) and not _NO_CREDS_RX.search(t):
        return True
    # «восстановить ДОСТУП к icloud» — это доступ, не данные: жадная тема
    # «восстановление из iCloud» перехватывала его, и клиент с паролем на руках
    # уходил в согласование (поймано сторожем router_guards при внедрении №14)
    if kind == "восстановление из iCloud/WhatsApp/Telegram" \
            and re.search(r"восстанов\w*\s*доступ|доступ\w*\s*к\s*(?:icloud|айклауд|аккаунт|apple|гугл|google)", t) \
            and not re.search(r"данн\w*|информаци|фото|перепис|файл|контакт", t.replace("данные все есть","").replace("данные есть","")) \
            and _HAS_CREDS_RX.search(t) and not _NO_CREDS_RX.search(t):
        return True
    # БАНК НА ANDROID — обычная работа (регламент называет только IPHONE/IPAD)
    if kind == "установка банковского приложения на iPhone/iPad" and _ANDROID_RX.search(t):
        return True
    # ── гарды по сверке матрицы 04.08 ──
    # ПОДКЛЮЧЕНИЕ БТ: «канализация» — место слива, не предмет работ (2×high, массовая первичка МНЧ)
    if kind == "стояк/канализация/отопление" \
            and _BT_HOOKUP_RX.search(t) and not _PIPE_WORK_RX.search(t):
        return True
    # ЧИСТКА и НАСТРОЙКА PS/Nintendo/Steam Deck — приём с озвучкой «от 1500»; соглас остаётся
    # за ремонтом/прошивкой любых консолей и НАСТРОЙКОЙ Xbox (чистку Xbox берём)
    if kind == "ремонт/прошивка игровой приставки" and not _CONSOLE_HARD_RX.search(t) \
            and (_CONSOLE_CLEAN.search(t)
                 or (_CONSOLE_SETUP.search(t) and not re.search(r"\bxbox\b|иксбокс", t))):
        return True
    # укладка ламината/линолеума по ГОТОВОМУ основанию — клиент сам закрыл квалификатор
    if kind == "ламинат/пол по неровному основанию" \
            and _FLOOR_READY_RX.search(t) and not _FLOOR_BAD_RX.search(t):
        return True
    # НАСТРОЙКА/подключение на кинескопе/плазме — приём на любом типе ТВ (соглас — только ремонт)
    if kind == "кинескоп/плазма/проекционный ТВ" \
            and _TV_SETUP_RX.search(t) and not _TV_REPAIR_RX.search(t):
        return True
    return False


def _soglas_is_mixed(kind, t, rx=None):
    """True, если тема согласования ОСТАЁТСЯ в силе, но рядом стоят принимаемые позиции.

    Шаблон тут похоронил бы живую часть заявки, поэтому ход отдаём модели — а модели про эту
    позицию говорим отдельной строкой (см. soglas_topic и подсказку в _fields_note).

    ⚠ У ОТКАЗА такой гард есть с сессии 40 (EDGE-03), а у СОГЛАСОВАНИЯ его не было вовсе:
    «кондиционер не холодит, и ещё микроволновка не греет» гасилось ЦЕЛИКОМ одним шаблоном
    «по графику сверюсь», хотя микроволновку мы берём сразу. Логика та же, что у _refuse_is_mixed:
    смесь — это ПЕРЕЧИСЛЕНИЕ, а рядом стоит ДРУГОЙ принимаемый предмет, не тот, что попал в ветку.
    """
    # СМЕШАННЫЙ СПИСОК ПРИЛОЖЕНИЙ («ВК, Макс, Авито, Сбербанк поставите?»): обычные приложения
    # мы берём сразу, и правило плейбука велит РАЗДЕЛИТЬ ответ одной репликой.
    if kind == "установка банковского приложения на iPhone/iPad" and _OTHER_APPS_RX.search(t):
        return True
    # МОСКИТНАЯ СЕТКА (15.08): свои предметы — сама сетка; окно и балкон рядом обычно
    # МЕСТО установки («сетку на окно»), но окно со СВОЕЙ поломкой («не закрывается,
    # и сетка порвана») — отдельная принимаемая работа, её шаблоном хоронить нельзя.
    if kind == "москитная сетка":
        _rest = re.sub(r"москитн\w*(?:\s*сетк\w*)?|москитк\w*|сетк\w*", " ", t)
        if _ACCEPT_OBJ_RX.search(_rest):
            return True
        return bool(re.search(r"окн\w*|балкон\w*", _rest)
                    and re.search(r"не\s*закрыва|не\s*открыва|продува|дует|регулир|"
                                  r"фурнитур|ручк|резинк|заеда|провис", _rest))
    # ⚠ ОБЩЕГО ГАРДА СМЕСИ У СОГЛАСОВАНИЙ ПОКА НЕТ — И ЭТО ОСОЗНАННО.
    # У отказа он работает, потому что там есть РУЧНАЯ карта своих предметов (_REFUSE_OWN):
    # она знает, что «телевизор» принадлежит ветке матрицы и смесью не является. У согласований
    # веток 40+, и попытка вывести их словарь автоматически (из паттерна ветки) провалилась на
    # двух заведомо верных кейсах: «засор в канализации, надо заменить трубу заодно» — засор и
    # канализация одна тема, а «купить кронштейн и повесить телевизор» — кронштейн и телевизор
    # тоже. Оба предмета лежат не в паттерне ветки, а в её гардах — у засора это
    # `_ZASOR_TAKE_RX`, а у кронштейна гарда больше нет: ветку целиком отпускает
    # `_soglas_taken` (см. удалённые _BRACKET_RX/_HANG_TV_RX выше).
    # Замер: гард освободил бы 27 диалогов из 6455 (0.4%), но ценой двух ложных освобождений
    # из двух проверенных — точность недостаточная. Нужна ручная карта своих предметов по
    # веткам, как у отказа; до неё общий гард не включаем, чтобы не отпускать согласуемое.
    return False


def check_soglasovanie(text, seed=""):
    """Тема «по согласованию» → удержать + handoff, без вызова модели (0 токенов).

    Длинные сообщения (>180 симв) НЕ гасим шаблоном: там часто СМЕСЬ (кондиционер + СВЧ) —
    шаблон похоронит принимаемую часть заявки. Пусть разбирает модель (правило согласования
    у неё в плейбуке, handoff она поставит сама)."""
    t = _cap(text).lower()
    if len(t) > 180:
        return None
    for kind, rx in _SOGLAS:
        if rx.search(t):
            if _soglas_taken(kind, t):        # гард сказал «это наша работа» — тему снимаем совсем
                continue
            if _soglas_is_mixed(kind, t, rx): # тема осталась, но рядом принимаемые позиции
                continue
            draft = soglas_reply(seed)
            цена = soglas_price_line(kind, t)
            if цена:
                draft = цена + ". " + draft       # сначала ответ на вопрос клиента
            q = soglas_detail_q(kind, t)
            if q:
                draft = draft + "\n" + q          # вторым пузырём, как пишут живые
            return {"kind": "soglas", "sub": kind, "reason": "тема по согласованию: " + kind,
                    "draft": draft}
    # компактная/переносная/настольная плитка И плита: ИНДУКЦИОННУЮ берём, остальные — по
    # согласованию («не индукционная» = соглас; учитываем отрицание!). Сверка матрицы 04.08:
    # словоформа «плита» не ловилась, а квалификатор «индукционная?» (матрица ❓ стр.73) не
    # задавался — индукционная без явного слова теряла прямой приём.
    _plitka = re.search(r"(?:компактн|переносн|настольн)\w*\s*(?:электро)?плит(?:к\w*|[аоуыеё]\b|ой\b)", t)
    _induction_ok = "индукцион" in t and not re.search(r"не\s*индукцион", t)
    if _plitka and not _induction_ok:
        draft = soglas_reply(seed)
        if "индукцион" not in t:
            draft += "\nПлита индукционная?"
        return {"kind": "soglas", "sub": "компактная не-индукционная плитка",
                "reason": "тема по согласованию: компактная плитка (не индукционная)",
                "draft": draft}
    return None


# ---- ЖАЛОБА/ПРЕТЕНЗИЯ → сразу оператору (бот не спорит, не оправдывается, не квотирует) ----
# ПОЛИТИКА ЗАКАЗЧИКА: недовольство → человеку МОЛЧА, без отписки (человек посмотрит историю
# звонков/заявок и ответит по фактам; бот их не видит и наврёт). COMPLAINT_REPLY пуст = тишина.
COMPLAINT_REPLY = ""
_COMPLAINT = re.compile(
    # «обман» только как ОБВИНЕНИЕ НАС (вы/меня/нас обманули, мастер обманул, обманываете, «это обман»).
    # НЕ ловим: «только не обмани(те)» (опасение, бабушка 28.07) и «я/сама обманула, он двустворчатый»
    # (клиент исправляет СВОЮ ошибку — кейс сборки 29.07, бот молча передал оператору стандартную сборку!)
    r"(?:вы|меня|нас)\s+обманул|обманул[иа]?\s+(?:меня|нас)|мастер\w*\s+обманул|обманули\b|"
    r"обманыва|обманщик|обман\b|мошенн|развод\w*\s+на\s+деньг|наеб|кидал\w*\s+люд|"
    r"верните\s+деньг|деньги\s+верн|возврат\s+денег|деньги\s+назад|"
    # «требую ВЕРНУТЬ деньги» — инфинитив прежние формы не ловили (нужен был порядок «деньги верн»)
    r"верн\w*\s+(?:мне\s+|нам\s+|обратно\s+){0,2}деньг|"
    # ПОРЧА ИМУЩЕСТВА НАШИМ мастером — всегда претензия, даже без слова «жалоба».
    # «ваш» обязателен: «предыдущий мастер сломал» — это рассказ нового клиента, лид (гард ниже).
    r"(?:ваш|вашего|вашим)\s+(?:мастер\w*|сотрудник\w*|специалист\w*)\s+"
    r"(?:[^.!?\n]{0,20})?(?:разбил|сломал|испортил|повредил|поцарапал|залил|уронил|порвал|"
    r"не\s+доделал|бросил)|"
    # «жалоб» с \b (иначе «добро поЖАЛОБать» нет, а вот «пожаловать» ловилось через «жаловат»);
    # «халтур(?!ин)» — улица Халтурина (Энгельс/Саратов/Киров/Ростов) хоронила первичные лиды молча
    r"\bжалоб|(?<!по)жаловат|\bв\s+суд\b|роспотреб|прокурат|"
    r"некачествен\w*\s*(?:работ|ремонт|услуг|сборк|установк|монтаж|обслуживан)|"
    r"(?:сделал|выполн|собра|устан|отремонт|починил)\w*\s+некачествен|"
    r"некачественно\s+(?:сделал|выполн|собра|устан|отремонт|починил)|"
    r"халтур(?!ин)|криворук|развели\s+на|"
    # ⚠ «ОТЗЫВ НАПИШУ» САМО ПО СЕБЕ — НЕ ПРЕТЕНЗИЯ (аудит регламента 18.08,
    # critical). Голый оборот ловил ЛОЯЛЬНОГО клиента: «скиньте за отзыв, я вам
    # хороший отзыв напишу» получал молчание и уходил человеку как жалоба —
    # хотя это торг, штатная отработка возражения лестницей (раздел 10).
    # Претензия — только с негативом или угрозой рядом.
    r"напиш\w*\s+плох\w*\s+отзыв|плох\w*\s+отзыв|негативн\w*\s+отзыв|"
    r"отзыв\w*\s+(?:напиш|оставл)\w*\s+(?:плох|отрицат|негат)|"
    r"(?:оставлю|напишу)\s+(?:плохой|негативный|отрицательный)\s+отзыв|"
    r"не\s+советую\s+обраща|"
    r"продаёте\s+заявк|продаете\s+заявк|перепрода\w*\s+заявк|"
    # «обсчитали за/нам» = составили смету («нам обсчитали за все 30000»), а не претензия
    # «взял N» в единственном числе («мастер взял 3500», «взял 1к за выезд и уехал») — такие
    # претензии проскакивали мимо роутера и уходили модели; гард третьего лица ниже держит лидов
    r"взял[иа]?\s+\d|содрали|насчитали\s+лишн|переплат\w*\s+из-за|"
    r"(?:меня|нас|вы)\s+обсчита|обсчита(?:л[иа]?|ли)\s+(?:меня|нас|на\s+\d)|"
    # --- по определению претензии из регламента (30.07): недовольство качеством/стоимостью,
    # ПОВЕДЕНИЕМ мастера, заявление в органы, требование связи с мастером из-за его работы ---
    r"недовол|не\s+довол(?:ен|ьна)|возмущ|безобрази|хамств|нахамил|нагрубил|груби(?:л|т)\b|"
    r"заявлени\w*\s+в\s+(?:полиц|прокурат|суд|орган|роспотреб)|напиш\w*\s+заявлени|обращ\w*\s+в\s+орган|"
    # ⚠ голое «переделывать» НЕЛЬЗЯ: «нам нужно всё переделывать» про гидроизоляцию — это ЛИД,
    # а «не будем переделывать шкафы» — отмена. Ловим только переделку ЗА НАМИ.
    r"переделыва\w*\s+(?:за\s+вами|за\s+вашим|после\s+ваш)|плохо\s+сделал|криво\s+сделал|сделал\w*\s+плохо|"
    r"после\s+(?:вашего\s+|его\s+)?(?:ремонта|мастера)\s.{0,40}(?:не\s+работает|слома|стало\s+хуже)|"
    # ⚠ голое «номер мастера» НЕЛЬЗЯ (нейтральное «девчонка попросила номер мастера найти»):
    # по регламенту триггер — требование связи ИЗ-ЗА некорректной работы, плюс срыв визита
    r"требую\s+мастер|свяжите\s+(?:меня\s+)?с\s+мастером|"
    r"мастер\w*.{0,20}(?:опозда|не\s+при(?:ехал|шёл|шел)|так\s+и\s+не\s+при)|опозда\w*.{0,20}мастер")


# ГАРД ТРЕТЬЕГО ЛИЦА: деньги взял НЕ МЫ, а «ребята/другой мастер/прошлый сервис» — это не претензия
# к нам, а рассказ новичка о чужом опыте, часто вместе с вопросом нашей цены («Ребята взяли 9000₽
# просто почистили тены, а можно ваш прайс?»). Молчать на такое = терять первичный лид.
_FEAR_QUESTION_RX = re.compile(
    r"не\s+мошенник|мошенник\w*\s*\?|не\s+обман(?:ете|ешь|ываете)|не\s+развод\w*\s*\?|"
    r"не\s+кинете|деньги\s+вперед\s+не\s+дам", re.IGNORECASE)
_COMPLAINT_THIRD_PARTY = re.compile(
    r"(?:ребят\w*|они|другие|друго\w+\s+мастер|прошл\w+\s+мастер|предыдущ\w+|"
    r"в\s+другом\s+сервис|в\s+другой\s+фирм|тот\s+мастер)\s+(?:взял|содрал|обсчита)|"
    # недовольство ЧУЖИМ исполнителем — это не претензия к нам, а рассказ нового клиента
    # («предыдущий мастер плохо сделал, переделать сможете?») — такой лид терять нельзя
    r"(?:друг|прошл|предыдущ|прежн|перв)\w*\s+(?:мастер|фирм|сервис|компани)\w*\s.{0,40}"
    r"(?:плохо|криво|недовол|нахамил|нагрубил)|"
    r"(?:недовол\w*|не\s+довол(?:ен|ьна))\s+(?:друг|прошл|предыдущ|прежн)\w*\s*(?:мастер|фирм|сервис)")


#: ПРОСЬБА УБРАТЬ НЕКРАСИВОЕ — ЛИД, А НЕ ПРЕТЕНЗИЯ. «Сможете спрятать это безобразие?»
#: — клиент просит работу и получал молчание, потому что «безобрази» стоит в списке
#: недовольства. Претензией «безобразие» остаётся, когда рядом нет просьбы к нам.
_COMPLAINT_ASK_RX = re.compile(
    r"(?:сможете|можете|получится|возьм[её]тесь|поможете|реально)\b[^.!?\n]{0,40}"
    r"(?:спрята|убра|убер|скры|скро|закры|исправ|почин|переделa?|привести\s+в\s+порядок)"
    r"[^.!?\n]{0,30}безобрази|"
    r"безобрази[^.!?\n]{0,30}(?:спрята|убра|убер|скры|скро|исправ|почин)",
    re.IGNORECASE)


def check_complaint(text):
    """Жалоба/претензия/угроза отзывом → МОЛЧА человеку, без отписки и без спора (0 токенов)."""
    if _COMPLAINT_ASK_RX.search(text or ""):
        return None
    if _COMPLAINT_THIRD_PARTY.search((text or "").lower()):
        return None
    if _FEAR_QUESTION_RX.search((text or "").lower()):
        # «а вы не мошенники?», «не обманете?» — страх, не претензия: молчание
        # тут хоронит живой лид, отвечает модель успокоением (корпус 16.08)
        return None
    if _COMPLAINT.search((text or "").lower()):
        return {"kind": "complaint", "reason": "жалоба/претензия — молча человеку (без отписки)",
                "draft": "", "silent": True}
    return None


# ---- «УЖЕ НАШ КЛИЕНТ» (контакт ВНЕ видимого чата) → МОЛЧА человеку --------------------------
# Политика заказчика: бот создаёт ПЕРВИЧНЫЕ заявки. Клиент мог звонить/договариваться голосом —
# бот этого НЕ ВИДИТ и наврёт. Малейший след внечатового контакта (звонки, визит мастера,
# «должен был», статус заявки) → тишина + человек (он посмотрит, кто и что звонил/отписано).
# ЖЁСТКИЕ маркеры: контакт вне чата очевиден (звонки, визит мастера, статус заявки) → человеку ВСЕГДА
_EXISTING_HARD = re.compile(
    r"уже\s*(?:обращал|звонил|вызывал)|уже\s*писал(?!\s*(?:вам\s+)?(?:адрес|номер|телефон|выше|тут|здесь|в\s*чате))|"
    r"мы\s*(?:с\s*вами\s*|же\s*)?(?:созванивал|договаривал|общались\s*по\s*телефон)|"
    r"мне\s*(?:звонил|набирал|перезванивал)|вы\s*(?:мне\s*)?(?:звонил|набирал)|"
    r"мастер\s*(?:приезжал|приходил|был\b|забрал|взял|должен|обещал)|"
    r"(?:приезжал|приходил|забрал)\s*(?:мастер|ваш)|"
    r"по\s*(?:моей|нашей)\s*заявк|статус\s*заявк|"
    r"обещал[аи]?\s*(?:позвонить|перезвонить|приехать|привезти)|"
    r"должн[ыа]?\s*были?\s*(?:позвонить|приехать|привезти)|"
    r"когда\s*(?:вернёте|вернете|отдадите|почините\s*мо[йю])|"
    r"где\s*м(?:ой|оя|оё)\s*(?:техник|ноутбук|телевизор|телефон|деньги)|"
    r"верн[ёе]те\s*(?:техник|ноутбук|телевизор)|забрали\s*(?:в\s*ремонт|технику)|"
    r"чек\s*(?:дадите|нужен|пришлите)|не\s*могу\s*(?:до\w*звониться|дозвониться)")
# МЯГКИЕ (статусные): «вы где», «когда приедете», «жду мастера» — ловим после записи или
# обрывком-стартом; в активной сборке заявки это обычный вопрос слота (см. check_existing_client)
# ⚠ 12.08: у «вы где» не было ЛЕВОЙ границы слова — оборот ловился внутри «отЗЫВЫ ГДЕ посмотреть»,
# и вопрос про отзывы получал мостик «гляну по графику и напишу» (палево на ровном месте).
# Тогда же добавлены живые формы статуса, которых не хватало: голое «Вас ждать?» (12 раз за
# 12 дней в корпусе) и «во \bсколько приедете» — они уходили модели, а та ОБЕЩАЛА приехать
# от лица мастера, не зная ни адреса, ни записи. Всего мимо роутера шло 58 статусных из 84.
_EXISTING_SOFT = re.compile(
    r"жд[уём]\s*(?:мастера|звонка)|\bвы\s*(?:сегодня\s*)?приедете|когда\s*(?:вы\s*)?приедете|"
    r"\bты\s*где\b|\bвы\s*где\b|\bвыехал|во\s*\bсколько\s*(?:вас\s*)?ждать|\bвы\s*скоро\b|"
    r"вс[её]\s*в\s*силе|через\s*\bсколько\s*(?:вы\s*)?будете|"
    r"\bвас\s*ждать|во\s*\bсколько\s*(?:вы\s*)?(?:приедете|будете|подъедете|подойдёте|подойдете)|"
    r"когда\s*(?:вы\s*)?(?:будете|подъедете|подъезжаете)|уже\s*(?:в\s*пути|едете|выехали)|"
    r"скоро\s*(?:вы\s*)?будете")   # «где вы находитесь» = гео-вопрос новичка, НЕ сюда
# ⚠ «вас ждать» живёт в двух ролях. Вопрос «Вас ждать?» — статус, человеку. А «будем вас ждать»
# — это клиент ПОДТВЕРЖДАЕТ визит и обычно тут же даёт адрес и телефон (проверка на корпусе
# 12.08: 2 таких диалога из 51, оба с телефоном). Уводить почти закрытый лид оператору нельзя.
_WAIT_CONFIRM_RX = re.compile(r"буд(?:у|ем|ет|ут)\w*\b[^.!?\n]{0,20}\bвас\s*ждать|"
                              r"жд[её]м\s*вас\b|\bжду\s*вас\b")
# ⚠ ОФТОП-СТОП (правка заказчика 04.08): статусные обороты живут и внутри болтовни — «может кофе
# выпьем, КОГДА ПРИЕДЕТЕ)» ловилось как статус существующего клиента и подменяло ответ мостиком
# «Сейчас гляну по времени и отпишусь» (самый палевный ответ: заготовка не в тему). Если в реплике
# есть маркеры флирта/личного/прикола — это НЕ статус визита, отдаём модели с лестницей 🎭 РАСКАЧКА.
_OFFTOPIC_RX = re.compile(
    r"симпатичн|красив\w*\s*(?:вы|ты)|\bкофе\b|свидан|женат|замуж|познаком|встрет\w*\s*(?:не\s*по|просто)|"
    r"\bгей\b|ориентаци|национальност|вероиспов|сколько\s+(?:вам|тебе)\s+лет|за\s+кого\s+голосов|"
    r"\bбот\b|робот|ассистент|нейросет|искусственн|стих|анекдот|смысл\s+жизни|пирожок|"
    r"зарплат|\bсколько\s+(?:вы\s+)?(?:плат\w+|получа\w+)|начальств|сотрудничеств|поставщик|"
    r"хочу\s+к\s+вам\s+работать|массаж", re.IGNORECASE)
# настоящий финал записи в истории бота («записал вас», «запишу вас на»), не квитирование порции
# ⚠ КАНОН «записал ВАС» — не единственная форма финала. Живые финалы бота пишутся иначе:
# «Записал, сегодня к 16:00 подъеду», «Записал: завтра к 10:00, Школьная 15», «Записал,
# буду к 10-10:30. До встречи». Без них booked=False → ветки переноса/статуса молчали, и
# «давайте перенесём»/«вы где?» уходили МОДЕЛИ, хотя переносы по политике делаются звонком.
# Голое «Записал, спасибо» на порцию данных записью по-прежнему НЕ считается: обязательно
# нужно окно цифрами или «до встречи».
_BOOKED_BH_RX = re.compile(
    r"запис\w*\s+(?:вас|тебя)|запишу\s+вас|"
    # точку в промежутке разрешаем («Записал. Могу сегодня к 18:00», «кв.10, к 13:30»), но
    # НЕ пускаем вопрос слота: «Записал адрес. В какое время удобно, может к 18:00?» — это ещё
    # не запись, а подбор времени, и статусные реплики после неё должна вести модель.
    r"(?:запис(?:ал|ала|ываю)|запишу)"
    r"(?:(?!\bкогда\b|како\w*\s*врем|во\s*\bсколько)[^?!\n]){0,80}"
    r"(?:\d{1,2}[:.]\d{2}|\bк\s*\d{1,2}\b|\bна\s*\d{1,2}\b|до\s+встречи)|"
    # 12.08 _soften_booking вычищает «запис» из реплик — финал записи в истории
    # бота узнаём по смягчённым формам (иначе booked не срабатывал никогда)
    r"до\s+встречи|подтвержу\s+ближе\s+к\s+делу|ожидайте\s+мастера|мастер\s+будет\s+у\s+вас")
# перенос/отмена после записи → человеку (все переносы делаются звонком — политика заказчика)
_RESCHED_RX = re.compile(
    r"перенес\w*|перенос\w*|давайте\s*(?:лучше\s*)?(?:на\s*)?(?:друг\w*\s*(?:день|время)|завтра|послезавтра)|"
    r"не\s*получится\s*(?:сегодня|завтра|принять)|не\s*смогу\s*(?:сегодня|завтра|принять)|"
    r"отмен\w*\s*(?:запись|заявк|визит)|давайте\s*отмен")


# Стандарт операторов (26+ случаев в корпусе): спросить номер, с которого обращались, —
# даёт человеку зацепку для поиска в базе звонков/заявок. Ротация формулировок (анти-копирка).
# мостик для статусных «вы где/всё в силе?» и переносов: не тишина, но и не выдуманное время
STATUS_BRIDGE_VARIANTS = [
    "Сейчас гляну по времени и отпишусь вам",
    "Гляну, как у меня по графику, и напишу",
    "Сейчас посмотрю по времени, минуту",
    # ⚠ ПУЛ РАСШИРЕН 26.08 ПОД ТРЕБОВАНИЕ УНИКАЛЬНОСТИ. Пул из трёх-четырёх фраз
    # это потолок в три-четыре разных ответа: роутерная реплика уходит клиенту
    # ЦЕЛИКОМ из пула, и повтор виден невооружённым глазом. Нижняя граница
    # держится набором test_unikalnost (пул меньше шести — провал).
    "Секунду, сверюсь по времени и отпишу",
    "Гляну по своему графику и вернусь с ответом",
    "Уточню по времени и сразу напишу вам",
    "Минуту, посмотрю, как получается, и отвечу",
    "Сейчас разберусь по срокам и отпишусь",
    # живые формулы из корпуса (обучение 30.08): обещание связи без срока визита
    "сейчас гляну и наберу вас",
    "скоро вам наберу, уточню по времени",
]
ASK_NUMBER_VARIANTS = [
    "Номер напомните, с которого обращались?",
    "С какого номера обращались, подскажите?",
    "Подскажите номер, с которого обращались, гляну и вернусь",
    # ⚠ ПУЛ РАСШИРЕН 26.08 ПОД ТРЕБОВАНИЕ УНИКАЛЬНОСТИ. Пул из трёх-четырёх фраз
    # это потолок в три-четыре разных ответа: роутерная реплика уходит клиенту
    # ЦЕЛИКОМ из пула, и повтор виден невооружённым глазом. Нижняя граница
    # держится набором test_unikalnost (пул меньше шести — провал).
    "На какой номер оформляли, подскажите?",
    "Скажите номер, по которому оставляли обращение",
    "По какому номеру вас искать, подскажите?",
    "Номер, с которого писали, напомните, посмотрю",
    "Напомните телефон, с которого обращались, гляну",
]


def check_existing_client(text, bot_history="", all_client_text=""):
    """След контакта ВНЕ видимой истории чата (0 токенов). Политика заказчика: бот создаёт
    только ПЕРВИЧНЫЕ заявки; человек видит историю звонков/заявок, бот — нет и наврёт.
    Номера в чате ещё нет → спросить «с какого номера обращались?» (стандарт операторов)
    и передать человеку. Номер уже есть → молча человеку (зацепка для поиска есть)."""
    t = _cap(text).lower()
    bh = (bot_history or "").lower()
    hard = bool(_EXISTING_HARD.search(t))
    # ЗАПИСЬ = только настоящий финал «записал ВАС» (голое «Записал, спасибо» на порцию данных —
    # НЕ запись: ловился баг — «когда приедете?» в активной сборке улетал человеку)
    booked = bool(_BOOKED_BH_RX.search(bh))
    # МЯГКИЕ («вы где», «когда приедете», «жду мастера»): статус, а не вопрос слота. Ловим когда
    # (а) запись УЖЕ была в чате (после «записал вас» все статусные → человеку: переносы и
    # подтверждения делаются звонком — политика заказчика 29.07) ИЛИ
    # (б) истории бота нет вообще (обрывок-старт «мне звонили»). В АКТИВНОЙ сборке заявки без
    # записи «когда приедете?» — обычный вопрос слота, НЕ ловим.
    in_progress = bool(bh.strip()) and not booked
    soft = bool(_EXISTING_SOFT.search(t)) and not in_progress and not _OFFTOPIC_RX.search(t) \
        and not _WAIT_CONFIRM_RX.search(t)
    # перенос/отмена ПОСЛЕ записи → человеку (бот переносы не делает)
    resched = bool(_RESCHED_RX.search(t)) and booked
    if not (hard or soft or resched):
        return None
    has_phone = bool(phones_in((all_client_text or "") + " " + (text or "")))
    # СТАТУСНЫЕ/переносы (soft/resched) — не молча, а с мостиком-репликой (валидация 30.07:
    # живые всегда дают мост «сейчас гляну по времени»); человек продолжит от того же лица.
    if (soft or resched) and not hard:
        idx = len(text or "") % len(STATUS_BRIDGE_VARIANTS)
        return {"kind": "existing_client", "silent": False, "draft": STATUS_BRIDGE_VARIANTS[idx],
                "to_operator": True,
                "reason": "статус/перенос после записи — мостик и человеку (график у людей)"}
    if has_phone:
        return {"kind": "existing_client", "silent": True, "draft": "",
                "reason": "контакт вне чата, номер уже в чате — молча человеку (найдёт по номеру)"}
    idx = len(text or "") % len(ASK_NUMBER_VARIANTS)
    return {"kind": "existing_client", "silent": False, "draft": ASK_NUMBER_VARIANTS[idx],
            "reason": "контакт вне чата — спросить номер обращения и передать человеку"}


# ---- КЛИЕНТ ПРОСИТ ПОЗВОНИТЬ → передать человеку, чтобы набрал и договорился окончательно ----
# Правило заказчика: такой диалог лучше отдать оператору для звонка (бот сам не звонит).
CALL_REPLY = "Сейчас у клиента, как освобожусь, наберу вас и обо всём договоримся"
_CALL_FORBID_RX = re.compile(
    r"н[ея]\s+(?:надо\s+|нужно\s+)?(?:мне\s+)?(?:по)?звон|"
    r"тольк[оа]\s+не\s+звон|без\s+звонк|не\s+звони|звонить\s+не\s+(?:надо|нужно)|"
    r"не\s+смогу\s+(?:ответить|взять\s+трубку|поднять)|пишите\s+(?:сюда|тут|в\s*чат)",
    re.IGNORECASE)

_CALL_REQUEST = re.compile(
    r"перезвон\w+|"
    r"(?:по)?звони(?:те)?\s+(?:мне|нам|пожалуйста)|"
    r"наберите\s+(?:меня|мне|нам)|наберите\s+мой\s+номер|"
    r"можете\s+(?:мне\s+|меня\s+)?(?:позвонить|набрать|перезвонить)|"
    r"созвон[иё]мся|давайте\s+созвон|можем\s+(?:ли\s+)?созвон|наберите\s+пожалуйста|"
    r"можн[оа]\s+(?:вам|с\s+вами)\s+позвонить|по\s+какому\s+(?:телефону|номеру)\s+(?:с\s+вами\s+)?(?:можно\s+)?(?:созвон|позвон|связ)|"
    r"по\s+телефону\s+(?:обсуд|договор|поговор|удобн|проще|свяж)|"
    r"позвони(?:те)?\s+обсуд|"
    r"не\s+могу\s+позвонить\s+через\s+авито|через\s+авито\s+не\s+могу\s+позвон|"
    r"давайте\s+(?:по\s+телефону|голосом)|"
    r"(?:обсуд\w+|договор\w+|поговор\w+)\s+(?:по|голосом\s+по)\s+телефон|звякн\w+")
# «позвоните, КАК БУДЕТЕ ПОДЪЕЗЖАТЬ» — инструкция к визиту, НЕ просьба созвониться (ответ «Хорошо, наберу»)
_CALL_VISIT_GUARD = re.compile(
    r"буд[еу]\w*\s+подъезж|подъезжа\w+\s*[,\-]?\s*(?:наберите|позвоните|набери)|"
    r"подъед\w+\s*[,\-]?\s*(?:наберите|позвоните)|перед\s+(?:выездом|приездом)|"
    r"заранее\s+(?:позвон|набер)|за\s+(?:час|полчаса)|домофон|если\s+что\w*\s+помен|я\s+встречу")


# ⚠ ИНВЕРСИЯ: звонить собирается САМ КЛИЕНТ («я вам перезвоню», «телефон скиньте, перезвоню»).
# Отвечать на это «наберу вас» — бессмыслица: он просит НАШ номер, а не оставляет свой.
# В корпусе 10 таких из 109 сработок ветки.
_CALL_INVERSE_RX = re.compile(
    r"\bя\s+(?:вам\s+|тебе\s+)?(?:пере)?звоню|\bя\s+(?:вам\s+)?наберу|сам\s+наберу|сам\s+позвоню|"
    r"(?:телефон|номер)\w*\s+(?:свой\s+)?(?:скинь|скиньте|дайте|напишите|пришлите|оставьте|"
    r"подскажите|киньте)[^.!?\n]{0,30}(?:перезвоню|позвоню|наберу|свяжусь)|"
    r"(?:перезвоню|позвоню|наберу|свяжусь)[^.!?\n]{0,30}(?:телефон|номер)\w*\s+"
    r"(?:скинь|скиньте|дайте|напишите|пришлите|оставьте)|"
    r"как\s+с\s+вами\s+связаться|ваш\s+(?:номер|телефон)\s+(?:какой|подскажите|скажите)")
# просьба номера ВТОРЫМ пузырём: звонить некуда, Avito телефон скрывает
CALL_ASK_NUMBER = [
    "Номер оставьте, наберу, как освобожусь",
    "Номер ваш подскажите, наберу вас",
    "Оставьте номер, наберу и обо всём договоримся",
    # ⚠ ПУЛ РАСШИРЕН 26.08 ПОД ТРЕБОВАНИЕ УНИКАЛЬНОСТИ. Пул из трёх-четырёх фраз
    # это потолок в три-четыре разных ответа: роутерная реплика уходит клиенту
    # ЦЕЛИКОМ из пула, и повтор виден невооружённым глазом. Нижняя граница
    # держится набором test_unikalnost (пул меньше шести — провал).
    "Скиньте номер, наберу вам",
    "Телефон ваш напишите, позвоню",
    "Дайте номер, свяжусь с вами",
    "Напишите номер, наберу и всё обсудим",
    "Номер ваш оставьте, и я перезвоню",
]


def check_call_request(text, all_client_text=""):
    """Клиент хочет, чтобы ЕМУ позвонили → передать оператору для звонка (0 токенов).
    «Звоните с Авито»/«я вам позвоню» сюда НЕ попадают (там нужен номер, обрабатывает модель).

    ⚠ БЕЗ НОМЕРА ЗВОНИТЬ НЕКУДА. Avito телефон скрывает, а ветка его не спрашивала: клиент
    уходил ждать звонка, которого физически не может быть, оператор получал диалог без номера,
    лид засыпал молча (29 сработок из 109 по корпусу). Соседняя ветка «уже наш клиент» ту же
    ситуацию решает правильно — здесь про это забыли."""
    t = _cap(text).lower()
    if "звоните с авито" in t or "звонить с авито" in t:
        return None
    if _CALL_VISIT_GUARD.search(t):          # «позвоните как подъедете» = инструкция, не созвон
        return None
    if _CALL_INVERSE_RX.search(t):           # звонить собирается сам клиент — «наберу вас» неуместно
        return None
    # ⚠ ЗАПРЕТ ЗВОНКА — НЕ ПРОСЬБА ЗВОНКА (аудит 15.08). «НЕ звоните мне, я на
    # совещании, пишите сюда» матчился внутренностью «звоните мне», и клиент,
    # попросивший тишины, получал «как освобожусь, наберу вас». Хуже сценария
    # не придумать: глухой клиент, писавший «только не звоните, общаюсь текстом»,
    # получал обещание звонка. Отрицание рядом с основой — молча к модели.
    if _CALL_FORBID_RX.search(t):
        return None
    if _CALL_REQUEST.search(t):
        draft = CALL_REPLY
        if not phones_in((all_client_text or "") + " " + (text or "")):
            draft += "\n" + CALL_ASK_NUMBER[len(t) % len(CALL_ASK_NUMBER)]
        return {"kind": "call_request", "reason": "клиент просит позвонить — нужен звонок оператора",
                "draft": draft}
    return None


# Отговорка-слив (дубль / уже есть активная заявка) — как в реальной практике.
DEFLECT_REPLY = ("Здравствуйте\nК сожалению, уехал из города по работе, "
                 "в ближайшие дни подъехать не смогу. Всего доброго")

# ⚠ РАЗДЕЛИТЕЛИ ТОЛЬКО ПОСЛЕ КОДА СТРАНЫ, А НЕ ПЕРЕД НИМ (найдено 25.08 по жалобе
# владельца: «если бот определил номер как 89001112240, заявку он не создаёт»).
# Старый шаблон начинался с НЕОБЯЗАТЕЛЬНОГО кода страны и сразу за ним пускал
# `[\s\-()]*`. Из-за левого совпадения движок вставал на ПРОБЕЛ перед номером: код
# совпадал пусто, пробел съедался разделителем, и дальше бралось 3+3+2+2 = ДЕСЯТЬ
# цифр из одиннадцати — «мой номер 89001112240» давало ключ «8900111224».
# Ошибка только у слитных одиннадцатизначных БЕЗ «+» и НЕ в начале строки, то есть
# у самой частой формы записи. С «+7…» и с разделителями («8 900 111-22-40») всё
# работало — потому и не замечали.
# Цена: ключ дедупа и признак «телефон уже дан» считались по НЕВЕРНОМУ номеру.
# ⚠ ТОЧКА И ЗАПЯТАЯ — ТОЖЕ РАЗДЕЛИТЕЛИ НОМЕРА (замер 27.08). В корпусе 34 реплики, где
# клиент дал номер, а парсер его не увидел: «8.999.123.45.67», «8,999,123,45,67»,
# «8999...123...45...67». Цена промаха прямая — бот переспрашивает номер, который уже назван.
# Даты и цены под шаблон не подходят: он требует групп 3+3+2+2 подряд, а «12.05.2026» и
# «1 500, 2 000» так не ложатся (проверено на всём корпусе — ложных срабатываний не прибыло).
_PHONE = re.compile(r"(?:(?:\+?7|8)[\s\-().,]*)?\d{3}[\s\-().,]*\d{3}[\s\-().,]*\d{2}[\s\-().,]*\d{2}(?!\d)")


def phones_found(text):
    """Номера в тексте В ПОРЯДКЕ ПОЯВЛЕНИЯ, нормализованные до последних 10 цифр.

    ⚠ ОДИН ШАБЛОН НА ВЕСЬ ПРОЕКТ. Сервер искал номер СВОИМ регексом
    (`[+78][\\d\\s\\-()]{9,16}`), потому что phones_in отдаёт множество и не
    индексируется. Два шаблона расходились: сервер брал номер, которого
    phones_in не видел, и наоборот.
    """
    out = []
    for m in _PHONE.findall(text or ""):
        digits = re.sub(r"\D", "", m)
        if len(digits) >= 10 and digits[-10:] not in out:
            out.append(digits[-10:])
    return out


def phones_in(text):
    """Ключи дедупа: то же самое множеством — порядок вызывающим не нужен."""
    return set(phones_found(text))


def norm_text(t):
    t = (t or "").lower()
    t = re.sub(r"https?://\S+", "", t)
    t = re.sub(r"[🖼📢🤝☀️)]+", "", t)
    t = re.sub(r"[^\w\s]", " ", t, flags=re.UNICODE)
    t = re.sub(r"\s+", " ", t).strip()
    return t


def soglas_topic(text):
    """Тема по согласованию в тексте БЕЗ гарда длины и БЕЗ гарда смеси — для подсказки модели
    там, где шаблон намеренно не ушёл: длинные простыни (>180) и смешанные списки
    («Макс, Авито, сбер, альфа на айфон»). Короткие чистые случаи перехватывает
    check_soglasovanie шаблоном до модели.

    ⚠ Темы, которые гард отпустил как НАШУ работу (кронштейн, прошивка принтера, засор,
    iCloud с сохранёнными данными, банк на Android), сюда НЕ попадают: иначе подсказка вернула бы
    ровно те ложные согласования, ради которых эти гарды и писались."""
    t = _cap(text).lower()
    for kind, rx in _SOGLAS:
        if rx.search(t) and not _soglas_taken(kind, t):
            return kind
    return None


# + МОНОБЛОК и ПК: регламент КП — «любая техническая проблема с ПК/Моноблоком/Ноутбуком» без
# согласования, а отказ по матрице объявлен только для ЖК ТВ. Моноблок под отказ не подпадает.
# ⚠ «КОМПЬЮТЕР» СЮДА НЕ ВХОДИЛ, А ОБЪЯВЛЕНИЕ НАЗЫВАЕТСЯ «Ремонт и настройка компьютеров»
# (снимок владельца 27.08). Список опознаёт предмет КП, чтобы отказ по матрице ЖК ТВ не
# накрыл ноутбучный экран, — и самое частое слово этого предмета в нём отсутствовало.
_LAPTOP_RX = re.compile(r"ноутбук|ноут\b|нетбук|macbook|макбук|laptop|ультрабук|моноблок|\bпк\b|"
                        r"компьютер|\bкомп\b|систем\w*\s*блок")
# Восстановление ДАННЫХ с неисправного телефона/планшета — согласование, а не отказ: отказ
# 06.04.2026 объявлен для РЕМОНТА телефонов, а регламент КП отдельно перечисляет «восстановление
# информации с телефонов и планшетов, которые повреждены / не включаются / заблокированы».
_DATA_RECOVERY_RX = re.compile(
    r"восстанов\w*|вытащ\w*|достат[ьи]|вынут[ьи]|скопир\w*|перенест[ьи]|спасти|"
    r"(?:нужн\w*|надо|нада)\s*(?:данн|фото|контакт|файл|информац)")
# Матрица МОНИТОРА — по согласованию (регламент КП «Мониторы/Видеокарты»), а отказ объявлен
# только для матрицы ЖК ТВ (объявление КЦ 16.09.2025). Различаем по слову «монитор» без ТВ.
_MONITOR_RX = re.compile(r"монитор")
# (_TV_RX объявлен НИЖЕ, у правил МНЧ. Здесь стояла его вторая копия — мёртвая, потому что
#  нижняя затирала её при импорте. Копии были почти одинаковы и на 13 живых пробах не
#  расходились ни разу, так что поведение не менялось; убрано 24.08 вместе с линтером,
#  который теперь не даёт завести третью.)
# Настройка ПУЛЬТА к любому типу ТВ — берём без согласования (регламент БТ, ТВ п.7), даже если
# в тексте мелькает «триколор»: клиенту нужен пульт, а не подключение спутника.
_REMOTE_RX = re.compile(r"пульт")
# ── ГАРДЫ ОТКАЗОВ, найденные строгим аудитом 31.07. Каждый снят с реальных лидов корпуса ──
# ГАЗ упомянут РЯДОМ, а работа мебельная/кухонная/сантехническая: «шкаф под встраиваемую газовую
# панель», «вырезать отверстие под мойку и газовую панель», «укоротить трубу к газовой колонке».
# Живые мастера такие заявки БРАЛИ (проверено по корпусу). Отказ — только если просят работу
# с САМИМ газовым прибором (подключить/отключить/починить/установить его).
_GAS_CONTEXT_OK = re.compile(
    r"столешниц|шкаф|кухн|гарнитур|мойк|раковин|врез|выпил|отверсти|тумб|полк|"
    r"сборк|собрать|труб|шланг|полипропилен|подводк|смесител|лампочк")
_GAS_DIRECT = re.compile(
    r"(?:подключ|отключ|отсоедин|перенест|перевес|установ|почин|ремонт|отремонт|замен|помен|"
    r"смен|снять|снят|демонтир)\w*"
    r"[^.!?]{0,30}(?:газов|\bгаз\b)|(?:газов\w*|\bгаз\b)[^.!?]{0,30}"
    r"(?:подключ|отключ|не\s*работает|не\s*греет|не\s*горит|почин|ремонт|теч|пахнет|утечк)")
# МАТРИЦА: ПОДСВЕТКА и инвертор — это НЕ матрица, регламент и плейбук велят такое брать
# («звук есть, изображения нет», «не горит подсветка», «тёмный экран»).
_BACKLIGHT_RX = re.compile(
    r"подсветк|инвертор|блок\w*\s*питани|звук\s*есть[^.!?]{0,30}(?:изображен|картин|нет)|"
    r"т[её]мн\w*\s*экран|лампы\s*подсв")
# ⚠ «скол» БЕЗ границы слова сидел внутри «СКОЛько» — а «\bсколько будет стоить» есть почти в
# каждом ценовом обращении (разбор живого корпуса 12.08.2026: 927 первых сообщений со словом
# «\bсколько»). Из-за этого исключение подсветки НЕ РАБОТАЛО, как только клиент спрашивал цену:
# «замена подсветки матрицы, \bсколько стоит» уходило в отказ, хотя мастера такие заказы берут
# («от 1000 замена подсветки» — 23 диалога за 12 дней). Тот же класс бага, что «соо-ТВ-етственно».
# «полос» заодно отделён от «полоскания» (стиральные машины).
_MATRIX_HARD_RX = re.compile(r"разбит|треснул|полос(?!кан)|\bскол(?:ы|ов|а|ами)?\b|"
                             r"удар|упал|уронил|залил|раздав")
# Клиент сам пишет, что матрица цела («матрица абсолютно целая», «матрица жива») — слово
# «матрица» в реплике есть, а повреждения нет: это подсветка/плата, а не замена матрицы.
# ⚠⚠ 12.08, вторая правка за день. Первая («ключи потерял» = отказ) оказалась хуже исходной
# дыры: «потеряли ключи, надо замок ЗАМЕНИТЬ» уходило в окончательный отказ, хотя замена
# замка — обычная работа из прайса МНЧ (межкомнатные 2500, входные 5000). Регламент отказывает
# только ВСКРЫТИЮ: «Вскрытием замков мы не занимаемся». Проверка вынесена в цикл check_refuse,
# а не в просмотр вперёд внутри регекса: тот не видит слов, стоящих ПЕРЕД совпадением, и
# «Замена замка, ключи потеряли» всё равно уходило в отказ.
_LOCK_REPLACE_RX = re.compile(
    r"(?:замен|помен|постав|установ|врез)\w*[^.!?\n]{0,25}(?:замок|замк|личинк|ручк)|"
    r"(?:замок|замк|личинк|ручк)\w*[^.!?\n]{0,25}(?:замен|помен|постав|установ|врез)",
    re.IGNORECASE)
_MATRIX_OK_RX = re.compile(r"матриц\w*\s*(?:абсолютно\s*|вроде\s*|как\s*бы\s*)?"
                           r"(?:цел|жив|в\s*порядке|не\s*разбит|не\s*бит|норм)")
# ТЕЛЕФОН как КОНТАКТ, а не как техника: «нужен ремонт, мой телефон 89…» — в одном сообщении
# и суть, и номер. Такой лид почти оформлен, отшивать его шаблоном нельзя.
_PHONE_AS_CONTACT = re.compile(
    r"(?:мой|наш|мне|контактн\w*|для\s*связи|звонит[ье])\s*(?:номер\s*)?телефон|"
    r"телефон\w*\s*(?:для\s*связи|мой|наш)")
_OTHER_TECH_RX = re.compile(
    r"холодильник|стиральн|стиралк|посудомо|телевизор|\bтв\b|принтер|ноутбук|компьютер|\bпк\b|"
    r"плит[аыу]|духовк|микроволн|\bсвч\b|бойлер|водонагрев|кондицион|пылесос|кофемашин")
# КАРТРИДЖ в НАДПИСИ принтера или в предыстории («пишет замените картридж», «поменяли картридж —
# стал мазать») — это заявка на РЕМОНТ ПРИНТЕРА, его берём.
_PRINTER_SYMPTOM_RX = re.compile(
    r"пишет|выда[её]т|ошибк|горит|мигает|маж[еу]|маза|грязно|полос|жу[её]т|не\s*печата|не\s*берёт|"
    r"не\s*видит|посмотрет|профилактик|чистк|засохл|сообщение|на\s*экране|на\s*дисплее|"
    # L2-02: из 28 ремонтных заявок с упомянутым картриджем старый словарь ловил симптом
    # только в 11 — добраны частые формы («Необходима диагностика», «перестал подавать бумагу»,
    # «Моргают все индекаторы», «замялась бумага», «очередь на печать висит»)
    r"диагностик|перестал\w*\s*(?:работ|печат|подава)|не\s*пода[её]т|морга|индикатор|"
    r"замял|зажева|очеред\w*\s*на\s*печать|(?:бел|чист|пуст)\w*\s*лист")
# принтерное слово рядом с симптомом — признак заявки на РЕМОНТ техники, а не на заправку
_PRINTER_CTX_RX = re.compile(r"принтер|\bмфу\b|копир|сканер|плоттер")


# ---- СМЕШАННАЯ ЗАЯВКА В ОТКАЗЕ (EDGE-03) --------------------------------------------
# У согласований гард смеси стоит с самого начала (см. check_soglasovanie: len>180), а у отказа
# его не было: ОДНО запретное слово в любом месте отшивало ВСЮ заявку шаблоном, до модели ход
# не доходил. Живые примеры из корпуса: «вырезать в столешнице отверстие под мойку И ГАЗОВУЮ
# ПАНЕЛЬ» (врезка мойки — берём!), «повесить телевизор на кронштейн и ЕЩЁ заправить картридж».
# Признак смеси — принимаемая работа рядом с запретной. Тогда шаблон не отдаём: пусть отвечает
# модель, а _fields_note детерминированно подскажет ей отказать по одной позиции и взять остальные.
# ⚠ ТОЛЬКО ПРЕДМЕТЫ, БЕЗ ГЛАГОЛОВ. Первая версия гарда держала и глаголы («поменять»,
# «подключить») — и «подключить газовую колонку И настроить её» объявляла смесью сама с собой:
# глагол почти всегда управляет как раз запретным предметом. Вторая позиция — это ДРУГОЙ ПРЕДМЕТ.
_ACCEPT_OBJ_RX = re.compile(
    r"шкаф|кухн|комод|кроват|\bполк|карниз|гардин|зеркал|стеллаж|тумб|мебел|"
    r"розетк|выключател|проводк|щит(?:ок|ка)|люстр|светильник|\bбра\b|"
    r"смесител|раковин|мойк|унитаз|сифон|полотенцесушител|\bванн|душев|засор|\bкран\b|"
    r"стиральн|стиралк|посудомо|холодильник|духов|вытяжк|кондицион|свч|микроволнов|"
    r"ноутбук|компьютер|\bпк\b|роутер|кронштейн|ламинат|линолеум|плинтус|москитн|жалюзи|"
    r"телевизор|телек\b|\bтв\b")
# «Свои» предметы каждой запретной темы: они НЕ считаются второй позицией. Без этого
# «матрица разбита на ТЕЛЕВИЗОРЕ, поменяете?» само себя объявляло смесью через слово «телевизор».
_REFUSE_OWN = {
    "газ": re.compile(r"плит|панел|поверхн|колонк|котл|котел|духов|варочн|шланг|труб|горелк|"
                      r"конфорк|водонагрев|бойлер|газ"),
    "заправка": re.compile(r"картридж|катридж|тонер|принтер|\bмфу\b"),
    "матрица": re.compile(r"телевизор|\bтв\b|экран|монитор|дисплей|матриц|подсветк|пиксел"),
    "телефоны": re.compile(r"телефон|айфон|iphone|смартфон|планшет|ipad"),
    "замок": re.compile(r"замок|замк|двер|ключ"),
    "спутниковое ТВ": re.compile(r"антенн|тарелк|\bтв\b|телевизор|триколор|канал|ресивер|приставк"),
    "батарейка пульта": re.compile(r"батарейк|пульт"),
    "аккумулятор самоката": re.compile(r"аккумулятор|батаре|самокат"),
    "мнч-непрофиль": re.compile(r"кровл|крыш|асфальт|тротуар|дорожн|копк|транше|колодц|колодец|"
                                r"дерев|покос|трав|снос|сруб|дом\b|гараж|бан[яюи]|сарай|участ"),
}
# Скупка и интим смесью не бывают: там сам запрос («выкупаете?», интим-товар) отдельный,
# а не позиция в списке работ — гард смеси для них не включаем.
_NO_MIX_KINDS = {"скупка", "интим"}
_ENUM_RX = re.compile(r"\bи\b|\bещ[её]\b|\bа\s*также\b|,|\+|\bплюс\b|\bтакже\b|\bзаодно\b")


def refuse_topic(text, предмет=""):
    """Тема ОТКАЗА в тексте БЕЗ гарда смеси — для подсказки модели на смешанных заявках
    (чистые отказы перехватывает check_refuse шаблоном до модели).

    ⚠ ГАРД СМЕСИ ЗДЕСЬ И ПРАВДА НЕ НУЖЕН — А ВОТ ПРЕДМЕТНЫЕ НУЖНЫ, И ИХ НЕ БЫЛО. Функция
    шла по той же таблице `_REFUSE` голым перебором, поэтому на «матрицу ноутбука» она
    отвечала «не наша позиция» ровно тогда, когда шаблонный отказ её уже снял. Модель
    получала совет отказать в работе, которую мы берём (разбор 27.08).
    """
    t = _cap(text).lower()
    предмет_t = (t + " " + _cap(предмет or "").lower()).strip()
    # клиент сам снял вопрос — отказывать ему по теме не за что (см. _ОТМЕНА_ЯВНАЯ_RX)
    if _ОТМЕНА_ЯВНАЯ_RX.search(t):
        return None
    for kind, rx, reason in _REFUSE:
        if rx.search(t):
            # ⚠ ТОЛЬКО ПРЕДМЕТНЫЙ ГАРД. Подсказка «рядом есть НЕ НАША позиция» тем и полезна,
            # что предупреждает про газ у столешницы и картридж у кронштейна — контекстные
            # гарды её гасить не должны, это её работа. А вот ноутбучную матрицу правило про
            # ЖК ТВ не касается вовсе, и предупреждать о ней не о чем.
            if _не_тот_предмет(kind, t, предмет_t):
                continue
            return kind
    return None


def _refuse_is_mixed(kind, t, rx):
    """True, если рядом с запретной темой стоит ДРУГОЙ, принимаемый предмет работ."""
    if kind in _NO_MIX_KINDS:
        return False
    if not _ENUM_RX.search(t):        # смесь — это перечисление, а не одна позиция с описанием
        return False
    m = rx.search(t)
    if not m:
        return False
    rest = t[:m.start()] + " " + t[m.end():]
    own = _REFUSE_OWN.get(kind)
    for om in _ACCEPT_OBJ_RX.finditer(rest):
        if not own or not own.search(om.group(0)):
            return True
    return False


#: Прямые слова про матрицу — если они есть, исключение про «уронили пульт» не работает.
_МАТРИЦА_ПРЯМАЯ_RX = re.compile(
    r"матриц|разби\w*\s*(?:экран|дисплей)|(?:экран|дисплей)\w*\s*разбит|"
    r"треснул\w*\s*(?:экран|дисплей)|битые\s*пиксел",
    re.IGNORECASE)
#: Уронили/ударили ПРИНАДЛЕЖНОСТЬ, а не сам телевизор.
_УДАР_ПО_МЕЛОЧИ_RX = re.compile(
    r"(?<![а-яё])(?:упал|упало|упала|урон\w*|уронил\w*|ударил\w*|бросил\w*|кинул\w*)"
    r"[\s\S]{0,20}(?:пульт|подставк|кронштейн|коробк|провод|шнур|антенн|приставк)",
    re.IGNORECASE)


#: ⚠ «НА ЗАПЧАСТЬ» БЫВАЕТ ВОПРОСОМ О ЦЕНЕ ДЕТАЛИ, А НЕ ПРЕДЛОЖЕНИЕМ ПРОДАТЬ (26.08).
#: Роутер скупки ловит подстроку «на запчаст» и отвечал «скупкой не занимаемся» живым
#: возражениям посреди воронки: «Мне нужно конкретно знать цену НА ЗАПЧАСТЬ», «А НА
#: ЗАПЧАСТИ ценники примерные?». Клиент спрашивает, сколько стоит деталь для ремонта, —
#: это торг, а не продажа нам техники.
#: Отличаем по грамматике, а не по контексту, и это проверено на боевом корпусе:
#: настоящие скупщики ПРЕДЛАГАЮТ («на запчасти принимаете?», «выкупаете?», «продать
#: можно?»), а возражающие СПРАШИВАЮТ ЦЕНУ или ОТРИЦАЮТ («скупке он НЕ нужен»).
#: Контекст тут не помощник: из десяти диалогов, где «на запчасти» всплывает не первой
#: репликой, девять — всё равно продажа. Значит решает формулировка.
_ЗАПЧАСТЬ_ЦЕНА_RX = re.compile(
    r"(?:цен\w*|ценник\w*|стоимост\w*|скольк\w*|прайс\w*)[^.!?\n]{0,40}на\s*запчаст|"
    r"на\s*запчаст[^.!?\n]{0,40}(?:цен\w*|ценник\w*|стоимост\w*|скольк\w*|прайс\w*)",
    re.IGNORECASE)
#: ⚠ КЛИЕНТ СОБИРАЕТСЯ ПРОДАТЬ ЕГО САМ — ЭТО ДОВОД В ТОРГЕ, А НЕ ПРЕДЛОЖЕНИЕ НАМ.
#: «лучше новый куплю, а этот на запчасти ПРОДАМ», «мне его проще продать на запчасти
#: будет» — клиент взвешивает, чинить или избавляться, и говорит о СЕБЕ. Настоящий
#: скупщик обращается к НАМ: «вы принимаете?», «выкупаете?», «покупаете?», «заберёте?».
#: Поэтому первое лицо без обращения к нам скупкой не считаем.
_САМ_ПРОДАМ_RX = re.compile(
    r"(?:\bя\b|\bмне\b|\bсам\b|\bсама\b)[^.!?\n]{0,60}"
    r"(?:продам|продать|сдам|сдать|избавит)", re.IGNORECASE)
_К_НАМ_RX = re.compile(
    r"\bвы\b|\bвам\b|принима\w+|выкуп\w+|скупа\w+|покупа\w+|бер[её]те|заб(?:ир|ер)а\w+|"
    r"нужен\s+(?:вам|ли\s+вам)|интересует\s+ли", re.IGNORECASE)
_СКУПКА_ОТРИЦАНИЕ_RX = re.compile(
    r"скупк\w*[^.!?\n]{0,20}не\s+(?:нужен|нужна|нужно|интересн|берут|возьмут)|"
    r"не\s+(?:нужен|нужна|нужно)[^.!?\n]{0,20}скупк", re.IGNORECASE)


#: ⚠ ОТМЕНА ВАЖНЕЕ ОТКАЗА ПО ТЕМЕ (26.08). «Извините, НЕ АКТУАЛЬНО, проще комп собрать
#: чем матрицу поменять» — клиент уходит и вежливо объясняет почему. Роутер отказа видел
#: слово «матрицу» и отвечал «разбитой матрицей не занимаемся» — то есть отказывал тому,
#: кто уже сам отказался. Со стороны это выглядит как «нам и не надо».
#: Слово темы здесь стоит в ПРИЧИНЕ ухода, а не в запросе. Отдаём такую реплику ветке
#: отмены: она скажет «понял, спасибо, что предупредили» и оставит дверь открытой.
_ОТМЕНА_ЯВНАЯ_RX = re.compile(
    r"(?<!\w)(?:не\s+актуальн|уже\s+не\s+нужн|больше\s+не\s+нужн|отмен(?:яю|ите|ил)|"
    r"передумал\w*|решил\w*\s+не\s+|нашли?\s+другого|сам\w*\s+справил)", re.IGNORECASE)


def _не_тот_предмет(kind, t, предмет_t):
    """Тема угадана по слову, но предмет НЕ ТОТ, о котором правило.

    ⚠ ЭТО НЕ ТО ЖЕ САМОЕ, ЧТО «В ЭТОМ КОНТЕКСТЕ БЕРЁМ». Отказ по матрице объявлен для ЖК ТВ;
    матрица ноутбука и монитора — обычная работа КП, и правило к ней не относится ВООБЩЕ.
    А вот «вырезать отверстие под газовую панель» — тема газа рядом с нашей работой: там
    модель предупредить надо. Первое снимает и подсказку модели, второе — только шаблон.
    Смешать их значит либо отказывать в ноутбучной матрице, либо молчать про газ.
    """
    if kind != "матрица":
        return False
    if _TV_RX.search(t):
        return False                      # телевизор назван прямо — правило про него
    return bool(_LAPTOP_RX.search(предмет_t) or _MONITOR_RX.search(предмет_t))


def _гард_снимает_отказ(kind, t, предмет_t):
    """Снимает ли предметный гард отказ по этой теме. `t` — последняя реплика клиента,
    `предмет_t` — она же плюс вся речь за диалог (предмет работы называют один раз).

    ⚠ ЖИЛО ЭТО ВНУТРИ ЦИКЛА `check_refuse`, И ВТОРОЙ ПОТРЕБИТЕЛЬ ГАРДОВ НЕ ВИДЕЛ ВОВСЕ.
    `refuse_topic` — та же таблица `_REFUSE`, но без единого гарда: она подсказывает модели
    «в сообщении есть НЕ НАША позиция». То есть шаблон отказ по матрице ноутбука снимал, а
    подсказка модели — нет, и модель получала совет отказать там, где мы берёмся. Разбор
    27.08 по снимку владельца. Теперь список один и зовут его обе точки.
    """
    # ⚠ ГАРДА ПО НАПРАВЛЕНИЮ ДЛЯ «мнч-непрофиль» ЗДЕСЬ НЕТ, И ЭТО ПРОВЕРЕНО (31.08).
    # Соблазн был: раз п.12 — список работ МУЖА НА ЧАС (кровля, асфальт, покос, колодцы,
    # снос), то на компьютерном диалоге он не должен судить вовсе. Но проба показала
    # обратное: гард снимал ВЕРНЫЙ отказ на «крышу перекрыть», сказанное в диалоге с
    # телевизионного объявления — а крышу мы не кроем независимо от того, по какому
    # объявлению пришёл клиент. Боевой случай 30.08 («покосить вирус») закрыт там, где
    # ему и место — сужением самого словаря по признаку «что косят».
    # скупка — это ПРЕДЛОЖЕНИЕ продать нам технику. Вопрос о цене детали и
    # отрицание («скупке он не нужен») — возражение по цене, его ведёт модель.
    if kind == "скупка" and (_ЗАПЧАСТЬ_ЦЕНА_RX.search(t)
                             or _СКУПКА_ОТРИЦАНИЕ_RX.search(t)
                             or (_САМ_ПРОДАМ_RX.search(t) and not _К_НАМ_RX.search(t))):
        return True
    # матрица-отказ — про ТВ; экран НОУТБУКА и МОНОБЛОКА меняем (обычная работа КП)
    if kind == "матрица" and _LAPTOP_RX.search(предмет_t) and not _TV_RX.search(t):
        return True
    # ⚠ ПЛАНШЕТ — НЕ ТВ (аудит 30.08): «разбит экран планшета» получал финальный отказ
    # «матрицами не занимаюсь», а регламент В-004 шлёт планшеты в СОГЛАСОВАНИЕ. Отказ
    # отпускаем — ветку подхватит соглас-тема «планшеты» ниже по конвейеру.
    if kind == "матрица" and re.search(r"планшет|ipad|айпад", предмет_t) \
            and not _TV_RX.search(t):
        return True
    # ⚠ СТАЦИОНАРНЫЙ/КНОПОЧНЫЙ/РАДИОТЕЛЕФОН — согласование, не отказ (аудит 30.08):
    # отказ «телефоны» съедал собственную соглас-ветку ниже.
    if kind == "телефоны" and re.search(r"стационарн|кнопочн|радиотелефон", предмет_t):
        return True
    # ⚠ УРОНИЛИ НЕ ЭКРАН, А ПРИНАДЛЕЖНОСТЬ. «Уронил пульт от телевизора» — обычная
    # работа, а не разбитая матрица: падал не телевизор. Проверяем, что стоит сразу
    # ЗА глаголом удара; если там пульт, подставка, кронштейн или коробка — отказ
    # снимаем. Ошибиться здесь дороже вдвое: ложный отказ выбрасывает живой лид.
    if kind == "матрица" and not _МАТРИЦА_ПРЯМАЯ_RX.search(t) \
            and _УДАР_ПО_МЕЛОЧИ_RX.search(t):
        return True
    # «утопил телефон, достаньте фото» — это ВОССТАНОВЛЕНИЕ ДАННЫХ, оно по согласованию,
    # а не отказ. Ценный лид, отшивать шаблоном нельзя.
    if kind == "телефоны" and _DATA_RECOVERY_RX.search(t):
        return True
    # матрица МОНИТОРА (без ТВ в тексте) — согласование, не отказ
    if kind == "матрица" and _MONITOR_RX.search(предмет_t) and not _TV_RX.search(t):
        return True
    # «настроить пульт... приставка триколор» — это работа с пультом, берём
    if kind == "спутниковое ТВ" and _REMOTE_RX.search(t):
        return True
    # батарейка пульта при ЖИВОЙ ТВ-проблеме рядом — модель откажет по батарейке,
    # а телевизор возьмёт (шаблон похоронил бы весь лид)
    if kind == "батарейка пульта" and (_PULT_TV_WORK_RX.search(t)
                                       or _BATT_DONE_RX.search(t)
                                       or _PULT_BROKEN_RX.search(t)):
        return True
    # L2-05: ремонт/прошивка ТВ-приставки, ресивера, кинотеатра «Триколор» —
    # СОГЛАСОВАНИЕ (регламент ТВ п.4), отказ 06.03.2026 закрыл только
    # подключение/настройку спутниковых антенн. ⚠ «не триколор» голым куском
    # писать нельзя — ловится внутри «к антенне Триколор».
    if kind == "спутниковое ТВ" and _STB_RX.search(t) and _STB_REPAIR_RX.search(t):
        return True
    # ГАЗ лишь упомянут рядом с мебельной/кухонной/сантехнической работой — берём
    if kind == "газ" and _GAS_CONTEXT_OK.search(t) and not _GAS_DIRECT.search(t):
        return True
    # ПОДСВЕТКА/инвертор ЖК — это не матрица, регламент велит брать.
    # Сюда же случай «слово матрица есть, но клиент говорит, что она цела».
    if kind == "матрица" and (_BACKLIGHT_RX.search(t) or _MATRIX_OK_RX.search(t)) \
            and not _MATRIX_HARD_RX.search(t):
        return True
    # ВСКРЫТИЕ отказываем, ЗАМЕНУ замка берём — это разные работы
    if kind == "замок" and _LOCK_REPLACE_RX.search(t) \
            and not re.search(r"вскр|захлопнул|без\s*ключ", t):
        return True
    # «телефон» здесь — контакт клиента или названа ДРУГАЯ техника, а не ремонт телефона
    if kind == "телефоны" and (_PHONE_AS_CONTACT.search(t) or _OTHER_TECH_RX.search(t)):
        return True
    # «замените картридж» на дисплее / «поменяли картридж, стал мазать» = ремонт принтера
    if kind == "заправка" and _PRINTER_SYMPTOM_RX.search(t) \
            and not re.search(r"заправ|заправк|тонер\w*\s*(?:долит|засып)", t):
        return True
    # L2-02: РЕМОНТ/ДИАГНОСТИКА принтера при УПОМЯНУТОЙ заправке («стоимость заправки…
    # перестал печатать») — регламент КП велит брать ремонт принтеров/МФУ/копиров без
    # согласования, отказ 08.12.2025 касается только самого картриджа. Симптом ОБЯЗАТЕЛЕН
    # вместе с принтерным словом, иначе освободим чистые «заправьте картридж».
    # Ход уйдёт модели, refuse_topic подскажет отказать по одной позиции.
    if kind == "заправка" and _PRINTER_CTX_RX.search(t) and _PRINTER_SYMPTOM_RX.search(t):
        return True
    return False


def check_refuse(text, предмет=""):
    """Отказ по шаблону, до модели. `предмет` — вся речь клиента за диалог.

    ⚠ ПРЕДМЕТ РАБОТЫ НАЗЫВАЮТ ОДИН РАЗ, А ОТКАЗ СЧИТАЕТСЯ ПО ПОСЛЕДНЕЙ РЕПЛИКЕ — И ЭТО
    СТОИЛО ЗАЯВКИ (снимок владельца 27.08). Клиент спросил «Заменой матрицы на ноутбуках
    занимаетесь?» — исключение `_LAPTOP_RX` сработало, бот ответил «Да, занимаюсь»,
    уточнил модель и предложил приехать. Через пять реплик клиент написал «Меня интересует
    цена замены матрицы» — слова «ноутбук» в ЭТОЙ реплике нет, исключение не сработало, и
    бот выдал «матрицами не занимаюсь». Развернулся на 180° после собственного согласия;
    владелец: «бот чуть не слил заявку, я пытался её как-то спасти».

    ⚠ КОНТЕКСТ УМЕЕТ ТОЛЬКО СНИМАТЬ ОТКАЗ И НИКОГДА ЕГО НЕ СОЗДАЁТ. Соблазн симметрии
    («раз ноутбук помним, давайте и телевизор помнить») ошибочен: тогда «настроить
    телевизор» из первой реплики похоронило бы ноутбучную матрицу из десятой. Здесь же
    написано, почему нельзя — ложный отказ выбрасывает живой лид, а пропущенный отказ
    всего лишь доходит до человека.
    """
    t = _cap(text).lower()
    # предмет ищем и в последней реплике, и во всей речи: назвали один раз — считается
    предмет_t = (t + " " + _cap(предмет or "").lower()).strip()
    # клиент сам снял вопрос — отказывать ему по теме не за что (см. _ОТМЕНА_ЯВНАЯ_RX)
    if _ОТМЕНА_ЯВНАЯ_RX.search(t):
        return None
    for kind, rx, reason in _REFUSE:
        if rx.search(t):
            # СМЕСЬ: запретная позиция + принимаемая работа рядом → шаблоном не гасим,
            # отдаём модели (подсказка в _fields_note через refuse_topic)
            if _refuse_is_mixed(kind, t, rx):
                return None
            if _гард_снимает_отказ(kind, t, предмет_t):
                continue
            # ⚠ 12.08.2026 — СВЕРКА С ЖИВЫМ РЕГЛАМЕНТОМ. Отказывать мы вправе только там,
            # где регламент отказывает ПРЯМО. Таких тем две: газовое оборудование («с
            # бойлерами и плитами, имеющими газовые элементы, не работаем») и вскрытие
            # замков («вскрытием замков мы не занимаемся»). Всё остальное, чего нет в
            # списке «без согласования», идёт ПО СОГЛАСОВАНИЮ: в регламенте дважды
            # написано «просто так отказать клиенту, не уточнив у города, запрещено».
            # Детекторы и все их исключения оставлены как есть — меняется только исход.
            if kind in REFUSE_AS_SOGLAS:
                return {"kind": "soglas", "sub": kind,
                        "reason": "по регламенту согласование, не отказ: " + reason,
                        "draft": SOGLAS_REPLY}
            return {"kind": "refuse", "sub": kind, "reason": reason,
                    "draft": _refuse_text(kind, text)}
    return None


