# ---- ФИЛЬТР МУСОРА: тролли/приколы/оффтоп/инъекции (0 токенов, узко и осторожно) ----
# ВАЖНО (вывод многоагентного разбора всего корпуса 2487 диалогов): реального мусора
# ~0.04% — канал почти чист. Это ЗАЩИТНЫЙ КЛАПАН от будущих троллей, НЕ экономия токенов.
# Принцип: точность >> полнота. Короткое/цифровое/с эмодзи/странное НИКОГДА не режем.
# Каждый regex адверсариально прогнан против ВСЕГО корпуса (11.5К сообщений) → 0 ложных.
# Политики: close=вежливо закрыть (как отказ); operator=молча оператору; nudge=один
# нейтральный вопрос (даём шанс, диалог продолжается); ignore_comply=не подчиняться инъекции,
# ответить нейтрально по делу. close только для ОДНОЗНАЧНОГО оффтопа; неоднозначное → nudge.
# Признаки, что реплика — про ремонт/заявку, какой бы странной она ни была (аудит 15.08).
_REPAIR_CTX_RX = re.compile(
    r"почин|отремонт|ремонт|не\s*работает|не\s*греет|не\s*крутит|не\s*включа|слома\w*|"
    r"искрит|течёт|течет|протека|засор|мастер\w*|заявк|запис\w*|перенес|давайте\s*(?:лучше\s*)?"
    r"(?:завтра|сегодня|позже)|по\s*времени", re.IGNORECASE)

_JUNK_INJECT = re.compile(
    r"(?:игнорир\w*|проигнорир\w*|забудь(?:те)?)\s+(?:все\s+|всё\s+)?(?:мои\s+|прошл\w+\s+|предыдущ\w+\s+)?"
    r"(?:инструкц\w+|правил\w+|промпт\w*|указани\w+)"
    r"|ignore\s+(?:all\s+)?(?:the\s+)?(?:previous\s+)?(?:instruction|prompt)"
    r"|(?:ты\s+теперь|ты\s+больше\s+не|веди\s+себя\s+как|представь\s+что\s+ты|притворись\s+что\s+ты"
    r"|act\s+as|system\s+prompt|систем\w*\s+промпт)|jailbreak|\bdan\s+mode\b")
_JUNK_KEYSMASH = re.compile(
    r"(?:qwerty|asdfgh|zxcvbn|йцукен|фывапр|ячсмит|ывапро|цукенг|укенгш|апролд)"
    r"|([а-яёa-z])\1{6,}"                                  # 7+ одинаковых символов подряд
    r"|(?<![а-яёa-z0-9])[бвгджзйклмнпрстфхцчшщъь]{8,}(?![а-яёa-z0-9])")   # 8+ согласных без гласной
_JUNK_BARE_PING = re.compile(r"^[\s?!.,)(«»…？；¿‼–—\-]+$")   # только знаки препинания (первый ход)
# ВСЁ сообщение — одно приветствие (плюс пунктуация). Проверяется только на первом ходе.
# ⚠ Порядок альтернатив: полные формы ПЕРЕД усечёнными («добрый день» раньше «добрый»),
# иначе хвост «день» не даст матчу дойти до конца строки.
_GREET_ONLY_RX = re.compile(
    r"^(?:здравствуйте|здравствуй|здрасьте|здрасте|приветствую|привет|"
    r"добрый\s+день|добрый\s+вечер|доброе\s+утро|доброй\s+ночи|"
    r"доброго\s+(?:дня|вечера|утра|времени(?:\s+суток)?)|добрый|доброе|доброго|"
    r"салам\s*алейкум|ассаламу?\s*алейкум|салам|hello|hi)"
    r"[\s.,!?)(«»…-]*$", re.IGNORECASE)
_JUNK_SEXUAL = re.compile(
    r"постел\w+\s+хочу\s+с\s+(?:вами|тобой)|интим\w*\s+услуг|секс\w*\s+за\s+деньг"
    r"|(?:познаком\w+|девушк\w+)\s+для\s+интим|для\s+интим\w*\s+(?:встреч|услуг)|интим\w*\s+знаком"
    # +04.08: «массаж интимный делаете?» уходило модели и ловилось формулой согласования
    r"|массаж\w*\s+интим|интим\w*\s+массаж|эротич\w*\s+массаж")
# Деловые предложения и вербовка (04.08): это НЕ заявка и НЕ «согласование» — короткая честная
# фраза и человеку. Раньше модель отвечала «сверюсь по графику», что палило бота.
_JUNK_BUSINESS = re.compile(
    r"хот(?:им|ел\w*)\s+сотрудничат|предлага\w+\s+сотрудничеств|поставщик\w*\s+(?:запчаст|детал|товар)"
    r"|оптов\w+\s+(?:цен|поставк)|коммерческ\w+\s+предложен|разместит\w*\s+реклам"
    r"|хочу\s+(?:к\s+вам\s+)?(?:на\s+)?работ(?:ать|у)\b|есть\s+ли\s+вакансии|ищ[уюе]\s+(?:работу|подработк\w*)"
    r"|(?:дайте|скиньте)\s+(?:контакт\w*|номер)\s+(?:начальств|руководств|директор)"
    r"|\bсколько\s+(?:вы\s+)?(?:плат\w+|получа\w+)\s+мастер")
_JUNK_FOOD = re.compile(
    r"(?:закаж\w+|привез\w+|достав\w+|хочу|нужн\w+|можно|доставьте)(?:\s+\w{1,14}){0,3}\s+"
    r"(?:пицц\w|шаурм\w|шаверм\w|суши(?![а-яё])|ролл(?:ы|ов|ами)(?![а-яё])|бургер\w*|шашлык\w*)")
_JUNK_POLITICS = re.compile(
    # ⚠ было «голосу\w+» — прошедшее время «голосовали» не ловилось (правка 04.08)
    r"за\s+кого\s+(?:вы\s+|ты\s+)?(?:голос\w+|болеешь)"
    r"|(?:ты|вы)\s+за\s+(?:путин\w*|войн\w+|\bсво\b)"
    r"|(?:поддержива\w+|ты\s+против|вы\s+против)\s+(?:войн\w+|\bсво\b|путин\w*)")
_JUNK_INSULT = re.compile(
    # «робот» без «пылесоса»: робот-пылесос — ТЕХНИКА, «робот пылесос тупой стал,
    # кружит на месте» — это заявка на ремонт, а не оскорбление бота (аудит 15.08)
    r"\b(?:ты|вы|бот|робот(?!\s*-?\s*пылесос)|ассистент)\b[^.!?\n]{0,12}\b"
    r"(?:туп(?:ой|ая|ые|ое)|дебил\w*|идиот\w*|придур\w+|дурак\w*|мудак\w*|клоун\w*|уёбо?к|долбо[её]б\w*|даун\w*)\b"
    r"|\b(?:пош[её]л|иди)\s+(?:ты\s+)?на\s*х(?:уй|ер)?\b")

# Хамство и агрессия. ⚠ ТОНКОСТЬ (правка заказчика 04.08): «давайте спокойно» само по себе —
# нотация, это уже ловили. Оно работает ТОЛЬКО после признания эмоции: сначала «понимаю, что
# бесит», потом приглашение разобраться. Порядок обратный — снова получаем учителя.
# Ротация по профилю: один и тот же человек видит стабильный ответ, разные — разные.
# Смягчение сухого отказа от бесплатной работы (правка заказчика 04.08). Модель на этом месте
# дрейфует к голому «работаю платно» — после такого человек уходит с обидой. Гард ловит отказ БЕЗ
# личной причины и дописывает её: формулировку модели не трогаем, добавляем недостающее тепло.
_PAY_REFUSE_RX = re.compile(
    # только настоящие отказы: опциональное «не» превращало «бесплатно смогу
    # посмотреть» в отказ и подменяло позитив (аудит 16.08)
    r"работаю\s+платно|бесплатно\s+не\s+(?:смогу|могу|получится|делаю|езжу|работаю)|"
    r"не\s+(?:могу|смогу)\s+бесплатно", re.IGNORECASE)
# признаки, что причина уже названа по-человечески — тогда не трогаем
_PAY_REASON_RX = re.compile(
    r"заработок|этим\s+и?\s*живу|кормл|работаю\s+один|по\s+минимуму|бензин|"
    r"на\s+выезды\s+трач|единственн\w*\s+доход|семью\s+кормлю", re.IGNORECASE)
# три части отказа: тёплое признание → причина через себя → открытая дверь
_PAY_SOFT = [
    "Понимаю, но это мой единственный заработок, бесплатно ездить не получается. "
    "Будет возможность, напишите, помогу",
    "Хотел бы помочь, но работаю один, этим и живу, даром выехать не выйдет. "
    "Появятся деньги, обращайтесь, сделаю по минимуму",
    "Ситуация непростая, понимаю. Но я сам на выезды трачусь, бензин и время, "
    "поэтому бесплатно никак. Если решите, пишите, всегда на связи",
    # ⚠ ПУЛ РАСШИРЕН 26.08 ПОД ТРЕБОВАНИЕ УНИКАЛЬНОСТИ. Пул из трёх-четырёх фраз
    # это потолок в три-четыре разных ответа: роутерная реплика уходит клиенту
    # ЦЕЛИКОМ из пула, и повтор виден невооружённым глазом. Нижняя граница
    # держится набором test_unikalnost (пул меньше шести — провал).
    "Понял вас. Рад бы помочь, но выезд это мой бензин и моё время, бесплатно не выйдет. Появится возможность, напишите",
    "Понимаю, сейчас с деньгами непросто. Но я работаю один и живу этим, даром съездить не смогу. Решите, пишите, помогу",
    "Жаль, но бесплатно не получится, это мой заработок. Я на связи, обращайтесь, когда будет возможность",
    "Сочувствую, правда. Только с этого я и живу, поэтому за так выехать не смогу. Как появится возможность, обращайтесь",
    "Хотел бы выручить, но каждый выезд из своего кармана. Будет возможность, пишите, сделаю по минимуму",
]
_SENT_SPLIT_RX = re.compile(r"(?<=[.!?…])\s+|\n+")


def soften_pay_refusal(reply, seed=""):
    """Сухой отказ «работаю платно» → отказ с признанием, личной причиной и открытой дверью.

    ⚠ Именно ЗАМЕНА, а не дописка: если приклеить причину к готовому «бесплатно не смогу»,
    отказ звучит дважды — ровно то, что запрещено правилом. Срабатывает только когда причина
    НЕ названа: живую формулировку модели с объяснением не трогаем."""
    r = (reply or "").strip()
    if not r or not _PAY_REFUSE_RX.search(r) or _PAY_REASON_RX.search(r):
        return r
    soft = _PAY_SOFT[sum(ord(c) for c in str(seed or r)) % len(_PAY_SOFT)]
    parts = [p for p in _SENT_SPLIT_RX.split(r) if p.strip()]
    kept, placed = [], False
    for part in parts:
        if _PAY_REFUSE_RX.search(part):
            if not placed:                      # первую отказную фразу меняем, остальные убираем
                kept.append(soft)
                placed = True
            continue
        kept.append(part.strip())
    if not kept:
        return soft
    # склейка через точку: без неё вставленная фраза слипалась со следующей («по минимуму Что у вас…»)
    out = ""
    for part in kept:
        if out and out[-1] not in ".!?…":
            out += "."
        out += (" " if out else "") + part
    return out.strip()


