JUNK_REPLIES = {
    "prompt_inject": "Я обычный частный мастер по ремонту, помогаю только по технике и быту. "
                     "Подскажите, что у вас сломалось, разберёмся.",
    "keysmash": "Кажется, сообщение набралось не полностью. Напишите, пожалуйста, что нужно "
                "отремонтировать, помогу.",
    "bare_ping": "Здравствуйте\nПодскажите, что случилось, что нужно посмотреть или отремонтировать?",
    "greet_only": "Здравствуйте\nЧто у вас случилось?",
    "sexual": "Извините, я мастер по ремонту техники и быту — по таким вопросам помочь не смогу.",
    "food_order": "Я занимаюсь ремонтом техники и быта, еду не вожу. Если что-то сломалось — пишите, помогу.",
    "politics": "Я по политике не общаюсь, я про ремонт. Нужна помощь по технике или быту — пишите.",
    # Правка заказчика 04.08: на оскорбление бот МОЛЧАЛ (пустой draft) — в чате это читается как
    # игнор и злит сильнее хамства. Живой мастер не огрызается, но и не пропадает: одна спокойная
    # фраза и передача человеку.
    # ⚠ 04.08: голое приветствие — САМОЕ частое первое сообщение в корпусе (528 раз за период,
    # вчетверо чаще следующего). Один фиксированный ответ на всех 35 аккаунтах — это отпечаток:
    # человек, написавший на несколько наших объявлений (а по правилу «>5 аккаунтов» такие есть),
    # увидит слово в слово одно и то же. Ротация по профилю клиента: сам клиент видит стабильный
    # ответ, а разные люди — разные формулировки.
    # ⚠ правка заказчика 04.08: прежнее «давайте спокойно и по делу» читалось как нотация
    # («звучит как учитель») и злило сильнее. Живой мастер не поучает — он сглаживает и
    # сразу предлагает помощь.
    "insult_to_bot": INSULT_VARIANTS[0],   # ротация — через insult_draft(seed) в server
    "business_offer": "Я частный мастер, работаю сам — по таким вопросам не подскажу. "
                      "Если что-то нужно починить, пишите, помогу.",
    # ⚠ 12.08 (живой корпус): 151 диалог начинается голым «Спасибо» — это хвост разговора,
    # который Jivo сохранил отдельным куском. Модель на него ОТКРЫВАЛА воронку заново
    # («Что у вас случилось с техникой?») — для клиента, который уже попрощался, это палево.
    "closing": "Пожалуйста! Если что-то ещё понадобится по технике или быту, пишите, помогу.",
    # ⚠ 12.08: 50 диалогов с «уже не актуально / нашли другого мастера / отмените вызов».
    # Заявка уже существует — бот её не ведёт, но и воронку заново открывать нельзя:
    # короткое спасибо и человеку, он снимет заявку.
    "cancel": "Понял, спасибо, что предупредили. Если что-то понадобится, пишите, помогу.",
}
# Голая благодарность/прощание ВСЕЙ репликой (не «спасибо, а во \bсколько приедете?»)
_JUNK_CLOSING = re.compile(
    r"^\W*(?:большое\s+)?(?:спасибо|спс|благодар\w*|пока|всего\s+доброго|до\s+свидания)"
    r"(?:\s+(?:большое|огромное|вам|за\s+ответ|за\s+помощь))*\W*$", re.IGNORECASE)
# Снятие заявки: клиент отказывается от уже созданного вызова
_JUNK_CANCEL = re.compile(
    r"отмен\w*\s*(?:заявк|запись|визит|вызов)|уже\s*не\s*актуальн|не\s*актуальн\w*\s*(?:уже|больше)?|"
    r"нашл\w*\s*друг\w*\s*(?:мастер|специалист)|забронировал\w*\s*друг|вызвал\w*\s*друг\w*\s*мастер",
    re.IGNORECASE)

# (sub, regex, policy). Порядок = приоритет; bare_ping проверяется отдельно (только первый ход).
_JUNK_RULES = [
    ("prompt_inject", _JUNK_INJECT, "ignore_comply"),
    ("sexual", _JUNK_SEXUAL, "close"),
    ("politics", _JUNK_POLITICS, "close"),
    ("food_order", _JUNK_FOOD, "close"),
    ("insult_to_bot", _JUNK_INSULT, "operator"),
    ("business_offer", _JUNK_BUSINESS, "operator"),
    ("keysmash", _JUNK_KEYSMASH, "nudge"),
    ("cancel", _JUNK_CANCEL, "operator"),
]


def check_junk(text, prior_client_content=False):
    """Узкий фильтр явного мусора. Возвращает {kind,sub,policy,reason,draft} или None.

    prior_client_content=True — клиент уже присылал содержательное (с буквами/цифрами) сообщение;
    тогда «голый пинг» (только знаки препинания) НЕ гасим шаблоном, а отдаём модели (у неё есть
    контекст ответить по делу — это торопящий уже ждущий клиент, а не новый)."""
    t = _cap(text).strip().lower()
    if not t:
        return None
    # ССЫЛКИ ВЫРЕЗАЕМ: в товарной ссылке Avito сидит base64-хвост «?context=H4sIAAAAAAAA_…»,
    # и ветка keysmash (7+ одинаковых букв подряд) принимала его за клавиатурную кашу — рабочий
    # лид со ссылкой на объявление получал «Кажется, сообщение набралось не полностью».
    # Режем ТОЛЬКО для матчинга правил: _JUNK_BARE_PING ниже работает по исходному тексту.
    t_nourl = re.sub(r"https?://\S+", " ", t)
    for sub, rx, policy in _JUNK_RULES:
        if rx.search(t_nourl):
            # ⚠ РЕМОНТНЫЙ КОНТЕКСТ ПОБЕЖДАЕТ МУСОР (аудит 15.08). Четыре живых класса,
            # где правило точное, а реплика — целевая: «нужно починить бургер-гриль»
            # (гриль — техника, а не еда), «забудьте предыдущие указания по времени,
            # давайте завтра» (клиент отменяет СВОИ указания, не наши инструкции),
            # «стиралка пищит ееееее и не крутит» (писк — звукоподражание при полном
            # описании поломки). Принцип файла «точность >> полнота» требует в споре
            # отдавать ход модели, а не закрывать живой лид шаблоном.
            if sub in ("food_order", "prompt_inject") and _REPAIR_CTX_RX.search(t_nourl):
                continue
            if sub == "keysmash":
                # каша — это КАША: если после вычета каши остаётся ≥3 содержательных
                # слов, это описание поломки со звукоподражанием, а не смэш
                rest = rx.sub(" ", t_nourl)
                if len([w for w in re.findall(r"[а-яёa-z]{3,}", rest)]) >= 3:
                    continue
                # ⚠ РАСТЯНУТАЯ БУКВА — ЭТО ЭМОЦИЯ, А НЕ КАША (26.08, три живых промаха).
                # «Дааааааааа, приезжайте», «Сеееееееейчас могу», «Аааааааа, тогда
                # кабельное» — согласие и уточнение, а бот отвечал «Кажется, сообщение
                # набралось не полностью». Прежний выход требовал ТРЁХ содержательных
                # слов, а согласие короткое: «приезжайте» — одно.
                # Отличаем по причине, а не по длине: сжимаем растянутые буквы до двух
                # (в русском есть двойные) и смотрим, остаётся ли каша. Если нет — буква
                # была тянущейся, и это слово. Голое «аааааааа» без слов кашей остаётся.
                сжатое = re.sub(r"([а-яёa-z])\1{2,}", r"\1\1", t_nourl)
                if not rx.search(сжатое) and re.search(r"[а-яёa-z]{3,}", сжатое):
                    continue
            return {"kind": "junk", "sub": sub, "policy": policy,
                    "reason": "нецелевой/мусорный запрос: " + sub,
                    "draft": JUNK_REPLIES.get(sub, "")}
    # ГОЛОЕ ПРИВЕТСТВИЕ первым сообщением (2.8% ходов; живые операторы отвечают встречным
    # приветствием-приглашением) — вызов модели не нужен, 0 токенов (аудит C2-4).
    # ⚠ Только ПЕРВОЕ сообщение: «Здравствуйте» посреди диалога — вернувшийся клиент, к модели.
    if not prior_client_content and _GREET_ONLY_RX.match(t):
        return {"kind": "junk", "sub": "greet_only", "policy": "nudge",
                "reason": "первое сообщение — только приветствие, без сути",
                "draft": JUNK_REPLIES["greet_only"]}
    # «голый пинг» (только «?»/«))»/«...») — лишь в ПЕРВОМ сообщении клиента, иначе к модели
    if not prior_client_content and _JUNK_BARE_PING.search(t):
        return {"kind": "junk", "sub": "bare_ping", "policy": "nudge",
                "reason": "пустой пинг (только знаки препинания) в первом сообщении",
                "draft": JUNK_REPLIES["bare_ping"]}
    # ГОЛАЯ БЛАГОДАРНОСТЬ/ПРОЩАНИЕ всей репликой — разговор закончен, воронку не открываем.
    # Работает и в середине диалога: «Спасибо» после записи — это точка, а не новый заход.
    if _JUNK_CLOSING.match(t):
        return {"kind": "junk", "sub": "closing", "policy": "nudge",
                "reason": "благодарность/прощание — закрываем вежливо, без вопроса воронки",
                "draft": JUNK_REPLIES["closing"]}
    return None


# ---- ОБЯЗАТЕЛЬНЫЕ ОЗВУЧКИ ЦЕН (детерминированный до-озвучиватель, 0 токенов) -----
# Регламент ТРЕБУЕТ всегда называть: ремонт видеокарты — от 5000; пайка/гнёзда ЖК-ТВ —
# от 5000; игровые приставки (PS/Xbox/Switch) — от 1500. Модель забывает это ~через раз.
# Здесь бэкстоп: если тема хода ЯВНО про это, а нужного числа нет ни в ответе, ни в прежних
# репликах бота — дописываем короткую фразу. Срабатывает узко, чтобы не всплыть невпопад.
_GPU_RX = re.compile(r"видеокарт|видюх|видеочип|\bgpu\b|geforce|radeon|\brtx\b|\bgtx\b")
_GPU_REPAIR_RX = re.compile(
    r"ремонт|почин|отремонт|не\s*работает|сгорел|артефакт|полос|греет|перегрев|"
    r"не\s*включ|нет\s*(?:сигнал|изображ|картин)|померл|умерл|сдохл|мёртв|мертв|"
    r"замен\w*\s*чип|реболл|отвал|битые\s*пиксел")
_GPU_CLEAN_RX = re.compile(r"чист|термопаст|обслуж|профилакт|\bпыл")
# основа «паять» во всех формах: пайка/паять/припаять/перепаять/запаять/выпаять/пропаять/реболл
_SOLDER_CORE = r"(?:пропа[йя]|перепа[йя]|припа[йя]|запа[йя]|спа[йя]|выпа[йя]|па[йя]к|пая[тюеьл]|реболл)\w*"
_SOLDER_TV_RX = re.compile(
    _SOLDER_CORE + r".{0,30}(?:тв|телевизор|подсветк|плат|шлейф|hdmi|разъ[её]м|гнезд)|"
    r"(?:тв|телевизор).{0,25}" + _SOLDER_CORE + r"|"
    r"(?:замен|ремонт|почин)\w*.{0,20}(?:hdmi|usb)?\s*(?:разъ[её]м|гнезд)\w*.{0,25}(?:тв|телевизор)|"
    r"(?:тв|телевизор).{0,25}(?:разъ[её]м|гнезд)\w*.{0,20}(?:слома|отвал|сгорел|шатает|не\s*держ|замен)")
_CONSOLE_RX = re.compile(
    r"playstation|плейстейшн|плейстешн|\bps[2-5]\b|\bxbox\b|иксбокс|"
    r"nintendo|нинтендо|dualshock|dualsense|игров\w*\s*(?:приставк|консол)|"
    r"приставк\w*\s*(?:sony|сони|майкрософт|xbox|ps\d|для\s*игр)")
# «от 1500» — обязательная озвучка регламента за ЧИСТКУ и НАСТРОЙКУ приставки.
# ⚠ РЕМОНТ СЮДА НЕ ВХОДИТ: регламент КП разводит их однозначно — «Без согласования: чистка и
# настройка PS/Nintendo Switch/Steam Deck, чистка Xbox — от 1500. По согласованию: прошивка и
# ремонт любых приставок, настройка Xbox». Приклейка «чистка ИЛИ РЕМОНТ приставки от 1500»
# обещала взять в работу то, что требует согласования, да ещё и по цене чистки.
_CONSOLE_SETUP = re.compile(r"подключ|настро|настрой|подсоедин|подключить\s*к|к\s*телевизор|к\s*тв\b|каналы")
_CONSOLE_CLEAN = re.compile(r"чист|пыл|термопаст|профилактик")
_CONSOLE_REPAIR = re.compile(r"ремонт|почин|не\s*работает|не\s*включ|греет|перегрев|шум|сломал|тормоз|виснет|зависает")

_HAS_5000 = re.compile(r"5000|5\s*000|пять\s*тыс")
_HAS_1500 = re.compile(r"1500|1\s*500|полторы\s*тыс|полутора")
# КП-техника: обязательная озвучка «выезд+диагностика 1000» (регламент: всегда). ТВ сюда НЕ входит.
_KP_RX = re.compile(r"ноутбук|ноут\b|компьютер|\bпк\b|моноблок|систем\w*\s*блок|винд|windows|принтер|printer|"
                    r"laptop|notebook|computer|\bмфу\b|роутер|сервер|видеокарт|материнск|биос|bios", re.IGNORECASE)
# ⚠ (?<!с)варочн: «СВАРОЧНЫЕ работы» ловились через подстроку «варочн» и уводили направление
# в БТ (сверка матрицы 04.08, СКВ-2). Торговый холод (винный шкаф/витрина/ларь) — это ХОЛОД,
# а не мебель: «винный шкаф не охлаждает» ловился _MNC_OBJ_RX через «шкаф» и уезжал в МНЧ,
# где плейбук велит соглас холода вместо приёма БТ (сверка 04.08, БТ-1).
# ⚠ «винный шкаф» — ТОЛЬКО с холодильным симптомом рядом: без него это сборка мебели
# («производство винных шкафов, собрать и упаковать» — живой МНЧ-лид в корпусе).
_BT_BIG_RX = re.compile(r"стиральн|стиралк|машинк\w*\s*стир|холодильник|морозилк|посудомо|"
                        r"духовк|электроплит|(?<!с)варочн|\bсвч\b|микроволн|водонагреват|бойлер|сушильн|кофемашин|"
                        r"холодильн\w*\s*витрин|витрин\w*\s*холодильн|морозильн\w*\s*лар|"
                        r"(?:винн\w*\s*шкаф|шкаф\w*\s*винн)\w*[^.!?]{0,45}"
                        r"(?:не\s*охлажда|не\s*холоди|не\s*мороз|не\s*работа|не\s*включ|не\s*держ|"
                        r"тепл|температур|ремонт|почин|слома|барахл|компрессор|фреон|поте[кч]|течёт|течет)|"
                        r"(?:ремонт|почин|не\s*работает)\w*[^.!?]{0,30}(?:винн\w*\s*шкаф|шкаф\w*\s*винн)", re.IGNORECASE)
# ⚠ IGNORECASE ДОБАВЛЕН 26.08 И ЭТО ПОЧИНКА, А НЕ УКРАШЕНИЕ. Четыре предметных регекса
# (_TV_RX, _BT_BIG_RX, _KP_RX, _MNC_RX) были собраны без учёта регистра, а люди начинают
# сообщение с большой буквы: «Телевизор сони...», «Принтер Pantum bm 2302», «Роутер хуавей».
# Заглавных литералов в самих шаблонах нет ни одного — регистр здесь ничего не различал,
# он просто терял слова. Замер по 30 428 живым диалогам: _TV_RX не видел предмет в 611
# диалогах (2,0 %), _KP_RX в 386, _MNC_RX в 215, _BT_BIG_RX в 99, а problem_stated из-за
# этого отвечала «поломка не названа» на 406 диалогов (1,3 %) — и бот вырезал из ответа
# адрес со временем и переспрашивал «что у вас случилось?» человека, который уже всё
# написал. Ровно эта жалоба стоит вторым пунктом в «Правках бота» от владельца.
_TV_RX = re.compile(r"телевизор|телек\b|\bтв\b|плазм|кинескоп", re.IGNORECASE)
# МНЧ-работы: там условие выезда своё («по городу бесплатный»), формула 1000 в МНЧ разрешена
# регламентом только партнёру 723, а мы 7 (стр. 743 и 1521 полного регламента).
_MNC_RX = re.compile(
    r"смесител|сифон|раковин|мойк|унитаз|биде|полотенцесушител|ванн|душев|засор|прочист|"
    r"труб|\bкран\b|счётчик|счетчик|розетк|выключател|люстр|светильник|бра\b|автомат\b|проводк|"
    r"щиток|лампочк|мебел|шкаф|кухн|комод|стол\b|стеллаж|полк|карниз|гардин|зеркал|картин|"
    r"кронштейн|навес|турник|сушилк|замок|замк|ручк\w*\s*двер|двер|окн[аоу]|плинтус|ламинат|"
    r"линолеум|порожек|потолочн\w*\s*плитк|сборк|собрать|разобрать|повесить|установ\w*\s*(?:полк|шкаф)", re.IGNORECASE)
# ── НАПРАВЛЕНИЕ ДИАЛОГА (правило заказчика 01.08.2026) ──────────────────────────────
# «На 1 направление 1 заявка. Если проблема КП — использовать регламент КП, если МНЧ —
# регламент МНЧ.» Направление задаёт ПЕРВОЕ обращение и дальше НЕ МЕНЯЕТСЯ: заявка уходит
# в одну базу, и проверять приём по всем трём регламентам сразу не нужно.
# Вторая задача из ЧУЖОГО направления — это НЕ вторая заявка: по ней отвечаем в рамках
# СВОЕГО регламента (пример заказчика: пришли с настройкой ТВ, спрашивают «повесите?» →
# «с настройкой помогу, установкой не занимаюсь» / «скажу только по месту»).
_DIR_ORDER = ("kp", "bt", "mnc")
# ⚠ ТЕЛЕВИЗОР НАПРАВЛЕНИЯ НЕ ЗАДАЁТ. Правка заказчика 01.08.2026: «некоторые вещи принимаются
# в 3 направления, такие как ТВ, но регламент приёма у них один — логика приёмки ТВ одинаковая
# для КП, МНЧ и БТ». То есть ТВ не признак направления, а сквозная тема со своим регламентом:
# заявка по ТВ может прийти в любое из трёх. Поэтому при классификации ТВ пропускаем и смотрим
# следующий предмет; если других нет — направление берём из метки Jivo (по какому объявлению
# пришли), а правила приёма ТВ применяются одни и те же в любом случае.


# ⚠ НАПРАВЛЕНИЕ ЗАДАЁТ ПРЕДМЕТ, А НЕ ГЛАГОЛ. _MNC_RX держит и действия («повесить»,
# «собрать») — для приклейки озвучек это правильно, а для классификации гибельно:
# «ПОВЕСИТЬ телевизор на стену» уходило в МНЧ, потому что глагол стоит раньше предмета.
# Здесь список только из ПРЕДМЕТОВ.
_MNC_OBJ_RX = re.compile(
    r"столешниц|смесител|сифон|раковин|мойк|унитаз|биде|полотенцесушител|\bванн|душев|засор|"
    # ⚠ «КРАН» БЫЛ ЗАПЕРТ В ИМЕНИТЕЛЬНОМ ПАДЕЖЕ (\bкран\b): «замена крана», «поменять
    # краны», «течь в кранах» направления не задавали вовсе — 16 живых первых обращений
    # корпуса уходили в направление ОБЪЯВЛЕНИЯ. Падежи перечислены поимённо, а не \w*:
    # закрытый конец нужен, чтобы «кранбукса» не считалась отдельным предметом; начальная
    # граница слова обязательна — иначе внутрь попадёт «эКРАН».
    r"\bтруб|\bкран(?:а|у|ы|ов|ам|ами|ах|ом|е)?\b|счётчик|счетчик|розетк|выключател|люстр|"
    r"светильник|\bбра\b|"
    # ⚠ «щиток» не ловил падежи: «в щиткЕ», «из щиткА» — а это самая частая форма в
    # живой речи. Поймано тестом 19.08: «тумблер в щитке выбивает» оставался без
    # направления, хотя это чистая электрика.
    r"\bавтомат\b|проводк|щитк\w*|щиток|лампочк|мебел|шкаф|кух(?:н|онн)|гарнитур|комод|\bстол\b|стеллаж|\bполк|"
    # ⚠ МЕБЕЛЬ, КОТОРОЙ В СПИСКЕ НЕ БЫЛО (сверка живых первых реплик 19.08). Сборка
    # кровати, дивана, тумбы, кресла и столика — ядро работ МНЧ, а направления они не
    # задавали: 460 первых обращений корпуса оставались без направления, и ещё 20
    # уезжали в ЧУЖОЕ («сборка компьютерного столика», «собрать кресло компьютерное»
    # уходили в КП, потому что единственным предметом там опознавался «компьютер»).
    # «тумб» с закрытым концом — иначе внутрь попадает «ТУМБЛер» (живая реплика про щиток).
    r"\bкроват|\bдиван|\bкресл|\bматрас|\bэтажерк|\bантресол|\bстолик|"
    r"\bтумб(?:а|ы|у|е|ой|ою|ам|ами|ах|очк\w*)?\b|"
    # ⚠ «КАРТИНКА» — ЭТО ИЗОБРАЖЕНИЕ, А НЕ КАРТИНА НА СТЕНЕ. Голый корень «картин» ловил
    # «нет картинки», «зависает картинка», «тусклая картинка» — 106 живых первых реплик
    # корпуса, и ВСЕ до одной про экран (просьб повесить картинку нет ни одной). 27 из них
    # получали направление МНЧ: ремонт материнской платы уезжал к мебельщикам.
    r"карниз|гардин|зеркал|картин(?!к)|кронштейн|турник|сушилк|замок|замк|двер|окн[аоуе]|"
    r"плинтус|ламинат|линолеум|порожек|потолочн\w*\s*плитк|москитн|вешалк|крючок")
_KP_OBJ_RX = re.compile(
    r"ноутбук|ноут\b|компьютер|\bпк\b|моноблок|систем\w*\s*блок|винд|windows|принтер|"
    r"laptop|notebook|computer|\bмфу\b|роутер|сервер|видеокарт|материнск|биос|bios|"
    r"монитор|сканер|копир|плоттер|приставк|ресивер|антенн")


def direction_of(text):
    """Направление по СУТИ задачи: 'kp' | 'bt' | 'mnc' | '' (не определилось).

    Считаем по САМОМУ РАННЕМУ упоминанию ПРЕДМЕТА: клиент называет свою задачу первой,
    а дальше могут мелькать чужие слова («ноутбук стоит на СТОЛЕ» — это КП, а не мебель).
    Совпадений нет → пустая строка, направление возьмётся из метки Jivo.
    """
    t = _cap(text).lower()
    hits = []
    for name, rx in (("kp", _KP_OBJ_RX), ("bt", _BT_BIG_RX), ("mnc", _MNC_OBJ_RX)):
        for m in rx.finditer(t):        # перебор, а не первое: первое могло быть омонимом
            if not _начало_слова(t, m.start()):
                continue
            hits.append((m.start(), name))
            break
    # ПЛИТА КАК ПРИБОР — отдельным проходом, потому что у неё свои омонимы: строительная
    # плита (бетон, ОСБ, перекрытия) прибором не является, а «плитка» иногда наоборот им
    # является («электрическая плитка через раз включается»).
    for m in _ПЛИТА_RX.finditer(t):
        # ⚠ ОРИЕНТИР, А НЕ ЗАКАЗ: «шкаф НАД плитой», «вырезать ПОД плиту» — плита тут
        # только место, а работа мебельная. Корпус: 14 таких диалогов.
        if re.search(r"(?:над|под|за|возле|около|рядом\s+с|вокруг)\s*$", t[:m.start()]):
            continue
        if _начало_слова(t, m.start()) and not _СТРОЙПЛИТА_RX.search(_клауза(t, m.start())):
            hits.append((m.start(), "bt"))
            break
    for m in re.finditer(r"плитк\w*", t, re.IGNORECASE):
        ф = _клауза(t, m.start())
        if _ПЛИТКА_ПРИБОР_RX.search(ф) and not _СТРОЙПЛИТА_RX.search(ф) \
                and not re.search(r"кафел|керамогранит|ванн\w*\s+плитк|положит|укла", ф, re.I):
            hits.append((m.start(), "bt"))
            break
    if not hits:
        return ""                       # в т.ч. чистый ТВ-запрос: направление даст метка Jivo
    hits.sort()
    # ТВ СТОИТ РАНЬШЕ ЛЮБОГО ДРУГОГО ПРЕДМЕТА — значит ПЕРВАЯ задача про телевизор, а она
    # направления не задаёт. Тогда решает метка объявления, а не предмет из второй фразы:
    # «телевизор настроить и полку повесить» — это НЕ мебельная заявка.
    _tv = _TV_RX.search(t)
    if _tv and _tv.start() < hits[0][0]:
        return ""

    # ── РАБОТА, А НЕ СЛОВО (решение владельца 18.08) ──
    # (1) техника, которую СТАВЯТ, а не чинят, — это МНЧ, а не БТ. Холод исключён:
    #     холодильники МНЧ не принимает ни в каком виде (регламент, смежная зона).
    def _в_мнч(поз, напр):
        """Монтаж техники — работа МНЧ. Холод — исключение регламента, но МЕБЕЛЬНАЯ
        работа с холодом (фасад, встройка, перенавес двери) снова МНЧ: её делает
        мебельщик, а не мастер по технике (решение владельца 18.08, вариант B)."""
        if напр != "bt" or not _монтаж_без_поломки(t, поз):
            return напр
        if not _FRIDGE_SUBJ_RX.search(_клауза(t, поз)):
            return "mnc"
        _фр = _фрагмент(t, поз)
        return "mnc" if (_МЕБЕЛЬНАЯ_ХОЛОД_RX.search(_фр) or _ФУРНИТУРА_RX.search(_фр)) else напр

    hits = [(поз, _в_мнч(поз, напр)) for поз, напр in hits]
    hits.sort()

    # (2) две НАСТОЯЩИЕ работы разных направлений → МНЧ. Настоящая = предмет и признак
    #     работы в ОДНОЙ фразе, иначе «ноутбук на столе» станет мебельной заявкой.
    #     Почему МНЧ: у него филиалы есть в 55 городах, где у БТ их нет (обратных — 2),
    #     а регламент МНЧ принимает всю бытовую технику, кроме холода. Холод — исключение:
    #     там заявка обязана уйти в БТ, вторая работа уходит в комментарий карточки.
    настоящие, занятые_слова, холод_в_работе = [], set(), False
    for поз, напр in hits:
        сл = _слово(t, поз)
        if сл in занятые_слова or not _начало_слова(t, поз):
            continue                     # «посудоМОЙКа», «оптоволОКНО» — один предмет
        занятые_слова.add(сл)
        if _работа_рядом(t, поз, узко=True) and напр not in настоящие:
            настоящие.append(напр)
            # ⚠ ХОЛОД МНЧ НЕ ПРИНИМАЕТ НИ В КАКОМ ВИДЕ — ни в ремонт, ни в установку
            # (регламент смежной зоны). Первая версия правила требовала здесь ПРИЗНАК
            # ПОЛОМКИ, и «холодильник устанавливаете в мебель?» уезжал в МНЧ — то есть
            # оговорка «кроме холода» аннулировалась ровно в той ветке, ради которой
            # правило писалось. Исключение одно: работа по МЕБЕЛЬНОЙ ФУРНИТУРЕ
            # («доводчик дверцы», «отрегулировать двери шкафов со встроенными
            # холодильниками») — это мебель, БТ такого не делает.
            _фр = _фрагмент(t, поз)
            if напр == "bt" and _FRIDGE_SUBJ_RX.search(_фр):
                # РЕМОНТ холода → БТ (регламент: «Только для БТ»). МЕБЕЛЬНАЯ работа с
                # холодом → МНЧ, там работает мебельщик. Поломка сильнее слова
                # «встроенный»: «встроенный холодильник не морозит» — это ремонт.
                _ремонт = _ПОЛОМКА_RX.search(_фр) and not _ФУРНИТУРА_RX.search(_фр)
                _мебель = _МЕБЕЛЬНАЯ_ХОЛОД_RX.search(_фр) or _ФУРНИТУРА_RX.search(_фр)
                if _ремонт or not _мебель:
                    холод_в_работе = True
    if len(настоящие) > 1:
        # ⚠ ХОЛОД ПЕРЕВЕШИВАЕТ, ТОЛЬКО ЕСЛИ ОН И ЕСТЬ РАБОТА. Раньше хватало слова
        # «холодильник» где угодно в тексте, и мебельные заказы («отрегулировать
        # двери шкафов со встроенными холодильниками», «перевесить дверь
        # холодильника») уезжали в БТ, где такую работу не делают.
        if холод_в_работе:
            return "bt"
        return "mnc" if "mnc" in настоящие else настоящие[0]
    return hits[0][1]


# ── ПРАВИЛО «НАПРАВЛЕНИЕ РЕШАЕТ РАБОТА, А НЕ СЛОВО» (решение владельца 18.08) ──
#
# ЗАЧЕМ. Направление выбиралось по САМОМУ ЛЕВОМУ предмету в тексте, поэтому
# «стиралка не отжимает и смеситель течёт» и «смеситель течёт и стиралка не
# отжимает» уезжали в РАЗНЫЕ лид-центры. Из 40 проверенных смесей порядок слов
# переворачивал вердикт в 36. Но дороже другое: из 733 диалогов, где вердиктом
# вышло БТ, в 148 (20.2%, ~28 в неделю) поломки НЕТ вовсе — есть монтаж,
# установка, подключение. По регламенту это работа МНЧ, а слово «стиральная
# машина» утаскивало заявку в БТ-лид-центр, где у 55 городов нет филиала.
#
# ЧТО ТЕПЕРЬ. Предмет сам по себе направления не задаёт — его задаёт РАБОТА
# рядом с предметом, в той же фразе:
#   • техника + поломка          → БТ («стиралка не отжимает»);
#   • техника + монтаж/подключение → МНЧ («стиральную машину подключить»),
#     кроме холода: холодильники МНЧ не принимает ни в каком виде;
#   • обе работы настоящие и из разных направлений → МНЧ (справочник шире на
#     55 городов против 2, выезд бесплатный там и там), опять же кроме холода.
_МОНТАЖ_RX = re.compile(
    r"установ|устанавл|подключ|подсоедин|подключение|навес|повес|привес|встро|врез|"
    r"перенест|перевес|закреп|прикрут|прибит|смонтир|монтаж|собра|разобра|"
    r"помен|замен|поставит|провест|развест|прочист|устран|отрегулир|подрегулир|"
    # ⚠ ВЫРЕЗ В СТОЛЕШНИЦЕ — МЕБЕЛЬНАЯ РАБОТА (корпус 18.08: 57 диалогов «вырезать под
    # мойку и плиту», где плита — только габарит выреза). Без этих глаголов правило
    # «монтаж → МНЧ» их не спасало, и столешницы уезжали к мастерам по технике.
    r"вырез|выпил|прорез|запил|подрез|врезк|"
    r"сделат|нужен\s+мастер|нужна\s+помощ", re.IGNORECASE)

_ПОЛОМКА_RX = re.compile(
    r"не\s*(?:работа|включ|греет|мороз|холод|отжима|слива|крут|набира|стира|"
    r"суш|запуска|загружа|закрыва|держ|печата|показыва|реаг|запус)|"
    r"слома|сгорел|теч[ёе]т|подтека|проте[кч]|течет|гуд[еи]т|шум[иы]т|ошибк|"
    r"ремонт|почин|чинит|диагностик|перестал|глючит|искр|выбива|запах\s+гар|"
    r"барахл|дым|мига|не\s+исправ", re.IGNORECASE)


#: СОСТАВНЫЕ СЛОВА, где предмет стоит ВТОРОЙ частью и остаётся собой:
#: термоПРИНТЕР — принтер, водоСЧЁТЧИК — счётчик, электроПЛИТА — плита.
#: ⚠ «посудо» сюда НЕ входит: «посудоМОЙКа» — это посудомойка, а не мойка.
_ПРИСТАВКИ = ("термо", "водо", "электро", "газо", "тепло", "гидро", "радио",
              "фото", "видео", "аудио", "микро", "нано", "мото", "авто",
              # живые опечатки корпуса: «элетродуховка», «електроплита», «злектро»
              "элетро", "електро", "злектро", "эл", "электра")


def _начало_слова(t, pos):
    """Совпадение стоит в НАЧАЛЕ слова — либо после известной приставки.

    ⚠ «ОптоволОКНО» содержит «окно», «посудоМОЙКа» — «мойку», «сбросить
    счётчик» ловится в «счётчике печати». Пока направление выбирал самый левый
    предмет, такие куски были безобидны; правилу «две работы → МНЧ» они видятся
    ВТОРОЙ работой — и ремонт роутера уезжал к оконщикам (10 диалогов корпуса).
    ⚠ НО ГОЛАЯ ГРАНИЦА СЛОВА ЛОМАЛА СОСТАВНЫЕ: «термопринтер» переставал быть
    принтером, «водосчётчик» — счётчиком (39+20 диалогов корпуса ушли «по метке»).
    Поэтому приставки из списка выше границу не рвут.
    """
    # ⚠ ДЕФИС — ГРАНИЦА: «DNS-сервер» это сервер, «3D-принтер» — принтер,
    # «ТВ-приставка» — приставка. Склеивание через дефис теряло предмет целиком.
    if pos == 0 or not t[pos - 1].isalpha():
        return True
    нач = pos
    while нач > 0 and t[нач - 1].isalpha():
        нач -= 1
    return t[нач:pos] in _ПРИСТАВКИ


def _слово(t, pos):
    """Границы слова, внутри которого стоит совпадение.

    ⚠ ЗАЧЕМ. В «посудоМОЙКе» сидит МНЧ-предмет «мойка», в «дверце холодильника» —
    «дверь», в «замке люка стиралки» — «замок». Пока направление выбиралось по
    самому левому предмету, это было безобидно; правилу «две работы → МНЧ» такие
    подстроки видятся ВТОРОЙ работой, и обычная посудомойка уезжает в сантехнику.
    Совпадения внутри одного и того же слова — это одна вещь, а не две.
    """
    н = pos
    while н > 0 and (t[н - 1].isalpha() or t[н - 1] == "-"):
        н -= 1
    к = pos
    while к < len(t) and (t[к].isalpha() or t[к] == "-"):
        к += 1
    return н, к


def _клауза(t, pos):
    """Фраза вокруг позиции: работа считается «своей», если она в ОДНОЙ фразе с предметом.

    Иначе «ноутбук стоит на столе, шкаф собрать не надо» превращается в смесь:
    предмет одного направления и действие другого просто оказались в одном тексте.
    """
    нач = max((t.rfind(з, 0, pos) for з in ".!?;\n"), default=-1)
    конц = [i for i in (t.find(з, pos) for з in ".!?;\n") if i != -1]
    return t[нач + 1:(min(конц) if конц else len(t))]


#: ПЛИТА КАК ПРИБОР (решение владельца 18.08). В словаре предметов её не было вовсе —
#: только «электроплита» и «варочная», поэтому «Ремонт плиты сколько стоит?» и «Плита
#: индукционная не работает» вообще не получали направления и уезжали по метке
#: объявления. По корпусу: 355 диалогов со словом «плит» — техника 192, кафель 144,
#: строительная плита 17. Форма БЕЗ «-к-» («плита/плиту/плиты/плите/плитой») встречается
#: в 169 диалогах и НИ РАЗУ не означает кафель: кафель в живой речи всегда «плитка».
_ПЛИТА_RX = re.compile(r"(?<![а-яё])плит(?:а|у|ы|е|ой|ою|ам|ами|ах)?(?![а-яё])", re.IGNORECASE)

#: СТРОИТЕЛЬНАЯ ПЛИТА — не прибор: бетон, ОСБ, перекрытия, звукоизоляция (17 диалогов).
_СТРОЙПЛИТА_RX = re.compile(
    r"бетон|железобетон|ж/б|\bосб\b|\bосп\b|\bдсп\b|перекрыти|фундамент|"
    r"звукоизол|шумоизол|утеплител|пенопласт|минерал|стык\w*\s+плит|плит\w*\s+на\s+(?:стен|потол)|"
    r"стена\s+плита|потолочн\w*\s+плитк", re.IGNORECASE)

#: «ПЛИТКА» ИНОГДА И ЕСТЬ ПЛИТА (21 диалог корпуса): «электрическая плитка через раз
#: включается», «плитка перестала работать 4 конфорочная». Живые операторы это понимают
#: и переспрашивают «марку модель ПЛИТЫ подскажите» — бот теперь тоже.
_ПЛИТКА_ПРИБОР_RX = re.compile(
    r"конфорк|комфорк|включа|включ[ие]|не\s+работает|перестал|греет|варочн|духовк|"
    r"индукцион|электрическ|стеклокерамик|нагрева", re.IGNORECASE)

#: ⚠ КОМПЬЮТЕРНЫЕ ОМОНИМЫ. «Игры вылетают на рабочий СТОЛ» — это экран Windows, а не
#: мебель; «сбросить СЧЁТЧИК печати» — счётчик принтера, а не воды. Правило «две работы
#: → МНЧ» уводило чистый ремонт ПК в мебельно-сантехническую базу, где его никто не
#: сделает: заявка теряется целиком (найдено состязательной проверкой 18.08).
_ЛОЖНЫЙ_МНЧ_RX = re.compile(
    r"рабоч\w*\s+стол\w*|стол\w*\s+windows|счётчик\w*\s*(?:печат|страниц|тонер|"
    r"памперс|абсорбер|картридж)|сброс\w*\s+счётчик|оптоволок|оптико[-\s]?волок|"
    r"окн\w*\s+(?:браузер|программ|windows|виндовс|проводник)", re.IGNORECASE)

#: ⚠ ИНДИКАТОР, А НЕ СВЕТИЛЬНИК. «Горит лампочка включения» у ноутбука — это описание
#: поломки техники, а не заказ на электрику. Без этой оговорки правило «две работы →
#: МНЧ» уводило в сантехнику обычный ремонт ноутбука (проверено на корпусе).
_ИНДИКАТОР_RX = re.compile(
    r"(?:горит|горят|мига|моргае|светит|индикатор|светодиод|\bдиод)\w*\s+(?:\w+\s+){0,2}?лампочк|"
    r"лампочк\w*\s+(?:включени|питани|зарядк|индикац|ошибк)", re.IGNORECASE)

#: «шкаф собирать НЕ надо», «стиралку подключать не нужно» — это не заказ работы.
_НЕ_НАДО_RX = re.compile(r"не\s+(?:надо|нужно|требует|хочу|буд(?:у|ет)|проси|заказыва)", re.IGNORECASE)


def _фрагмент(t, pos):
    """Короткий кусок вокруг предмета — для ОПИСИ работ в карточке заявки.

    Дробим мельче клаузы (ещё и по запятой, «и», «ещё», «также»): диспетчеру в
    комментарии нужна «розетку поменять», а не пересказ всей реплики.
    ⚠ Для определения «есть ли рядом работа» granularity остаётся крупной
    (_клауза): «стиралку, которая не отжимает, посмотреть» — признак работы
    стоит за запятой, и мелкое дробление потеряло бы его.
    """
    гр = [m.end() for m in re.finditer(r"[.!?;,\n]|\bи\b|\bещ[её]\b|\bтакже\b", t)]
    нач = max([g for g in гр if g <= pos] or [0])
    кон = min([g for g in гр if g > pos] or [len(t)])
    return t[нач:кон].strip(" ,.;и")


def _работа_рядом(t, pos, узко=False):
    """Есть ли рядом с предметом признак РАБОТЫ — поломка или монтаж.

    ⚠ УЗКО=True — для СПОРА двух направлений: там признак обязан стоять в своём
    фрагменте («смеситель течёт»), а не где-то в той же длинной фразе. Иначе
    поломка одного предмета приписывается соседнему слову: «не включается
    ноутбук, горит лампочка включения» становилось смесью КП и электрики.
    """
    ф = _фрагмент(t, pos) if узко else _клауза(t, pos)
    if not ф or _НЕ_НАДО_RX.search(ф):
        return False
    if _ИНДИКАТОР_RX.search(ф):
        return False        # «горит лампочка» — это про технику, а не про свет
    if _ЛОЖНЫЙ_МНЧ_RX.search(ф):
        return False        # «рабочий стол», «счётчик печати» — компьютерные слова
    return bool(_ПОЛОМКА_RX.search(ф) or _МОНТАЖ_RX.search(ф))


#: ЗАМЕНА ДЕТАЛИ — ЭТО РЕМОНТ, А НЕ МОНТАЖ. «Поменять резинку в стиральной машине»,
#: «заменить тэн», «поменять насос» — работа мастера по технике, хотя глагол тот же,
#: что у монтажа. Меняют ПРИБОР — это МНЧ; меняют его ВНУТРЕННОСТЬ — это БТ.
_ДЕТАЛЬ_RX = re.compile(
    r"резинк|манжет|\bт[еэ]н\b|нагревател\w*\s*элемент|спирал|конфорк|"
    r"насос|помп|подшипник|"
    r"\bремен\b|ремень|уплотнител|термостат|датчик|\bплат[уаы]\b|модул|щётк|щетк|"
    r"фильтр|шланг|патрубок|амортизатор|клапан|таймер|прессостат", re.IGNORECASE)

#: МЕБЕЛЬНАЯ РАБОТА С ХОЛОДИЛЬНИКОМ (решение владельца 18.08, вариант «B»).
#: Регламент делит не по технике, а по РАБОТЕ: «Холодильники/Морозилки (Только для БТ):
#: РЕМОНТ и настройка» — это БТ; «Услуги Мебельщика: ремонт, сборка и установка мебели
#: принимается без согласования» — это МНЧ. Встроить холодильник в нишу, повесить на него
#: фасад, перенавесить дверь — работа мебельщика, а не мастера по технике: он такого не
#: делает. Живой корпус согласен: 28 диалогов «встройка + холод», диспетчеры взяли 16.
#: ⚠ ПОЛОМКА ВСЕГДА СИЛЬНЕЕ: «встроенный холодильник не морозит» — это ремонт, значит БТ.
_МЕБЕЛЬНАЯ_ХОЛОД_RX = re.compile(
    r"встро|встра|\bв\s+нишу|\bв\s+мебель|\bв\s+гарнитур|\bв\s+кухн|фасад|"
    r"перенавес|перевес\w*\s+двер|навес\w*\s+двер|регулир\w*\s+двер|"
    r"столешниц|распаков", re.IGNORECASE)

#: МЕБЕЛЬНАЯ ФУРНИТУРА ПРИ ВСТРОЕННОЙ ТЕХНИКЕ — работа МНЧ. «Сломался доводчик дверцы
#: встроенного холодильника» — это мебель, а не холодильник: мастер БТ такое не делает.
_ФУРНИТУРА_RX = re.compile(
    r"доводчик|петл[июяе]|креплени|направляющ|фасад|ламел|ручк[аиуе]\s|"
    r"\bдвер\w*\s+(?:шкаф|кухн|фасад|гарнитур)", re.IGNORECASE)


def _монтаж_без_поломки(t, pos):
    """Технику ставят/подключают, а не чинят — по регламенту это МНЧ."""
    ф = _клауза(t, pos)
    if _ДЕТАЛЬ_RX.search(_фрагмент(t, pos)):
        return False                      # замена внутренностей = ремонт техники
    return bool(_МОНТАЖ_RX.search(ф)) and not _ПОЛОМКА_RX.search(ф)


# холодильная техника КАК ПРЕДМЕТ (для смежной зоны МНЧ⊃БТ: холодильники МНЧ не принимает)
# «холодильн» вместо «холодильник»: холодильная витрина/камера — тоже холод (сверка 04.08)
_FRIDGE_SUBJ_RX = re.compile(r"холодильн|морозильн|морозилк|винн\w*\s*шкаф|шкаф\w*\s*винн")


#: Тип плиты назван словом клиента — газовая/электрическая/индукционная.
_ТИП_ПЛИТЫ_RX = re.compile(r"газов|электрическ|электро|индукцион|стеклокерамик|"
                           r"\bэл\.?\s*плит|на\s+газ", re.IGNORECASE)
#: Приборы, у которых газовый вариант СУЩЕСТВУЕТ (у стиралки и холодильника его нет —
#: спрашивать там «газовая или электрическая?» значит мгновенно спалить бота, п.207 плейбука).
# ⚠ «плит» БЕЗ ГРАНИЦЫ ловится внутри «уТЕПЛИТь» — поймано стражем границ слова.
# ⚠ И «плитК» СЮДА НЕ ВХОДИТ (состязательная проверка 18.08, critical): кафель ловился
# наравне с прибором, и клиент, заказавший укладку плитки в ванной, читал в
# ПОДТВЕРЖДЕНИИ ЗАПИСИ вопрос «Плита газовая или электрическая?» — грубее маркера бота
# не придумаешь. 135 таких диалогов в корпусе.
_ГАЗОВОЗМОЖНЫЙ_RX = re.compile(r"варочн|духов|панел\w*\s+на\s+кухн|колонк", re.IGNORECASE)


def stove_type_unknown(client_texts):
    """Плита названа, а тип — нет. Значит вопрос обязателен ДО записи.

    ⚠ РЕГЛАМЕНТ: «С плитами, имеющими газовые элементы не работаем» — и там же разобран
    именно этот провал: «Диспетчер принял заявку „Электроплита BOSСH, не работает нижний
    тэн духовки“, а на месте оказалось, что у клиента газовая плита с электрической
    духовкой, работа с которым не принимается». По корпусу тип не назван в 100 диалогах
    из 169. Живые диспетчеры спрашивают прямо: «плита газовая или электрическая?»
    """
    t = _cap(". ".join(x for x in (client_texts or []) if x)).lower()
    # прибор назван: либо форма без «-к-» (кафеля не означает никогда), либо варочная/
    # духовка, либо «плитка» С ПРИЗНАКОМ ПРИБОРА («плитка перестала греть, 4 конфорки»)
    _прибор = False
    for m in _ПЛИТА_RX.finditer(t):
        if _начало_слова(t, m.start()) and not _СТРОЙПЛИТА_RX.search(_клауза(t, m.start())):
            _прибор = True
            break
    if not _прибор and _ГАЗОВОЗМОЖНЫЙ_RX.search(t):
        _прибор = True
    if not _прибор:
        for m in re.finditer(r"плитк\w*", t, re.IGNORECASE):
            ф = _клауза(t, m.start())
            if _ПЛИТКА_ПРИБОР_RX.search(ф) and not re.search(
                    r"кафел|керамогранит|положит|класт|уклад|демонтир|затирк|зеркальн", ф, re.I):
                _прибор = True
                break
    if not _прибор:
        return False
    return not _ТИП_ПЛИТЫ_RX.search(t)


#: ОБЩАЯ ЗОНА ДВУХ НАПРАВЛЕНИЙ — работы, которые регламент разрешает ОБОИМ.
#: МНЧ, «Подключение бытовой техники»: «Принимаем подключение стиральных машин/
#: посудомоечных машин/сушильных машин, а также водонагревателей к сантехнике» и
#: «подключение электроплит/варочных поверхностей/посудомоечных машин/водонагревателей
#: к электрике». БТ, те же приборы: «Подключение, если сантехника/электрика готова».
#: Раз оба имеют право — выбирать должен ГОРОД (уточнение владельца 18.08).
_ОБЩАЯ_ТЕХНИКА_RX = re.compile(
    r"стиральн\w*\s*машин|стиралк|посудомо|сушильн\w*\s*машин|водонагрев|бойлер|"
    r"(?<![а-яё])плит|варочн|духов", re.IGNORECASE)


#: КЛИЕНТ ПОПРОСИЛ ПАУЗУ. Сценарий «отложил» — 1425 ходов корпуса (1238 диалогов),
#: конверсия 14.4% против базы 11.5%: эти клиенты возвращаются, если их не давить.
#: ⚠ «Напишу/сообщу» засчитывается только вместе с признаком ОТКЛАДЫВАНИЯ (позже,
#: потом, как определимся, не сможем) — иначе «напишите ваш номер» и «я вам напишу
#: адрес» превратились бы в отсрочку.
_ОТСРОЧКА_RX = re.compile(
    r"\bподумаю\b|\bподумать\b|посоветуюсь|посоветоват|"
    r"не\s*(?:сможем|смогу|получится|получается)\b|"
    r"(?:напишу|сообщу|наберу|отпишусь|свяжусь)[^.!?\n]{0,40}"
    r"(?:позже|потом|как\s+определ|когда\s+смож|завтра|на\s+днях)|"
    r"(?:позже|потом|на\s+днях|как\s+определ\w*|когда\s+смож\w*)[^.!?\n]{0,30}"
    r"(?:напишу|сообщу|наберу|свяжусь)|"
    r"пока\s+не\s+(?:готов|нужн|актуал)|давайте\s+(?:позже|потом)", re.IGNORECASE)


def postponed(client_text):
    """Клиент отложил визит и попросил не давить: «я вам напишу когда сможем»."""
    t = _cap(client_text or "")
    return bool(_ОТСРОЧКА_RX.search(t))


def shared_hookup(client_texts):
    """Работа из ОБЩЕЙ ЗОНЫ: подключение/установка техники, которую берут оба направления.

    Только МОНТАЖ: ремонт той же техники — чистое БТ, общей зоной не является.
    """
    t = _cap(". ".join(x for x in (client_texts or []) if x)).lower()
    for m in _ОБЩАЯ_ТЕХНИКА_RX.finditer(t):
        if not _начало_слова(t, m.start()):
            continue
        ф = _фрагмент(t, m.start()) or _клауза(t, m.start())
        if _МОНТАЖ_RX.search(ф) and not _ПОЛОМКА_RX.search(ф):
            return True
    return False


def fridge_repair(client_texts):
    """Клиент просит ПОЧИНИТЬ холод (а не встроить его в мебель).

    Нужно правилу владельца «C» (18.08): по регламенту МНЧ принимает холодильники
    «по согласованию с филиалом… только на те города, где нет филиалов БТ». То есть
    в 55 городах без БТ-филиала ремонт холода обязан уходить в МНЧ со сверкой, а не
    умирать отпиской в базе, где этого города нет вовсе.
    """
    t = _cap(". ".join(x for x in (client_texts or []) if x)).lower()
    for m in _FRIDGE_SUBJ_RX.finditer(t):
        if not _начало_слова(t, m.start()):
            continue
        ф = _фрагмент(t, m.start()) or _клауза(t, m.start())
        # поломка сильнее слова «встроенный»: «встроенный холодильник не морозит» —
        # это ремонт. Фурнитура (доводчик, петли) — наоборот, работа мебельщика.
        if _ПОЛОМКА_RX.search(ф) and not _ФУРНИТУРА_RX.search(ф):
            return True
    return False


def works_in(client_texts):
    """Настоящие работы в речи клиента: [(направление, фраза), …] — для карточки заявки.

    Нужно правилу «одна заявка, весь фронт работ» (решение владельца 18.08): заявка
    уходит по главному направлению, а ВТОРАЯ работа не теряется — она попадает в
    комментарий, чтобы мастер приехал готовым, а диспетчер видел весь объём.
    Живые диспетчеры именно так и работают: за 30 526 диалогов корпуса ни один не
    разделил смешанный заказ на две заявки.
    """
    t = _cap(". ".join(x for x in (client_texts or []) if x)).lower()
    найдено, было, занятые_слова = [], set(), set()
    for имя, rx in (("bt", _BT_BIG_RX), ("kp", _KP_OBJ_RX), ("mnc", _MNC_OBJ_RX)):
        for m in rx.finditer(t):
            сл = _слово(t, m.start())
            if сл in занятые_слова or not _начало_слова(t, m.start()):
                continue                 # подстрока чужого слова, а не отдельный предмет
            занятые_слова.add(сл)
            if not _работа_рядом(t, m.start()):
                continue
            напр = имя
            if имя == "bt" and _монтаж_без_поломки(t, m.start()) \
                    and not _FRIDGE_SUBJ_RX.search(_клауза(t, m.start())):
                напр = "mnc"
            ф = _фрагмент(t, m.start()) or _клауза(t, m.start()).strip()
            if (напр, ф) in было:
                continue
            было.add((напр, ф))
            найдено.append((m.start(), напр, ф))
    найдено.sort()
    return [(напр, ф) for _p, напр, ф in найдено]


def lock_direction(client_texts, label_direction=""):
    """Направление диалога = РЕГЛАМЕНТ, ПО КОТОРОМУ ПРИНИМАЕТСЯ ПРОБЛЕМА (по СУТИ задачи).

    ⚠ РЕШЕНИЕ ЗАКАЗЧИКА 02.08.2026: «при определении проблемы нужно сразу определять,
    по какому регламенту её принимать» — суть задачи ГЛАВНЕЕ метки объявления (это
    отменяет правило 01.08 «направление = направление объявления»; то, в свою очередь,
    отменяло 17b — маятник вернулся по слову заказчика, история в памяти проекта).
    Метка объявления — ЗАПАСНОЙ сигнал: суть не распозналась (чистый ТВ-запрос,
    «мастера вызвать», голое приветствие) → направление объявления.
    Первое определившееся направление ЗАКРЕПЛЯЕТСЯ на весь диалог (одно направление =
    одна заявка — это правило живо). ⚠ ТЕРРИТОРИЮ кросс-принятие НЕ обходит: холодильник
    (суть БТ) в городе без БТ-филиала уйдёт в сверку форсом no_filial в run_relay.
    """
    lab = (label_direction or "").lower()
    lab = lab if lab in _DIR_ORDER else ""
    # ⚠ ПЕРЕСМОТР ПО ВСЕЙ РЕЧИ (решение владельца 18.08). Раньше цикл выходил на ПЕРВОМ
    # сообщении с предметом, и вторая работа, названная на третьем ходу, направление уже
    # не меняла: клиент, добавивший сантехнику к ремонту техники, гарантированно уезжал
    # не в тот лид-центр. Теперь смотрим всю речь — но склеиваем через точку, чтобы
    # признак работы из одного сообщения не приписался предмету из другого.
    # Заявку это не раздваивает: направление убрано из ключа защиты от повторов.
    склейка = ". ".join(t for t in (client_texts or []) if t)
    ess = direction_of(склейка)
    if not ess:
        for t in (client_texts or []):
            d = direction_of(t)
            if d:
                ess = d
                break
    if not ess:
        return lab
    # ⚠ СМЕЖНЫЕ ЗОНЫ РЕГЛАМЕНТОВ (поправка заказчика 02.08 №2: «бот так и не знает регламент —
    # на МНЧ можно принять стиральную машину»). Регламент МНЧ «Бытовая техника» принимает ВСЮ
    # БТ по регламенту БТ, КРОМЕ холодильников. Поэтому БТ-суть на МНЧ-объявлении остаётся
    # заявкой МНЧ — переключение на регламент БТ нужно только холодильникам (их МНЧ не берёт)
    # и обратным случаям (сантехника на БТ-объявлении: регламент БТ её не покрывает → mnc).
    if lab == "mnc" and ess == "bt" and not _FRIDGE_SUBJ_RX.search(
            " ".join(client_texts or []).lower()):
        return "mnc"
    return ess


# «выезд бесплатный» обещаем, только когда это ЗАДАЧА по МНЧ, а не случайное упоминание предмета
_MNC_ACTION_RX = re.compile(
    r"поставит|установ|помен|замен|смени|собра|разобра|повес|навес|подключ|"
    r"почин|отремонт|ремонт|прочист|устран|прибит|прикрут|врез|подтян|заглуш|"
    r"монтир|монтаж|подсоедин|перенест|перевес")
# ПОДКЛЮЧЕНИЕ БТ К САНТЕХНИКЕ = работа МНЧ (регламент, «ВИДЫ РАБОТ МНЧ → Подключение бытовой
# техники», от 1000), а НЕ ремонт бытовой техники. Условие выезда у неё МНЧ-шное.
_MNC_HOOKUP_RX = re.compile(
    r"(?:подключ|подсоедин|устано\w*|поставит|запуст)\w*.{0,30}"
    r"(?:стиральн|стиралк|посудомо|сушильн\w*\s*машин|водонагрев|бойлер)|"
    r"(?:стиральн|стиралк|посудомо|сушильн\w*\s*машин|водонагрев|бойлер)\w*.{0,30}"
    r"(?:подключ|подсоедин|подключен)")
# ⚠ ПРИЗНАКИ ПОЛОМКИ — ОДНО ОПРЕДЕЛЕНИЕ НА ФАЙЛ (24.08). Их было ДВА под одним именем:
# бытовое здесь и компьютерное ниже, у формулы выезда. Второе молча затирало первое при
# импорте, и бытовая половина была мертва весь этот срок — «не сливает», «не отжимает»,
# «не набирает», «не запускается», «не стирает», «не моет», «не сушит», «подтекает»,
# «гудит», «не крутит» поломкой не считались.
#
# Что это стоило: на реплике «подключить стиральную машину, она подтекает» гард
# _drop_diagnostics_on_install считал задачу чистым монтажом и вырезал слово «диагностика»
# из формулы — клиент слышал «Выезд бесплатный» вместо «Выезд и диагностика бесплатные»,
# то есть мы сами теряли аргумент на ремонтной заявке. Мёртвый шаблон питал ещё три
# условия в enforce_callouts (строки 2932, 2989, 2990).
#
# Объединяю, а не выбираю: у обоих потребителей вопрос один — «в задаче есть поломка?»,
# и сузить его значит снова потерять половину. Компьютерная часть пришла из живой пробы
# 30.07, бытовая — из регламента БТ; обе нужны.
_BREAKDOWN_RX = re.compile(
    # бытовая техника (регламент БТ): «не сливает», «подтекает», «гудит»
    r"не\s*(?:работает|включ|сливает|греет|крутит|отжим|набирает|запускается|стирает|моет|сушит)|"
    r"слома\w|сгорел|течёт|течет|проте[кч]|подтекает|гудит|шум[ие]т|ошибк|код\s*ошибк|"
    r"неисправ|ремонт|почин|чин(?:ит|ить|ю)|"
    # компьютеры и ТВ (живая проба 30.07): «тормозит», «синий экран», «полосы»
    r"не\s*(?:грузит|печатает|ловит)|тормоз|вис[нея]|глюч|синий\s*экран|артефакт|полос|"
    r"барахл|перегрев|греет|диагностик|померл|сдохл|отвал")
_PRICE_OR_VISIT_RX = re.compile(r"\bсколько|цен[ауые]|стоит|стоимост|почём|почем|по\s*деньгам|дорог|дешевл|"
                                r"выезд|приезд|за\s*приезд|расцен|прайс")
# вопрос про САМ выезд/диагностику — только тогда бэкстопы дописывают 1000/«бесплатный» (правка заказчика
# 28.07: на первый вопрос цены РАБОТЫ — увод «беру по объёму работ», без навязывания озвучек выезда).
# ⚠ Нужны ОБА сигнала: слово визита И денежный контекст — «позвоните за час до ПРИЕЗДА» не про цену
# (ловился каскад: bt_free клеил «выезд бесплатный», а _ensure_close дожимал «когда удобно?»).
_VISIT_WORD_RX = re.compile(r"выезд|приезд|вызов|диагностик")
_MONEY_CTX_RX = re.compile(r"платн|бесплатн|\bсколько|цен[аыу]|стоимост|стоит|деньг|возьм[её]те|прайс|расценк")


#: ⚠ F-008 (слепая сверка этапа 4): «ну вы можете приехать ЕСЛИ ВЫЕЗД БЕСПЛАТНЫЙ к 18 ч» —
#: это вопрос о деньгах, хотя слова «сколько» в нём нет: клиент ставит условие. Бот отвечал
#: «Что у вас случилось?», живой диспетчер — «выезд по городу бесплатный». Условие клиента
#: надо подтвердить, иначе он поедет проверять к другому мастеру.
_VISIT_COND_RX = re.compile(
    r"если\s+(?:выезд|приезд|осмотр|диагностик)\w*\s*(?:будет\s*)?(?:бесплатн|платн|беспл)|"
    r"(?:выезд|приезд|осмотр)\w*\s*(?:же\s*)?(?:бесплатн|платн)\w*\s*\?|"
    r"при\s+условии\s+(?:бесплатн|беспл)", re.IGNORECASE)


def _visit_price_q(text):
    t = _cap(text).lower()
    if _VISIT_COND_RX.search(t):
        return True
    return bool(_VISIT_WORD_RX.search(t)) and bool(_MONEY_CTX_RX.search(t))


# УСТАНОВКА/ПОДКЛЮЧЕНИЕ: диагностики там нет и быть не может — формула «выезд И ДИАГНОСТИКА 1000»
# на установку роутера звучит нелепо и нарушает регламент (дефект живой пробы 30.07). Условие выезда
# остаётся, слово «диагностика» вырезаем. Срабатывает, только если в задаче НЕТ признаков поломки.
_INSTALL_ONLY_RX = re.compile(r"установ|подключ|настро|настрой|повесить|навесить|собрать|сборк|монтаж|"
                              r"поставить|провести|проложить")
# (второе определение _BREAKDOWN_RX убрано 24.08: оно молча затирало первое.
#  Всё, что было только здесь, перенесено выше — см. разбор у единственного определения.)
# ⚠ «БУДУТ» МЕЖДУ ПОДЛЕЖАЩИМ И СКАЗУЕМЫМ ЛОМАЛО ВЕСЬ РАЗБОР. Модель пишет «Выезд и
# диагностика для вас БУДУТ бесплатны» — этот вид сюда не подходил, срабатывал только грубый
# `_DIAG_PAIR_RX`, который выкидывает «и диагностика» и не трогает глагол. Клиент получал
# «Выезд для вас будут бесплатны» — множественное число при одном подлежащем.
_DIAG_FREE_RX = re.compile(
    r"(выезд)(\w*)\s+и\s+диагностик\w+(\s+для\s+вас)?(?:\s+буд(?:ет|ут))?\s+бесплатн\w+",
    re.IGNORECASE)
_DIAG_PAIR_RX = re.compile(r"(выезд)(\w*)\s+и\s+диагностик\w+|диагностик\w+\s+и\s+(выезд)(\w*)", re.IGNORECASE)


def _drop_diagnostics_on_install(reply, client_text):
    """При установке/подключении диагностики нет — убираем её из формулы выезда."""
    t = (client_text or "").lower()
    # ⚠ ДВА СПИСКА ПОЛОМОК, И ОДНОГО МАЛО (снимок владельца 27.08). Здесь спрашивался только
    # `_BREAKDOWN_RX`; в диалоге про замену матрицы ноутбука он молчал («горит серым»,
    # «изображение не выдаёт» он не знал), зато `_INSTALL_ONLY_RX` поймал слово «подключать»
    # из фразы клиента «Если через HDMI подключать к внешке, то работает» — то есть из ПРОВЕРКИ,
    # а не из задачи. Ремонтная заявка объявлена монтажом, и из формулы выезда вырезали
    # «и диагностика», оставив клиенту «Выезд для вас будут бесплатны».
    if not _INSTALL_ONLY_RX.search(t) or _BREAKDOWN_RX.search(t) or _СИМПТОМ_RX.search(t):
        return reply
    r = _DIAG_FREE_RX.sub(lambda m: m.group(1) + m.group(2) + (m.group(3) or "") + " бесплатный", reply or "")
    r = _DIAG_PAIR_RX.sub(lambda m: (m.group(1) or "") + (m.group(2) or "") + (m.group(3) or "") + (m.group(4) or ""), r)
    if r[:1].islower() and (reply or "")[:1].isupper():   # «Диагностика и выезд» → «Выезд»
        r = r[0].upper() + r[1:]
    return r


# ── ДВЕ ОБЯЗАТЕЛЬНЫЕ ОЗВУЧКИ РЕГЛАМЕНТА, КОТОРЫЕ МОДЕЛЬ ЗАНИЖАЕТ ──────────────────
# Это КОРРЕКТОРЫ, а не приклейки: если цифры в реплике нет (этап 1 лестницы) — не трогаем.
# 1) УСТАНОВКА/ЗАМЕНА самой ванны или душевой кабины = ОТ 8000 (регламент МНЧ «Ванны/душевые»).
#    Общий floor «от 1500» по ванной — это МЕЛКИЕ работы (герметизация, слив, шланг); модель их
#    путает и занижает цену впятеро. Глагол должен стоять ВПЛОТНУЮ к предмету, иначе ловилось
#    «заменить смеситель в ванной» (это от 800).
_BATH_BIG_RX = re.compile(
    r"(?:установ|замен|поменя|смонтир|поставит|врезат)\w*\s+(?:мне\s+|нам\s+|нов\w+\s+|стар\w+\s+){0,2}"
    r"(?:ванн[уыа]\b|душев\w*\s*кабин|душев\w*\s*уголок|душ\w*\s*кабин)|"
    r"(?:ванн[уыа]\b|душев\w*\s*кабин|душев\w*\s*уголок)\s+(?:нужно\s+|надо\s+|хочу\s+){0,2}"
    r"(?:установ|замен|поменя|поставит|смонтир)")
# ⚠ IGNORECASE ОБЯЗАТЕЛЕН: реплики часто НАЧИНАЮТСЯ с цены («От 500 такая работа»), и без
# флага молча отваливались обязательные правки — единица засора и планка белого аккаунта.
# В пуле эталонов 77 из 244 ценовых примеров написаны именно с заглавной «От N».
_FLOOR_PRICE_RX = re.compile(r"от\s*(\d{3,5})", re.IGNORECASE)
# 2) ЗАСОР = 500 ЗА ПОГОННЫЙ МЕТР (регламент МНЧ «Засоры», озвучивать обязательно). Без единицы
#    клиент слышит «500 за весь засор» — на месте спор и потерянная заявка.
_ZASOR_RX = re.compile(r"засор|прочист\w*.{0,20}(?:труб|канализ|слив|стояк)|"
                       r"(?:заб(?:ил|ит)\w*|не\s*уходит\s*вод)\w*.{0,25}(?:труб|канализ|раковин|унитаз|слив)")


# «Электрический или газовый?» законно ТОЛЬКО про бойлер/водонагреватель/плиту/духовку/варочную/колонку.
# У холодильника, стиралки, посудомойки, СВЧ, кофемашины газового варианта НЕ БЫВАЕТ — вопрос мгновенно
# палит бота. Источник ляпа: золотой RAG-пример r1-01 (правка заказчика) с этим хвостом на ХОЛОДИЛЬНИКЕ,
# он попадал в top-1 на каждый холодильный лид и копировался дословно (живая проба 30.07). Пул починен,
# но здесь второй слой — на случай самостоятельного слипа модели и пересборки пула из будущей разметки.
# Вопрос вырезаем; воронку потом восстановит _ensure_question в server.py.
_NO_GAS_APPLIANCE_RX = re.compile(r"холодильник|морозил|морозильн|винн\w*\s*шкаф|стиральн|стиралк|"
                                  r"посудомо|микроволн|\bсвч\b|кофемашин|пылесос|телевизор")
# газовым БЫВАЕТ: бойлер/водонагреватель/колонка/плита/духовка/варочная. Решаем по речи КЛИЕНТА,
# а не по реплике бота: в реплике слово «газовый» есть всегда, иначе гард сам себя блокировал.
_GAS_APPLIANCE_RX = re.compile(r"бойлер|водонагрев|колонк|\bплит|духов|варочн|поверхност|котел|котл")
_GAS_Q_RX = re.compile(r"\s*(?:[.,]\s*)?(?:электрическ\w*\s+или\s+газов\w*|газов\w*\s+или\s+электрическ\w*)"
                       r"(?:\s+(?:холодильник\w*|машинк\w*|техник\w*|стиральн\w*))?\s*\??", re.IGNORECASE)


def _drop_absurd_gas_q(reply, client_text):
    """Срезает вопрос про газ у техники, которая газовой не бывает."""
    ct = (client_text or "").lower()
    if not _NO_GAS_APPLIANCE_RX.search(ct) or _GAS_APPLIANCE_RX.search(ct):
        return reply
    if not _GAS_Q_RX.search(reply or ""):
        return reply
    r = re.sub(r"\s{2,}", " ", _GAS_Q_RX.sub("", reply or "")).strip()
    # реплика состояла ИЗ ОДНОГО этого вопроса — пустой ответ уйдёт как молчание оператору,
    # поэтому оставляем короткий приём, воронку дальше добавит _ensure_question
    if len(r.strip(" .,\n")) < 3:
        return "Да, помогу"
    return r


# ── ПОЛ ОЗВУЧКИ НА «БЕЛЫХ» АККАУНТАХ (партнёр 723) ──────────────────────────────
# Правило заказчика 31.07: 1000 — это МИНИМАЛЬНАЯ планка, а не цена. Работа по прайсу дешевле
# (смеситель/розетка/навес — от 800) → озвучиваем «от 1000». Дороже (от 1500/2000/5000/8000) →
# называем регламентную сумму как есть, поднимать не нужно и занижать нельзя.
# ⚠ ЕДИНИЧНЫЕ РАСЦЕНКИ НЕ ТРОГАЕМ: «от 500 за погонный метр» (засор), «от 350 за м²» (линолеум) —
# это ставка за единицу, а не стоимость услуги; подняв её до 1000, мы удвоили бы счёт клиенту.
# ⚠ ПРИЛАГАТЕЛЬНОЕ ПЕРЕД ЕДИНИЦЕЙ ОБЯЗАТЕЛЬНО РАЗРЕШИТЬ: «за КВАДРАТНЫЙ метр» — это дословная
# формулировка регламента («Услуги ОТ 800 руб. за квадратный метр») и естественная речь модели.
# Без неё планка белого аккаунта поднимала ставку за м² с 350/400/600 до 1000 — на 20 м² клиент
# слышал 20000 вместо 7000, то есть завышение втрое.
_PER_UNIT_AFTER_RX = re.compile(
    r"^\s*(?:р(?:уб\w*)?\.?\s*)?(?:за\s*(?:погонн\w*\s*|квадратн\w*\s*|кв\.?\s*)?"
    r"(?:метр|м\b|м2|м²|шт|штук|точк|издели)|"
    r"/\s*(?:м2|м²|метр|шт))", re.IGNORECASE)


def raise_white_floor(reply, minimum=1000):
    """На «белом» аккаунте поднимает озвучку ниже минимума до него. Цифры не добавляет."""
    r = reply or ""

    def _up(m):
        tail = r[m.end():]
        if _PER_UNIT_AFTER_RX.match(tail):
            return m.group(0)                       # ставка за единицу — не трогаем
        try:
            return ("от %d" % minimum) if int(m.group(1)) < minimum else m.group(0)
        except ValueError:
            return m.group(0)

    return _FLOOR_PRICE_RX.sub(_up, r)


# слова-якоря, по которым цену в реплике связываем с конкретной работой (для СМЕШАННЫХ заявок)
_BATH_WORD_RX = re.compile(r"ванн|душев|кабин", re.IGNORECASE)
_ZASOR_WORD_RX = re.compile(r"засор|прочист|труб|слив|канализ", re.IGNORECASE)


def _fix_reglament_floors(reply, client_text):
    """Правит занижённые обязательные озвучки. Цифры не добавляет — только исправляет.

    ⚠ СМЕШАННАЯ ЗАЯВКА. Раньше правки были «глобальными»: на «поменять ванну И засор прочистить»
    ванный корректор поднимал ВСЕ цены до 8000, а засорный приклеивал «за погонный метр» к первой
    попавшейся — выходило «Ванна от 8000 за погонный метр, засор от 8000». Теперь, если цен
    несколько, каждая правится ТОЛЬКО при своём слове-якоре рядом; если цена одна — контекстом
    считаем всю реплику (прежнее поведение, оно верное).
    """
    r = reply or ""
    t = (client_text or "").lower()
    bath, zasor = bool(_BATH_BIG_RX.search(t)), bool(_ZASOR_RX.search(t))
    if not (bath or zasor):
        return r
    def _owner_map(text):
        """Кому принадлежит каждая цена: смотрим слово-якорь НЕПОСРЕДСТВЕННО ПЕРЕД ней.

        Окно «±45 символов» не годится: реплика «Ванна от 1500, засор от 500» короче окна,
        и оба якоря оказывались «рядом» с обеими ценами. Берём отрезок от предыдущей цены
        до текущей и смотрим, какой якорь в нём последний."""
        out, prev = [], 0
        for m in _FLOOR_PRICE_RX.finditer(text):
            seg = text[prev:m.start()]
            b = max((x.start() for x in _BATH_WORD_RX.finditer(seg)), default=-1)
            z = max((x.start() for x in _ZASOR_WORD_RX.finditer(seg)), default=-1)
            out.append((m, "bath" if b > z else ("zasor" if z > b else None)))
            prev = m.end()
        return out

    owners = _owner_map(r)
    single = len(owners) < 2
    # ⚠ ВАННУ/ДУШЕВУЮ БОЛЬШЕ НЕ ПОДНИМАЕМ АВТОМАТОМ. Раньше здесь любая цена ниже 8000
    # заменялась на 8000 — это была моя ошибка чтения регламента. Заказчик 31.07 дал точный
    # алгоритм: «по месту» → «от 1500» → и только на третьем нажиме сумма из прайса
    # (ванна от 8000 — живой прайс 12.08, душевая от 8000). То есть «от 1500» — ЗАКОННЫЙ второй шаг, и подменять
    # его ценой из прайса нельзя: бот перепрыгивал лестницу и пугал клиента суммой.
    # Правильные цифры и порядок теперь живут в плейбуке (раздел 6 и 11).
    if zasor and "метр" not in r.lower():
        owners = _owner_map(r)
        target = next((m for m, own in owners if single or own == "zasor"), None)
        if target:
            # ⚠ ЗА ВАЛЮТНЫМ СУФФИКСОМ (аудит 30.08): вставка до «р/рублей» давала
            # «за погонный метрр» и «за погонный метр рублей».
            кон = target.end()
            м_суф = re.match(r"\s*(?:рубл\w*|руб\.?|р\.?|₽)", r[кон:], re.IGNORECASE)
            if м_суф:
                кон += м_суф.end()
            r = r[:кон] + " за погонный метр" + r[кон:]
    return r


def _append_clause(reply, clause):
    r = (reply or "").rstrip()
    if not r:
        return clause
    if r[-1] not in ".!?…":
        r += "."
    return r + " " + clause


# ── ЛОГИСТИКА ТОЛЬКО ПОСЛЕ ПОЛОМКИ (правка заказчика 04.08.2026) ────────────────
# Разбор провокаций показал корень палева: на флирт/шутку/голое «здравствуйте» бот
# отвечал вопросом «Куда приехать надо?» — то есть звал выезд, не зная, что чинить.
# Живой мастер сначала выясняет поломку. Держим это КОДОМ: промпт модель нарушает.
_PROBLEM_KNOWN_RX = re.compile(
    r"не\s*(?:работает|включ|сливает|греет|крутит|отжим|набирает|запускается|стирает|моет|сушит|"
    r"морозит|печатает|заряжа|ловит|показыв|горит)|слома\w|сгорел|теч[её]т|подтекает|гудит|шумит|"
    r"ошибк|неисправ|ремонт|почин|чинит|заменит|установ|подключ|повесит|собрат|прочист|навесит|"
    r"настро|перевесит|врезат|замен\w|засор|искрит|дым|разби(?:л|т)\w*|треснул|битый\s*пиксел|"
    # ⚠ ЧЕТЫРЕ ФОРМЫ, КОТОРЫХ ТУТ НЕ БЫЛО (замер 23.08, 4 промаха из 23). Промах стоит дорого:
    # пока поломка «не названа», гард СРЕЗАЕТ вопросы адреса и времени и возвращает разговор
    # к «что у вас случилось?» — то есть бот переспрашивает ровно то, что клиент уже сказал.
    #  · «экран разбит» — знали «разбил», не знали причастие;
    #  · «перестал холодить» — знали «не морозит», но не общую форму «перестал ...»;
    #  · «полосы на экране» — самая частая жалоба по ТВ и ноутбукам;
    #  · «висит на логотипе» — знали «виснет», не знали «висит».
    r"перестал[аио]?\s+\w{3,}|полос\w*\s+(?:на\s+)?(?:экран|дисплее|монитор)|полосит|"
    r"\bвисит\b|"
    # ⚠ ОТСОЕДИНЕНИЕ УЗЛА (снимок владельца 26.08, «кулер отпал»): см. тот же список в
    # _СИМПТОМ_RX. Держим оба в согласии — расходясь, они дают ровно тот класс промахов,
    # ради которого их и заводили.
    r"отпал|отвали\w+|оторва\w+|отклеи\w+|отломa?\w+|отсоедин\w+|отош[её]л|отходит|"
    r"вылетел|выпал|слетел|болтается|шатается|не\s*держ\w+|повис\w*|разъ[её]ха\w+|"
    # частые жалобы, которых не было в списке (стресс-тест: «комп не грузится, синий экран»)
    r"не\s*(?:груз|загруж|видит|читает|реагирует|отвечает|качает|тянет|держит|закрыв|открыв)|"
    r"зависа|виснет|тормоз|глюч|синий\s*экран|перезагру|выключа\w*\s*сам|"
    r"\bкомп\b|\bпк\b|\bноут\b|моноблок|систем\w*\s*блок", re.IGNORECASE)
# вопрос логистики в ответе бота (адрес/время/телефон)
_LOGISTICS_ASK_RX = re.compile(
    # ⚠ формы вопроса разнообразнее, чем кажется: «Куда НУЖНО БУДЕТ приехать?», «Когда могу к вам
    # приехать?», «Когда сможете принять?» — все они звали на выезд мимо гарда (разбор 05.08)
    r"куда\s+(?:мне\s+|нужно\s+|надо\s+|вам\s+)*(?:будет\s+)?(?:подъехать|приехать|ехать)|"
    r"по\s+какому\s+адресу|адрес\w*\s*(?:подскаж|назов|скажите|уточн|какой)|назовите\s+адрес|"
    r"(?:какой|ваш)\s+адрес|квартир\w*[,\s]*подъезд|"
    # ⚠ 12.08: чисто ВРЕМЕННЫЕ формы без глагола приезда проходили мимо («Когда вам было бы
    # удобно?», «В какое время вам удобно?») — и время спрашивалось до названной поломки
    r"когда\s+(?:вам\s+)?(?:было\s+бы\s+|будет\s+)?удобно|во\s+\bсколько|"
    r"в\s+какое\s+время(?:\s+вам)?\s+(?:было\s+бы\s+|будет\s+)?удобно|"
    # ⚠ 12.08, живая проверка: на «Вы работаете в выходные?» бот отвечал «да, работаю в любой
    # день. Завтра к 10:00-10:30 удобно вам?» — предложил окно, хотя поломка НЕ НАЗВАНА.
    # Гард ловил словесные формы, а окно ЦИФРАМИ проходило насквозь.
    r"\d{1,2}[:.]\d{2}\s*(?:-|–|—|до)?\s*(?:\d{1,2}[:.]\d{2})?[\s,]*(?:удобно|подойд|устро|нормально|пойд)|"
    r"(?:завтра|сегодня|послезавтра)\s*к\s*\d{1,2}[:.]?\d{0,2}\s*(?:удобно|подойд|устро)|"
    r"когда\s+(?:я\s+)?(?:могу|смогу)\s+(?:к\s+вам\s+)?(?:приехать|подъехать)|"
    r"когда\s+сможете\s+принять|когда\s+вам\s+помощь\s+нужна|"
    r"номер\w*\s*(?:телефона|оставьте|подскаж|для\s+связи|ваш)|номерок\w*|"
    r"телефон\w*\s*(?:подскаж|оставьте|ваш)|"
    r"территориально\s+вы\s+где", re.IGNORECASE)


# ⚠ УЗЕЛ ТЕХНИКИ — ЭТО ТОЖЕ НАЗВАННЫЙ ПРЕДМЕТ РАБОТЫ. Списки направлений знают приборы
# («телевизор», «холодильник», «компьютер»), но клиент называет ДЕТАЛЬ: «кулер отпал»,
# «шлейф перебит», «петля вырвана». Прибора в тексте нет, и признак возвращал False —
# при том, что ехать очевидно есть к чему. Слова целиком, без «начинается с»: разбор 25.08
# показал 7027 ложных попаданий там, где подстрока искалась внутри слова.
_УЗЕЛ_RX = re.compile(
    r"\b(?:кулер\w*|вентилятор\w*|радиатор\w*|матриц\w*|шлейф\w*|разъ[её]м\w*|петл[иеяю]\w*|"
    r"помп[аыуе]\w*|компрессор\w*|т[еэ]н\b|блок\s*питания|материнк\w*|материнск\w*|"
    r"процессор\w*|видеокарт\w*|клавиатур\w*|тачпад\w*|аккумулятор\w*|батаре[яию]\w*|"
    r"подсветк\w*|инвертор\w*|термопаст\w*|жёстк\w*\s*диск|жестк\w*\s*диск|"
    r"манжет\w*|амортизатор\w*|подшипник\w*|уплотнител\w*|смесител\w*|редуктор\w*)\b",
    re.IGNORECASE)


def problem_stated(client_text):
    """Назвал ли клиент поломку ИЛИ технику/услугу (иначе спрашивать адрес и время рано).

    ⚠ Одних глаголов поломки мало: стресс-тест поймал «комп не грузится, синий экран» —
    оборота «не грузится» в списке не было, и гард срезал ЗАКОННЫЙ вопрос воронки. Поэтому
    засчитываем и НАЗВАННУЮ ТЕХНИКУ/УСЛУГУ: клиент, написавший «комп» или «люстру повесить»,
    тему уже дал — ехать есть к чему. Пусто остаётся у «здравствуйте», «вы бот?» и болтовни.
    Переиспользуем боевые регексы направлений, чтобы не заводить второй список техники."""
    t = _cap(client_text or "")
    return bool(_PROBLEM_KNOWN_RX.search(t) or _BT_BIG_RX.search(t) or _KP_RX.search(t)
                or _MNC_RX.search(t) or _TV_RX.search(t) or _РАБОТА_RX.search(t)
                or _УЗЕЛ_RX.search(t))


# ⚠ ГЛАГОЛЫ-РАБОТЫ БЕЗ СЛОВА-ПОЛОМКИ (аудит регламента 18.08). «Натяжной потолок снять и
# обратно поставить» — работа названа полностью, а problem_stated возвращала False: воронка
# дописывала «Что у вас случилось?» человеку, который уже всё сказал и спрашивает цену.
# Это прямое нарушение п.3b «не переспрашивай то, что клиент уже сказал».
# ⚠ 23.08 СПИСОК ПОДНЯТ НА УРОВЕНЬ МОДУЛЯ: он понадобился второму потребителю (job_stated),
# а спрятанный внутри функции он бы разъехался с ним при первой же правке.
_РАБОТА_RX = re.compile(
    r"\b(?:снять|снимите|демонтир|установ|поставить|подключ|перенест|навес|"
    r"повесить|закреп|собрать|разобрать|поменять|заменить|починить|отремонтир|"
    r"натян|наклеи|покрас|прочист|пробит|запуст|настро)\w*", re.IGNORECASE)

# СИМПТОМ ПОЛОМКИ — то, что ломает «это услуга». Список намеренно НЕ равен _PROBLEM_KNOWN_RX:
# оттуда убраны сервисные глаголы (установ/подключ/настро/собрат/повесит), потому что именно
# они и означают услугу. Симптом имеет ПРИОРИТЕТ: «поставил новую посудомойку, теперь не
# сливает» — это поломка, а не монтаж, и спрашивать «что нужно сделать?» там нельзя.
_СИМПТОМ_RX = re.compile(
    r"не\s*(?:работает|включ|сливает|греет|крутит|отжим|набирает|запускается|стирает|моет|"
    r"сушит|морозит|печатает|заряжа|ловит|показыв|горит|груз|загруж|видит|читает|реагирует|"
    r"отвечает|качает|тянет|держит|закрыв|открыв)|слома\w|сгорел|теч[её]т|подтекает|гудит|"
    r"шумит|ошибк|неисправ|засор|искрит|дым|разби(?:л|т)\w*|треснул|битый\s*пиксел|"
    r"зависа|виснет|\bвисит\b|тормоз|глюч|синий\s*экран|перезагру|выключа\w*\s*сам|"
    r"перестал[аио]?\s+\w{3,}|полос\w*\s+(?:на\s+)?(?:экран|дисплее|монитор)|полосит|"
    # ⚠ ОТСОЕДИНИЛОСЬ — ТОЖЕ ПОЛОМКА (снимок владельца 26.08). Клиент написал «кулер отпал»,
    # и признак вернул False: ни одного из этих глаголов в списке не было. Цена промаха не в
    # формулировке — пока «поломка не названа», гард ВЫРЕЗАЕТ вопросы адреса и времени и
    # возвращает разговор к «расскажите, что случилось». Клиент рассказывает, признак снова
    # не узнаёт его слов, бот снова спрашивает то же самое — дословно.
    r"отпал|отвали\w+|оторва\w+|отклеи\w+|отломa?\w+|отсоедин\w+|отош[её]л|отходит|"
    r"вылетел|выпал|слетел|болтается|шатается|не\s*держ\w+|повис\w*|разъ[её]ха\w+|"
    # ⚠ ЭКРАН, КОТОРЫЙ НИЧЕГО НЕ ПОКАЗЫВАЕТ (снимок владельца 27.08). Клиент написал
    # «Просто горит серым и всё» и «Изображение не выдаёт» — ни один список поломок этих
    # оборотов не знал, и заявка на замену матрицы считалась МОНТАЖОМ.
    r"не\s*(?:выда[её]т|показыв|выводит)|нет\s+(?:изображени|картинк|подсветк)|"
    r"горит\s+(?:серым|бел\w+|ч[её]рн\w+)|(?:сер\w+|ч[её]рн\w+|бел\w+)\s+экран",
    re.IGNORECASE)


def job_stated(client_text):
    """Клиент просит УСЛУГУ (поставить, подключить, собрать), а не чинит поломку.

    ⚠ ЗАЧЕМ (находка по живым диалогам 23.08). Пул уточняющих вопросов выбирался по
    НАПРАВЛ�ению («job-пул только при direction == "mnc"»), а не по типу запроса. На вопрос
    «возможна ли у Вас установка приложений на айфон? И по стоимости?» бот ответил
    «Здравствуйте. Как давно это началось?» — спросил про давность несуществующей поломки.
    Замер: 200 хвостов из 200 на этой реплике брались из поломочного пула.
    """
    t = _cap(client_text or "")
    if _СИМПТОМ_RX.search(t):
        return False              # симптом сильнее глагола работы
    return bool(_РАБОТА_RX.search(t))


# Выход из затянувшегося троллинга (правка заказчика 04.08): три хода подряд не по делу
# и поломки так и нет — вежливо прощаемся. Считаем только ЯВНЫЙ офтоп: клиент, который
# молча уточняет цену или условия, троллем не считается и диалог не теряет.
TROLL_EXIT_TURNS = 3
# ⚠ ГОЛОСОВОЕ СООБЩЕНИЕ (24.08). Аудио бот не понимает — во всём мозге ноль строк про
# распознавание речи. До него доезжает только подпись вложения «📎 Голосовое сообщение»,
# и худший исход не в том, что он не расслышал, а в том, что он ОТВЕЧАЕТ ПО СМЫСЛУ,
# которого не слышал: клиент рассказал голосом про поломку, а бот пишет «расскажите, что
# случилось» или, того хуже, придумывает диагноз.
#
# Пока расшифровки нет, честный ответ дешевле и лучше выдумки. Роутер отвечает САМ, без
# вызова модели: голосовое без текста — это ноль информации, платить за неё нечем.
_ГОЛОСОВОЕ_RX = re.compile(r"голосов\w*\s*сообщ|voice\s*message|\bаудиосообщ", re.IGNORECASE)
#: строка целиком состоит из подписей вложений («📎 …», «🖼 …») и пробелов
_ТОЛЬКО_ВЛОЖЕНИЯ_RX = re.compile(r"^\s*(?:[📎🖼][^\n]*\n?)+\s*$")
# укорочено по живой норме (обучение 30.08): было 16 слов при живой медиане 4-10
ГОЛОСОВОЕ_ОТВЕТ = ("Голосовое тут не открывается. Напишите текстом или киньте номер — наберу")


def voice_only(text):
    """Реплика клиента — ТОЛЬКО голосовое, текста нет. Тогда отвечаем честно и без модели.

    ⚠ СМЕШАННЫЙ СЛУЧАЙ СЮДА НЕ ПОПАДАЕТ НАМЕРЕННО: если рядом с голосовым есть текст,
    вести разговор надо по тексту, а про голосовое модель предупредит сама (правило в
    playbook рядом с видео). Резать такой ход шаблоном значило бы терять сказанное.
    """
    t = (text or "").strip()
    if not t or not _ГОЛОСОВОЕ_RX.search(t):
        return False
    return bool(_ТОЛЬКО_ВЛОЖЕНИЯ_RX.match(t))


# ⚠ КЛИЕНТ ЗВОНИЛ (24.08). Отвечать ему «и номер ваш подскажите» — глухота: он уже пытается
# связаться голосом. Фраза НЕ обещает звонок от бота (звонить он не умеет), а честно передаёт
# человеку; срок реакции на call_request — 15 минут, и его сторожит channel._overdue_watch.
#: ⚠ ОТВЕТА НА ЗВОНОК БОЛЬШЕ НЕТ (слово владельца 26.08 по живому диалогу). Здесь стояло
#: «Вижу, вы звонили. Передам коллеге, он свяжется с вами в ближайшее время», и это ЛОМАЛО
#: ЛЕГЕНДУ: бот — частный мастер, работает сам, никакого «коллеги» у него нет и передать
#: он никому не может. Владелец дословно: «противоречит легенде, и на такое лучше не
#: отвечать». Ход уходит человеку молча — как и согласование: там решение тоже принимает
#: не бот, а черновик лишь создаёт видимость ответа, который диспетчер обязан вычитать.
#: Строка оставлена пустой намеренно, чтобы имя не потерялось из контракта.
ЗВОНИЛ_ОТВЕТ = ""

TROLL_EXIT_REPLY = ("Похоже, поломки у вас нет. Будет нужна помощь по технике — пишите, "
                    "всегда рад. Всего доброго!")


_TROLL_MARK_RX = re.compile(
    # смайлы (`))`, `:)`) НЕ считаются: живые клиенты так пишут массово, и
    # «Стиралка не отжимает))» закрывался как тролль (аудит 16.08)
    r"ха-?ха|хех|лол|ржу|\bору\b|смешн|прикол|шутк|шучу|давай\s+ещ|напиши\s+(?:про|мне|стих)|"
    r"подыгр|скучно|развлек", re.IGNORECASE)


def troll_exit(client_texts):
    """True — пора вежливо закрыть диалог: клиент написал N+ раз, поломки так и нет,
    и минимум две реплики — явный офтоп либо подкол. Требовать офтоп-маркер в КАЖДОЙ
    реплике нельзя: троллинг идёт вперемешку («напиши про холодильник хаха»), а тихий
    клиент, который просто уточняет условия, троллем не считается и диалог не теряет."""
    msgs = [t for t in (client_texts or []) if (t or "").strip()]
    if len(msgs) < TROLL_EXIT_TURNS:
        return False
    # ⚠ технику, названную ВНУТРИ подкола, заявкой не считаем: «ну напиши про холодильник
    # хаха» — это троллинг, а не заявка на холодильник. Но если про технику сказано всерьёз
    # (хоть в одной реплике без маркеров прикола) — это клиент, диалог не закрываем.
    serious = [t for t in msgs if not _TROLL_MARK_RX.search(_cap(t))]
    if problem_stated(" ".join(serious)):
        return False
    last = msgs[-TROLL_EXIT_TURNS:]
    marks = sum(1 for t in last
                if _OFFTOPIC_RX.search(_cap(t)) or _TROLL_MARK_RX.search(_cap(t)))
    return marks >= 2


# ⚠ САМАЯ КРУПНАЯ ОДИНОЧНАЯ ДОПИСКА ВО ВСЁМ БОТЕ (замер 24.08). Эта функция приписывала
# ОДНУ вшитую фразу «Что у вас случилось?» в 11,6% ходов — по объёму как вся воронка
# (11,8%), и вариантов у неё было ноль. То есть каждая девятая реплика бота заканчивалась
# слово в слово одинаково, на всех аккаунтах сразу. Это и есть та узнаваемость, ради
# которой заведены SOGLAS_POOL, PHONE_ASK_POOL и пулы следующего шага.
#
# ⚠ ВСЕ ВАРИАНТЫ СПРАШИВАЮТ ОДНО И ТО ЖЕ и все НЕЙТРАЛЬНЫ по предмету: «что случилось
# с техникой» звучит нелепо на мебели, сантехнике и монтаже, а МНЧ — пятая часть потока
# (разбор корпуса 12.08). И каждый обязан быть вопросом: по знаку «?» решает и сама эта
# функция, и воронка ниже по конвейеру.
ЧТО_СЛУЧИЛОСЬ_POOL = (
    "Что у вас случилось?",
    "Расскажите, что случилось?",
    "А что произошло?",
    "Опишите, что случилось?",
    "Что у вас произошло?",
    "Подскажите, в чём дело?",
)


def что_случилось_line(seed="", prior_bot=""):
    """Вариант вопроса «что случилось» по сиду — стабильно внутри диалога.

    ⚠ СТАБИЛЬНОСТЬ ОБОРАЧИВАЕТСЯ ДОСЛОВНЫМ ПОВТОРОМ, ЕСЛИ ВОПРОС ЗАДАЁТСЯ ДВАЖДЫ.
    Снимок владельца 26.08 (кулер): два хода подряд реплика бота заканчивалась слово в
    слово «Расскажите, что случилось?». Сид считается от диалога и внутри него не меняется,
    а истории эта функция не видела вовсе — ни `prior_bot`, ни подсказок. Круг чинится
    выше (бот больше не переспрашивает то, на что клиент ответил), но и здесь дословного
    повтора быть не должно: если вариант в этом диалоге уже звучал, берём следующий.
    """
    import hashlib as _h
    h = int(_h.sha256((seed or "").encode("utf-8")).hexdigest(), 16)
    было_ = (prior_bot or "").lower()
    n = len(ЧТО_СЛУЧИЛОСЬ_POOL)
    for сдвиг in range(n):
        вариант = ЧТО_СЛУЧИЛОСЬ_POOL[(h + сдвиг) % n]
        if вариант.lower().rstrip("?") not in было_:
            return вариант
    return ЧТО_СЛУЧИЛОСЬ_POOL[h % n]      # все шесть уже звучали — дальше молчать нельзя


def strip_logistics(reply, seed="", prior_bot=""):
    """Убирает из ответа вопрос логистики, оставляя человеческую часть.
    Если после вырезания вопроса по делу не осталось — добавляет вопрос о поломке."""
    r = reply or ""
    parts = re.split(r"(?<=[.!?…)])\s+|\n+", r)
    kept = [p for p in parts if p.strip() and not _LOGISTICS_ASK_RX.search(p)]
    out = " ".join(kept).strip()
    if not out:
        out = "Здравствуйте"
    if "?" not in out:
        out = out.rstrip(" .") + ". " + что_случилось_line(seed, prior_bot)
    return out


#: ⚠ 4-Й ЭТАП ВОЗРАЖЕНИЙ (регламент КП «Структура принятия заявки», урок 30.08).
#: Клиент выразил СОМНЕНИЕ уже после озвученной цены — «дорого», «подумаю», «поищу»:
#: этапы 1-3 пройдены, и регламент велит закрывать его БЕСПЛАТНЫМ выездом без оговорки
#: про 1000. Это единственный контекст, где «выезд бесплатный» на КП законен без
#: условия; на обычном вопросе цены гард ниже по-прежнему дописывает «при отказе 1000».
_ЭТАП4_СОМНЕНИЕ_RX = re.compile(
    r"дорого\b|дорогова|подума\w+|сомнева|не\s*уверен(?!\w*\s*(?:во|со|по)\s*времен)|поищ\w+|"
    r"посмотрю\s*(?:ещё|еще|друг)|сравн\w+|дешевле|навряд|вряд\s*ли|поспрашива",
    re.IGNORECASE)


def этап4_сомнение(client_text, prior_bot_text):
    """Клиент сомневается ПОСЛЕ того, как бот назвал цену: уступка 4-го этапа."""
    return bool(_ЭТАП4_СОМНЕНИЕ_RX.search(client_text or "")
                and re.search(r"\d{3,}|от\s*\d", prior_bot_text or ""))


def enforce_callouts(reply, client_text, prior_bot_text="", first_reply=False, white=False,
                     direction=""):
    """Дописывает обязательную озвучку цены, если тема хода явно про неё, а числа нет.

    Услуга детектится узкими regex (видеокарта+ремонт / приставка-бренд / пайка+ТВ), поэтому
    к моменту срабатывания задача УЖЕ однозначна — floor-цену называем сразу, в т.ч. на первом
    ходе (регламент: эти озвучки ОБЯЗАТЕЛЬНЫ). first_reply оставлен для совместимости, не влияет.
    client_text — вся речь клиента (тема могла всплыть раньше); prior_bot_text — прежние реплики
    бота (чтобы не повторять уже названную цену). Возвращает (reply, tags)."""
    r = reply or ""
    if not r.strip():
        return reply, []
    # к ОТКАЗУ цены не приклеиваем (озвучка после «не занимаюсь» выглядит абсурдно)
    if re.search(r"не\s*(?:работаю|занимаюсь|беру|делаю|смогу|помогу)|не\s*по\s*моей\s*части", r.lower()):
        return r, []
    ct = (client_text or "").lower()
    tags = []

    def has5000():
        return bool(_HAS_5000.search((r + " " + (prior_bot_text or "")).lower()))

    def has1500():
        return bool(_HAS_1500.search((r + " " + (prior_bot_text or "")).lower()))

    # ремонт видеокарты (именно ремонт, НЕ чистка/термопаста) → от 5000
    if _GPU_RX.search(ct) and _GPU_REPAIR_RX.search(ct) and not _GPU_CLEAN_RX.search(ct):
        if not has5000():
            r = _append_clause(r, "Ремонт видеокарты от 5000.")
            tags.append("gpu5000")
    # пайка / замена гнёзд ЖК-ТВ по плате → от 5000
    if _SOLDER_TV_RX.search(ct):
        if not has5000():
            r = _append_clause(r, "Такой ремонт по плате от 5000.")
            tags.append("solder5000")
    # ИГРОВЫЕ приставки → от 1500 на ЛЮБЫЕ работы. Регламент КП дословно: «чистка и НАСТРОЙКА
    # PS / Nintendo Switch / Steam Deck — обязательная озвучка "от 1500"; чистка Xbox — тоже».
    # Прежде настройка была исключена (от 500) — это расходилось с регламентом, аудит 30.07 поймал.
    # ТВ-приставки сюда не попадают: _CONSOLE_RX требует игровой бренд, и там настройка от 500.
    # ⚠ на согласуемых работах (ремонт/прошивка любой консоли, настройка Xbox) цену НЕ называем.
    # Но ЯВНАЯ просьба почистить/настроить сильнее слова-симптома: «почистить PS4, ШУМИТ» — это
    # чистка (берём, озвучка обязательна), а не ремонт.
    _cons_ask = _CONSOLE_CLEAN.search(ct) or _CONSOLE_SETUP.search(ct)
    if _CONSOLE_RX.search(ct) and not _CONSOLE_SOGLAS_RX.search(ct) \
            and (_cons_ask or not _CONSOLE_REPAIR.search(ct)):
        if not has1500():
            clean = _CONSOLE_CLEAN.search(ct)
            setup = _CONSOLE_SETUP.search(ct)
            if clean and setup:
                txt = "Чистка и настройка приставки от 1500."
            elif clean:
                txt = "Чистка приставки от 1500."
            elif setup:
                txt = "Настройка приставки от 1500."
            else:
                txt = "По приставке работы от 1500."
            r = _append_clause(r, txt)
            tags.append("console1500")
    low_all = (r + " " + (prior_bot_text or "")).lower()
    # ⚠ ИСПРАВЛЯЮЩИЙ ГАРД (красная команда 04.08.2026): дописывающие ветки выше молчат, если
    # модель УЖЕ сказала «бесплатн» — и тогда на ТВ/БТ/КП оставалось голое «выезд по городу
    # бесплатный» из МНЧ-мира. Это обещание, которого регламент не даёт: по этим направлениям
    # выезд бесплатен ТОЛЬКО при выполнении работ, при отказе — 1000. Кейс флапал между
    # прогонами хардкора («Давление по цене ТВ»), промптом не лечится — чиним детерминированно.
    _hookup_here = bool(_MNC_HOOKUP_RX.search(ct)) and not _BREAKDOWN_RX.search(ct)
    _mnc_topic = (_MNC_RX.search(ct) and _MNC_ACTION_RX.search(ct)) or _hookup_here
    # ⚠ 18.08, СЛОВО ВЛАДЕЛЬЦА: формула «при отказе 1000» — ТОЛЬКО КП. На БТ и МНЧ
    # выезд бесплатный, и дописывать условие туда нельзя: раньше этот гард «чинил»
    # верное «выезд бесплатный» на бытовой технике, превращая его в обещание с
    # оговоркой, которого регламент больше не даёт.
    # ⚠ ТВ ВЕРНУЛСЯ В КП (слово владельца 30.08, скрин Калуги): «выезд бесплатный»
    # на телевизоре — нарушение, условие про 1000 обязано дописываться и тут.
    _fee_topic = (direction == "kp" or _KP_RX.search(ct) or _TV_RX.search(ct)) \
        and not _mnc_topic and not _BT_BIG_RX.search(ct)
    # последняя реплика клиента — сомнение живёт в ней, а не во всей речи:
    # «дорого» из начала диалога не должно вечно выключать озвучку условий
    _посл_кл = (client_text or "").splitlines()[-1] if client_text else ""
    # ⚠ ОБА ПОРЯДКА СЛОВ. «Выезд будет бесплатным» и «бесплатный выезд» — одна и та же
    # формула, а прежний регекс знал только первый порядок: «сделаю бесплатный выезд»
    # проходило на КП без условия про 1000 задолго до этой правки.
    _беспл_выезд = re.search(r"выезд\w*[^.!?\n]{0,40}бесплатн|бесплатн\w*[^.!?\n]{0,20}выезд",
                             (r or "").lower())
    if _fee_topic and _беспл_выезд and этап4_сомнение(_посл_кл, prior_bot_text):
        tags.append("stage4_concession")           # уступка 4-го этапа: 1000 не дописываем
    elif _fee_topic and _беспл_выезд and "1000" not in (r or ""):
        # дописываем НЕДОСТАЮЩЕЕ условие, а не переписываем предложение: иначе вместе с фразой
        # про выезд терялся финал записи («Записал вас на завтра к 10:00»)
        r = _append_clause(r, "А если от работ откажетесь, это 1000 рублей.")
        tags.append("visit_fee_fix")

    # КП «выезд+диагностика 1000» — ТОЛЬКО на вопрос цены РЕМОНТА/поломки (правка заказчика:
    # без вопроса не навязывать; для УСТАНОВКИ/настройки диагностики нет — там цена работы).
    # ⚠ ТВ — ТОЖЕ ЗДЕСЬ (слово владельца 30.08, скрин Калуги: «За выезд ничего не берём»
    # на ремонте телевизора — «для КП строго нельзя так озвучивать. Выезд и диагностика
    # 1000 только так»). ТВ-заявка и в CRM уходит направлением КП (`_направление_тв`:
    # kp — первый и почти всегда единственный путь), а озвучка жила по правилу 18.08
    # «ТВ = БТ, выезд бесплатный» — клиенту обещали одно, заявку вели по-другому.
    # Симптомы ТВ добраны в словарь ремонта: «мерцает» из того же скрина.
    _kp_repair = re.search(r"не\s*включ|не\s*работает|не\s*грузит|слома|сгорел|тормоз|вис\w|глюч|"
                           r"синий\s*экран|артефакт|не\s*печатает|жу[её]т|полос|ошибк|ремонт|почин|чин\w|"
                           r"мерца|рябит|гаснет|мига|нет\s*(?:изображени|картинк|звук)|подсветк", ct)
    # на ПЕРВОМ ходе озвучку выезда не навязываем, даже если вопрос был в 1-м сообщении:
    # живые сперва квалифицируют («а что случилось?»), условия выезда — после ответов (аудит 29.07)
    if not tags and not first_reply and (_KP_RX.search(ct) or _TV_RX.search(ct)) and _kp_repair \
            and _visit_price_q(ct):
        if "1000" not in low_all and not re.search(r"\d{3,}", (prior_bot_text or "")):
            # ПОРЯДОК ОЗВУЧКИ (объявление КЦ 02.04.2026): сначала «бесплатно при работах»,
            # только потом условие про 1000 — клиент первым слышит про бесплатное.
            # Банк оболочек (правка заказчика 04.08 «заезженная пластинка»): смысл, порядок,
            # «бесплатн» и «1000» во всех вариантах одинаковы; выбор стабилен по тексту клиента.
            _kp1000 = (
                "Выезд и диагностика для вас бесплатны при выполнении работ, "
                "а если от работ откажетесь, это 1000 рублей.",
                "Выезд с диагностикой для вас бесплатно, если выполняю работу, "
                "а при отказе от работ — 1000 рублей.",
                "Выезд и диагностика бесплатно, когда работу делаем, "
                "только при отказе от работ будет 1000 рублей.",
                "Выезд и осмотр для вас бесплатные при выполнении работ, "
                "а откажетесь от работ — 1000 рублей.",
            )
            r = _append_clause(r, _kp1000[sum(ord(c) for c in ct) % len(_kp1000)])
            tags.append("kp1000")
    # ⚠ БЫТОВАЯ ТЕХНИКА: ВЫЕЗД БЕСПЛАТНЫЙ (уточнение владельца 18.08).
    # Формула «1000 при отказе» звучит ТОЛЬКО на КП. На БТ и МНЧ — выезд
    # бесплатный, без условий. Прежнее правило («на БТ как в КП») отменено
    # владельцем прямо: «Озвучка выезда 1000 есть только на КП направление,
    # на МНЧ и БТ выезд бесплатный».
    # ⚠ ПОДКЛЮЧЕНИЕ БТ К САНТЕХНИКЕ — ЭТО МНЧ, А НЕ БЫТОВАЯ ТЕХНИКА. Регламент, раздел «ВИДЫ РАБОТ
    # МНЧ → Подключение бытовой техники»: «принимаем подключение стиральных/посудомоечных/сушильных
    # машин, а также водонагревателей к сантехнике, услуга от 1000». Формула «1000 при отказе»
    # разрешена в МНЧ только партнёру 723, а мы 7 — здесь честное «выезд по городу бесплатный».
    # Без этого исключения слово «стиральная» тянуло ход в бытовую ветку, и клиент вместо
    # «выезд бесплатный» слышал «а если откажетесь — 1000». В корпусе 29 таких обращений.
    # ⚠ НАВЕС ТЕХНИКИ НА СТЕНУ — ТОЖЕ МНЧ (аудит регламента 18.08). «Телевизор
    # на стену повесить» + «выезд сколько стоит?» не получал ответа вовсе:
    # ветка МНЧ отсекалась словом «телевизор», а ветка БТ не срабатывала — нет
    # признаков поломки. Клиент спрашивал про деньги и оставался без ответа.
    _mnc_mount = bool(re.search(
        r"\b(?:повесить|навес|закреп|кронштейн|на\s+стен)\w*", ct, re.IGNORECASE)
    ) and not _BREAKDOWN_RX.search(ct)
    _mnc_hookup = (bool(_MNC_HOOKUP_RX.search(ct)) or _mnc_mount) and not _BREAKDOWN_RX.search(ct)
    # ⚠ ТВ ОТСЮДА УБРАН (слово владельца 30.08, отменяет правило 18.08 «ТВ = БТ»):
    # телевизор — направление КП и по заявке, и по озвучке, его выезд озвучивает
    # ветка _kp1000 выше. Здесь остаётся крупная бытовая — ей выезд бесплатный.
    if not tags and not first_reply and _BT_BIG_RX.search(ct) and not _TV_RX.search(ct) \
            and not _KP_RX.search(ct) and not _mnc_hookup and "запис" not in r.lower():
        if _visit_price_q(ct) and "бесплатн" not in low_all and "1000" not in low_all:
            _bt_free = (
                "Выезд по городу для вас бесплатный.",
                "Выезд бесплатный, платите только за работу.",
                "За выезд ничего не берём, только работа.",
            )
            r = _append_clause(r, _bt_free[sum(ord(c) for c in ct) % len(_bt_free)])
            tags.append("bt_free")
    # МНЧ (сантехника/электрика/мебель/навес): формулу 1000 регламент разрешает только партнёру 723,
    # а мы 7 — поэтому здесь честное «выезд по городу бесплатный».
    # ⚠ НУЖЕН ГЛАГОЛ-ДЕЙСТВИЕ, не просто существительное: хардкор-тест 31.07 поймал «глючит LG,
    # включается сам пока С РОЗЕТКИ не вытащить» — слово «розетка» тянуло сюда телевизор, и бот
    # обещал бесплатный выезд там, где по технике действует формула с 1000.
    if not tags and not first_reply and not _KP_RX.search(ct) and not _TV_RX.search(ct) \
            and "запис" not in r.lower() \
            and ((_MNC_RX.search(ct) and _MNC_ACTION_RX.search(ct) and not _BT_BIG_RX.search(ct))
                 or _mnc_hookup):
        if _visit_price_q(ct) and "бесплатн" not in low_all and "1000" not in low_all:
            # ⚠ «Белый» аккаунт — партнёр 723, и у него формула 1000 ОБЯЗАТЕЛЬНА и в МНЧ
            # (_WHITE_BLOCK в плейбуке; разрешение формулы в МНЧ только 723 — регламент).
            # Аудит 15.08: ветка клеила «бесплатный» не глядя на white — то есть бэкстоп,
            # существующий ради регламента, сам же его и нарушал на белом аккаунте.
            if white:
                # Порядок формулы — железный (нельзя наоборот, _PARTNER_BLOCK):
                # сначала «бесплатно при работах», потом «1000 при отказе».
                r = _append_clause(r, "Выезд и диагностика для вас бесплатны при выполнении "
                                      "работ, а если от работ откажетесь, это 1000 рублей.")
                tags.append("mnc1000_white")
            else:
                r = _append_clause(r, "Выезд по городу бесплатный.")
                tags.append("mnc_free")
    # последним: вычистить «диагностику» из формулы выезда, если задача — установка/подключение
    # (свои приклейки выше сюда не попадают: kp1000 требует признаков поломки)
    _r2 = _drop_diagnostics_on_install(r, ct)
    if _r2 != r:
        r, _ = _r2, tags.append("no_diag_install")
    # обязательные озвучки регламента, которые модель занижает (ванна/душевая от 8000; засор за метр)
    _r3 = _fix_reglament_floors(r, ct)
    if _r3 != r:
        r, _ = _r3, tags.append("reglament_floor")
    # «электрический или газовый?» у холодильника/стиралки — абсурд, палит бота
    _r4 = _drop_absurd_gas_q(r, ct)
    if _r4 != r:
        r, _ = _r4, tags.append("no_gas_q")
    # «белый» аккаунт 723: озвучка не ниже 1000 (ставки за метр/штуку не трогаем)
    if white:
        _r5 = raise_white_floor(r)
        if _r5 != r:
            r, _ = _r5, tags.append("white_floor")
    return r, tags


def _earlier(group, self_key, self_ts):
    """Сколько обращений этой группы (дубли) пришло РАНЬШЕ текущего."""
    me = (self_ts if self_ts is not None else float("inf"), self_key or "")
    c = 0
    for ts, k in (group or []):
        if k == self_key:
            continue
        if (ts, k) < me:
            c += 1
    return c


def classify(messages, dup_index=None, self_key=None, self_ts=None, engage_n=5):
    """Решение пре-фильтра для диалога.

    dup_index: {"text_groups": {norm: [(ts,key)...]}, "phone_groups": {phone: [(ts,key)...]}}
    engage_n: \bсколько обращений одного клиента (по тексту) ведём, прежде чем сливать.
    Возвращает {kind, reason, draft} или None (engage).
    """
    client_msgs = [m.get("text", "") for m in messages if m.get("role") == "client"]
    if not client_msgs:
        return None
    all_client = " \n".join(client_msgs)

    # 1) отказ по сути обращения (газ/матрица/замки/скупка)
    ref = check_refuse(all_client)
    if ref:
        return ref
    if not dup_index:
        return None

    # 2) телефон уже обращался раньше / активная заявка — слив сразу
    pg = dup_index.get("phone_groups", {})
    for ph in phones_in(all_client):
        if _earlier(pg.get(ph), self_key, self_ts) >= 1:
            return {"kind": "deflect", "sub": "dup_phone",
                    "reason": "этот клиент уже обращался (тот же телефон)",
                    "draft": DEFLECT_REPLY}
        if active_zayavka(ph):
            return {"kind": "deflect", "sub": "active_zayavka",
                    "reason": "по телефону уже есть активная заявка в базе",
                    "draft": DEFLECT_REPLY}

    # 3) копипаст на много объявлений: первые engage_n ведём, дальше — слив
    nt = norm_text(client_msgs[0])
    if len(nt) >= 25:
        grp = dup_index.get("text_groups", {}).get(nt)
        if _earlier(grp, self_key, self_ts) >= engage_n:
            return {"kind": "deflect", "sub": "dup_text",
                    "reason": "обращение уже вели на %d+ объявлениях" % engage_n,
                    "draft": DEFLECT_REPLY}
    return None
